import { Book } from "@/lib/types";

export const numbers: Book = {
  id: "numbers",
  name: "4. Mose (Numeri)",
  shortName: "4. Mose",
  testament: "old",
  introduction: `Israel auf dem Weg ins verheißene Land\n**Das vierte Buch Mose** wird auch \"Numeri\", d.h. \"Zählungen\" genannt. Es bekam seinen Namen, weil es von zwei Volkszählungen Israels berichtet und eine Menge Statistiken und Listen enthält. Man hätte es aber auch \"das Murren des Volkes\" nennen können, denn es ist die traurige Geschichte von Klagen, Unzufriedenheit und göttlichem Gericht. Das Buch umfasst die 38 Jahre der Geschichte Israels, in denen das Volk in der Wüste Sinai umherzog, und hat deshalb in der hebräischen Bibel den Namen \"Bemidbar\", \"in der Wüste\", nach dem fünften Wort im ersten Kapitel. Die ganze Schilderung der Wüstenwanderung geht offensichtlich auf einen Augenzeugen zurück. Wer anders als Mose könnte dafür in Betracht kommen? Er müsste das Buch dann im Jahr 1406 v.Chr., einige Zeit vor seinem Tod, vollendet haben.\n****Wie Israel die 40 Jahre in der Wüste verbringt, immer wieder gegen Gott rebelliert und immer wieder von Gott angenommen wird.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Jahwe redete zu Mose. Es geschah in der Wüste Sinai, im Zelt der Gottesbegegnung. Ein Jahr und ein Monat waren seit dem Auszug aus Ägypten vergangen.* Er sagte:", heading: "1-10: Reisevorbereitung am Sinai\nDie Volkszählung (1-4)\nDie Volks- und Heeresordnung am Sinai", footnotes: ["Jahr ... vergangen. Nach biblischer Chronologie geschah das im April 1445 v.Chr."] },
      { number: 2, text: "\"Ermittelt die Gesamtzahl der Gemeinschaft der Israeliten, geordnet nach ihren Sippen und Familien, Name für Name, Kopf für Kopf, alle Männer," },
      { number: 3, text: "die zwanzig Jahre und älter sind, alle wehrfähigen Israeliten. Mustert sie für ihre Heeresverbände, du und Aaron." },
      { number: 4, text: "Und von jedem Stamm soll euch ein Mann dabei helfen, der ein Sippenoberhaupt ist." },
      { number: 5, text: "Folgende Männer sollen euch beistehen: aus dem Stamm Ruben Elizur Ben-Schedëur," },
      { number: 6, text: "aus dem Stamm Simeon Schelumiël Ben-Zurischaddai," },
      { number: 7, text: "aus dem Stamm Juda Nachschon Ben-Amminadab," },
      { number: 8, text: "aus dem Stamm Issachar Netanel Ben-Zuar," },
      { number: 9, text: "aus dem Stamm Sebulon Eliab Ben-Helon," },
      { number: 10, text: "aus den Stämmen Josefs für Efraïm Elischama Ben-Ammihud und für Manasse Gamliël Ben-Pedazur," },
      { number: 11, text: "aus dem Stamm Benjamin Abidan Ben-Gidoni," },
      { number: 12, text: "aus dem Stamm Dan Ahiëser Ben-Ammischaddai," },
      { number: 13, text: "aus dem Stamm Ascher Pagiël Ben-Ochran," },
      { number: 14, text: "aus dem Stamm Gad Eljasaf Ben-Dëuël," },
      { number: 15, text: "aus dem Stamm Naftali Ahira Ben-Enan.\"" },
      { number: 16, text: "Das waren die Berufenen der Gemeinschaft, die Fürsten der Stämme ihrer Väter, die Häupter der Heereseinheiten Israels." },
      { number: 17, text: "Mose und Aaron ließen diese namentlich bestimmten Männer zu sich kommen" },
      { number: 18, text: "und riefen die ganze Gemeinschaft am 1. Mai* zusammen. Da wurden die Männer in die Geburtsverzeichnisse nach ihren Sippen und Familien eingetragen, Name für Name, Kopf für Kopf, und zwar alle, die zwanzig Jahre und älter waren.", footnotes: ["Mai. Wörtlich: des 2. Monats. Zum Datum siehe unter Schaltmonat im Vorwort des Übersetzers."] },
      { number: 19, text: "So hatte Jahwe es Mose befohlen. Und so musterte er sie in der Wüste Sinai." },
      { number: 20, text: "Zuerst kamen die Nachkommen Rubens, des Erstgeborenen Israels: Man ermittelte ihre Geschlechterfolge nach Sippen und Familien, Name für Name, Kopf für Kopf, und zwar alle, die zwanzig Jahre und älter und wehrfähig waren." },
      { number: 21, text: "Vom Stamm Ruben waren es 46 500 Mann." },
      { number: 22, text: "Dann kamen die Nachkommen Simeons: Man ermittelte ihre Geschlechterfolge nach Sippen und Familien, Name für Name, Kopf für Kopf, und zwar alle, die zwanzig Jahre und älter und wehrfähig waren." },
      { number: 23, text: "Vom Stamm Simeon waren es 59 300 Mann." },
      { number: 24, text: "Dann die Nachkommen Gads: Man ermittelte ihre Geschlechterfolge nach Sippen und Familien, Name für Name, Kopf für Kopf, und zwar alle, die zwanzig Jahre und älter und wehrfähig waren." },
      { number: 25, text: "Vom Stamm Gad waren es 45 650 Mann." },
      { number: 26, text: "Die Nachkommen Judas: Man ermittelte ihre Geschlechterfolge nach Sippen und Familien, Name für Name, Kopf für Kopf, und zwar alle, die zwanzig Jahre und älter und wehrfähig waren." },
      { number: 27, text: "Vom Stamm Juda waren es 74 600 Mann." },
      { number: 28, text: "Die Nachkommen Issachars: Man ermittelte ihre Geschlechterfolge nach Sippen und Familien, Name für Name, Kopf für Kopf, und zwar alle, die zwanzig Jahre und älter und wehrfähig waren." },
      { number: 29, text: "Vom Stamm Issachar waren es 54 400 Mann." },
      { number: 30, text: "Die Nachkommen Sebulons: Man ermittelte ihre Geschlechterfolge nach Sippen und Familien, Name für Name, Kopf für Kopf, und zwar alle, die zwanzig Jahre und älter und wehrfähig waren." },
      { number: 31, text: "Vom Stamm Sebulon waren es 57 400 Mann." },
      { number: 32, text: "Von den Söhnen Josefs kamen die Nachkommen Efraïms. Man ermittelte ihre Geschlechterfolge nach Sippen und Familien, Name für Name, Kopf für Kopf, und zwar alle, die zwanzig Jahre und älter und wehrfähig waren." },
      { number: 33, text: "Vom Stamm Efraïm waren es 40 500 Mann." },
      { number: 34, text: "Und dann die Nachkommen Manasses: Man ermittelte ihre Geschlechterfolge nach Sippen und Familien, Name für Name, Kopf für Kopf, und zwar alle, die zwanzig Jahre und älter und wehrfähig waren." },
      { number: 35, text: "Vom Stamm Manasse waren es 32 200 Mann." },
      { number: 36, text: "Dann kamen die Nachkommen Benjamins. Man ermittelte ihre Geschlechterfolge nach Sippen und Familien, Name für Name, Kopf für Kopf, und zwar alle, die zwanzig Jahre und älter und wehrfähig waren." },
      { number: 37, text: "Vom Stamm Benjamin waren es 35 400 Mann." },
      { number: 38, text: "Die Nachkommen Dans: Man ermittelte ihre Geschlechterfolge nach Sippen und Familien, Name für Name, Kopf für Kopf, und zwar alle, die zwanzig Jahre und älter und wehrfähig waren." },
      { number: 39, text: "Vom Stamm Dan waren es 62 700 Mann." },
      { number: 40, text: "Die Nachkommen Aschers: Man ermittelte ihre Geschlechterfolge nach Sippen und Familien, Name für Name, Kopf für Kopf, und zwar alle, die zwanzig Jahre und älter und wehrfähig waren." },
      { number: 41, text: "Vom Stamm Ascher waren es 41 500 Mann." },
      { number: 42, text: "Die Nachkommen Naftalis: Man ermittelte ihre Geschlechterfolge nach Sippen und Familien, Name für Name, Kopf für Kopf, und zwar alle, die zwanzig Jahre und älter und wehrfähig waren." },
      { number: 43, text: "Vom Stamm Naftali waren es 53 400 Mann." },
      { number: 44, text: "Das waren die von Mose, Aaron und den Fürsten Israels gemusterten wehrfähigen Israeliten nach ihren Familien" },
      { number: 45, text: "und zwar alle, die zwanzig Jahre und älter waren." },
      { number: 46, text: "Ihre Gesamtzahl betrug 603 550." },
      { number: 47, text: "Der Stamm Levi wurde nicht mit den anderen Stämmen erfasst.", heading: "Die Sonderstellung der Leviten" },
      { number: 48, text: "Jahwe hatte nämlich zu Mose gesagt:" },
      { number: 49, text: "\"Nur den Stamm Levi sollst du nicht mit den Israeliten mustern und zählen." },
      { number: 50, text: "Die Leviten sollst du mit der Sorge für die Wohnung des Bundesgesetzes beauftragen und für alles, was dazu gehört. Sie sollen für die Wohnung und all ihr Gerät sorgen, sie tragen und sich um die Wohnung herum lagern." },
      { number: 51, text: "Wenn die Wohnung weiterzieht, sollen die Leviten sie abbauen, und wenn die Wohnung Halt macht, sollen die Leviten sie aufbauen. Jeder Unbefugte, der sich ihr nähert, soll getötet werden." },
      { number: 52, text: "Die übrigen Israeliten sollen sich bei ihrer Heeresabteilung um ihr Feldzeichen lagern." },
      { number: 53, text: "Doch die Leviten sollen ihr Lager rings um die Wohnung des Bundesgesetzes herum aufschlagen, damit nicht mein Zorn über die Menge der Israeliten kommt. Und die Leviten sollen ihren Dienst an der Wohnung verrichten.\"" },
      { number: 54, text: "Die Israeliten machten alles so, wie Jahwe es Mose befohlen hatte." },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Jahwe sagte zu Mose und Aaron:", heading: "Die Lagerordnung" },
      { number: 2, text: "\"Die Israeliten sollen ihre Zelte bei ihren Verbänden, den Zeichen ihrer Familien, aufschlagen, und zwar rings um das Zelt der Gottesbegegnung herum und mit Blick darauf.\"" },
      { number: 3, text: "Vorn, im Osten, hatten die Verbände des Lagers von Juda ihren Platz. Fürst der Nachkommen Judas war Nachschon Ben-Amminadab." },
      { number: 4, text: "Sein Heer zählte 74 600 Mann." },
      { number: 5, text: "Neben ihm sollte der Stamm Issachar sein Lager aufschlagen. Fürst der Nachkommen Issachars war Netanel Ben-Zuar." },
      { number: 6, text: "Sein Heer zählte 54 400 Mann." },
      { number: 7, text: "Dann kam der Stamm Sebulon mit seinem Fürsten Eliab Ben-Helon." },
      { number: 8, text: "Sein Heer zählte 57 400 Mann." },
      { number: 9, text: "Zum Lager Juda gehörten also insgesamt 186 400 Mann. Diese Abteilung sollte beim Weitermarsch zuerst aufbrechen." },
      { number: 10, text: "Auf der Südseite hatten die Verbände des Lagers von Ruben ihren Platz. Fürst der Nachkommen Rubens war Elizur Ben-Schedëur." },
      { number: 11, text: "Sein Heer zählte 46 500 Mann." },
      { number: 12, text: "Neben ihm schlug der Stamm Simeon sein Lager auf. Fürst der Nachkommen Simeons war Schelumiël Ben-Zurischaddai." },
      { number: 13, text: "Sein Heer zählte 59 300 Mann." },
      { number: 14, text: "Dann kam der Stamm Gad mit seinem Fürsten Eljasaf Ben-Dëuël." },
      { number: 15, text: "Sein Heer zählte 45 650 Mann." },
      { number: 16, text: "Zum Lager Ruben gehörten also insgesamt 151 450 Mann. Diese Abteilung sollte beim Weitermarsch als zweite aufbrechen." },
      { number: 17, text: "Dann sollte das Zelt der Gottesbegegnung aufbrechen, das Lager der Leviten in der Mitte der anderen Lager. Wie sie ihre Zelte aufgeschlagen hatten, so sollten sie aufbrechen, jeder an seiner Stelle, Feldzeichen um Feldzeichen." },
      { number: 18, text: "Auf der Westseite hatten die Verbände des Lagers von Efraïm ihren Platz. Fürst der Nachkommen Efraïms war Elischama Ben-Ammihud." },
      { number: 19, text: "Sein Heer zählte 40 500 Mann." },
      { number: 20, text: "Neben ihm schlug der Stamm Manasse sein Lager auf. Fürst der Nachkommen Manasses war Gamliël Ben-Pedazur." },
      { number: 21, text: "Sein Heer zählte 32 200 Mann." },
      { number: 22, text: "Dann kam der Stamm Benjamin mit seinem Fürsten Abidan Ben-Gidoni." },
      { number: 23, text: "Sein Heer zählte 35 400 Mann." },
      { number: 24, text: "Zum Lager Efraïm gehörten also insgesamt 108 100 Mann. Diese Abteilung sollte beim Weitermarsch als dritte aufbrechen." },
      { number: 25, text: "Auf der Nordseite hatten die Verbände des Lagers von Dan ihren Platz. Fürst der Nachkommen Dans war Ahiëser Ben-Ammischaddai." },
      { number: 26, text: "Sein Heer zählte 62 700 Mann." },
      { number: 27, text: "Neben ihm schlug der Stamm Ascher sein Lager auf. Fürst der Nachkommen Aschers war Pagiël Ben-Ochran." },
      { number: 28, text: "Sein Heer zählte 41 500 Mann." },
      { number: 29, text: "Dann kam der Stamm Naftali mit seinem Fürsten Ahira Ben-Enan." },
      { number: 30, text: "Sein Heer zählte 53 400 Mann." },
      { number: 31, text: "Zum Lager Dan gehörten also insgesamt 157 600 Mann. Diese Abteilung sollte beim Weitermarsch zuletzt aufbrechen." },
      { number: 32, text: "Das waren die Gemusterten der Israeliten nach ihren Familien. Die Gesamtzahl aller Verbände aller Lager betrug 603 550." },
      { number: 33, text: "Aber die Leviten wurden nicht mit den Israeliten gemustert, wie Jahwe es Mose befohlen hatte." },
      { number: 34, text: "Die Israeliten machten alles genauso, wie Jahwe es Mose befohlen hatte. Sie schlugen ihr Lager nach ihren Verbänden auf und brachen auf, jeder bei seiner Sippe mit seiner Familie." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Es folgt das Verzeichnis der Stammesverwandten von Aaron und Mose, die zu der Zeit lebten, als Jahwe auf dem Berg Sinai mit Mose redete.", heading: "Die Musterung der Leviten" },
      { number: 2, text: "Aarons Söhne waren Nadab, der Erstgeborene, dann Abihu, Eleasar und Itamar." },
      { number: 3, text: "Sie waren durch Salbung zu Priestern geweiht und eingesetzt worden." },
      { number: 4, text: "Nadab und Abihu starben vor Jahwe, als sie ihm in der Wüste Sinai ein unerlaubtes Feueropfer brachten. Sie hatten keine Söhne. So versahen Eleasar und Itamar den priesterlichen Dienst unter Aufsicht ihres Vaters Aaron." },
      { number: 5, text: "Jahwe sagte zu Mose:" },
      { number: 6, text: "\"Lass die Männer des Stammes Levi herkommen und vor den Priester Aaron treten. Sie sollen seine Helfer sein." },
      { number: 7, text: "Sie sollen ihm und der ganzen Gemeinschaft vor dem Zelt der Gottesbegegnung dienen und die notwendigen Arbeiten an der Wohnung verrichten." },
      { number: 8, text: "Sie sollen alle Gegenstände, die zum Zelt der Gottesbegegnung gehören, in Ordnung halten und stellvertretend für die Israeliten die Arbeit an der Wohnung verrichten." },
      { number: 9, text: "Du sollst die Leviten Aaron und seinen Söhnen übergeben, denn sie sind ihnen von den übrigen Israeliten gegeben* worden.", footnotes: ["gegeben. Wörtlich: \"Gegebene\". Dieser Begriff wurde später zur Bezeichnung für die Tempeldiener."] },
      { number: 10, text: "Aaron und seine Nachkommen sollst du mit dem Priesterdienst beauftragen. Jeder Unbefugte, der sich das anmaßt, soll getötet werden.\"" },
      { number: 11, text: "Jahwe sagte weiter zu Mose:" },
      { number: 12, text: "\"Pass auf! Ich selbst habe die Leviten anstelle eurer erstgeborenen Söhne für mich ausgesondert. Sie gehören mir." },
      { number: 13, text: "Denn jede Erstgeburt gehört mir. Als ich im Land Ägypten jede Erstgeburt tötete, habe ich mir alles vorbehalten, was zuerst aus dem Mutterschoß kommt. Es gehört mir, Jahwe.\"" },
      { number: 14, text: "In der Wüste Sinai sagte Jahwe noch zu Mose:" },
      { number: 15, text: "\"Mustere die Nachkommen Levis nach ihren Familien und Sippen, und zwar alle männlichen, die älter als einen Monat sind.\"" },
      { number: 16, text: "Mose tat, was Jahwe ihm befohlen hatte." },
      { number: 17, text: "Die Söhne Levis waren Gerschon, Kehat und Merari." },
      { number: 18, text: "Die Söhne Gerschons waren Libni und Schimi," },
      { number: 19, text: "die Söhne Kehats Amram, Jizhar, Hebron und Usiël," },
      { number: 20, text: "und die Söhne Meraris Machli und Muschi. Das sind die Sippen der Leviten nach ihren Familien geordnet." },
      { number: 21, text: "Zu Gerschon gehörten die Sippen Libni und Schimi." },
      { number: 22, text: "Die Gesamtzahl ihrer männlichen Angehörigen, die älter waren als einen Monat, betrug 7500." },
      { number: 23, text: "Die Sippen der Gerschoniten schlugen ihr Lager hinter der Wohnung im Westen auf." },
      { number: 24, text: "Ihr Oberhaupt war Eljasaf Ben-Laël." },
      { number: 25, text: "Die Gerschoniten hatten beim Zelt der Gottesbegegnung für die Wohnung und das Zeltdach zu sorgen, für seine Decke und den Vorhang am Eingang zum Zelt," },
      { number: 26, text: "für die Behänge des Vorhofs, der die Wohnung und den Altar umgibt, und die dazugehörenden Seile, und für den Vorhang am Eingang des Vorhofs." },
      { number: 27, text: "Zu Kehat gehörten die Sippen Amram, Jizhar, Hebron und Usiël." },
      { number: 28, text: "Die Gesamtzahl ihrer männlichen Angehörigen, die älter als einen Monat und für den Dienst im Heiligtum bestimmt waren, betrug 8600." },
      { number: 29, text: "Die Sippen der Kehatiten schlugen ihr Lager an der Südseite der Wohnung auf." },
      { number: 30, text: "Ihr Oberhaupt war Elizafan Ben-Usiël." },
      { number: 31, text: "Sie hatten für die Lade zu sorgen, für den Tisch, den Leuchter, die Altäre und die heiligen Geräte, mit denen man den Dienst versieht, sowie den Vorhang, samt aller Arbeit daran." },
      { number: 32, text: "Über den Oberhäuptern der Leviten stand der Priester Eleasar Ben-Aaron. Er hatte die Aufsicht über alle, die mit einer Aufgabe beim Heiligtum betraut waren." },
      { number: 33, text: "Zu Merari gehörten die Sippen Machli und Muschi." },
      { number: 34, text: "Die Gesamtzahl ihrer männlichen Angehörigen, die älter waren als einen Monat, betrug 6200." },
      { number: 35, text: "Ihr Oberhaupt war Zuriël Ben-Abihajil. Sie schlugen ihr Lager an der Nordseite der Wohnung auf." },
      { number: 36, text: "Die Merariten hatten für die Bretter der Wohnung zu sorgen, für ihre Riegel, Säulen, Bodenplatten und alles weitere Zubehör, samt aller Arbeit daran," },
      { number: 37, text: "ebenso für die Säulen des Vorhofs ringsum und ihre Sockel, Pflöcke und Seile." },
      { number: 38, text: "An der Ostseite der Wohnung, vor dem Zelt der Gottesbegegnung, schlugen Mose, Aaron und dessen Söhne ihr Lager auf. Sie erfüllten ihre Aufgabe für das Heiligtum, wie es den Israeliten aufgetragen war. Doch jeder andere, der sich das anmaßte, musste getötet werden." },
      { number: 39, text: "Die Gesamtzahl der Leviten, die Mose und Aaron nach Jahwes Befehl musterten, alle männlichen Personen, die älter als einen Monat waren, betrug 22.000." },
      { number: 40, text: "Jahwe sagte zu Mose: \"Mustere alle männlichen Erstgeborenen der Israeliten, die älter als einen Monat sind und nimm ihre Zahl auf." },
      { number: 41, text: "Dann beanspruche für mich die Leviten anstelle aller Erstgeborenen bei den Israeliten – ich bin Jahwe – und das Vieh der Leviten anstelle aller erstgeborenen Tiere der Israeliten.\"" },
      { number: 42, text: "Da musterte Mose alle Erstgeborenen bei den Israeliten, wie Jahwe es ihm befohlen hatte" },
      { number: 43, text: "und kam auf eine Gesamtzahl von 22.273." },
      { number: 44, text: "Da sagte Jahwe zu Mose:" },
      { number: 45, text: "\"Beanspruche die Leviten anstelle aller Erstgeborenen bei den Israeliten und das Vieh der Leviten anstelle ihres Viehs. Die Leviten sollen mir gehören, ich bin Jahwe!" },
      { number: 46, text: "Zur Auslösung der 273 Erstgeborenen, die die Zahl der Leviten übersteigen," },
      { number: 47, text: "sollst du pro Kopf je fünf Silberstücke nehmen, die dem Gewicht des Heiligtums entsprechen, zwölf Gramm das Stück*.", footnotes: ["zwölf Gramm das Stück. Wörtlich: zwanzig Gera der Schekel. Nach archäologischen Funden kann das Durchschnittsgewicht eines Schekel mit 11,5 Gramm angenommen werden."] },
      { number: 48, text: "Das Geld sollst du zur Auslösung der überzähligen Israeliten Aaron und seinen Söhnen geben.\"" },
      { number: 49, text: "Mose nahm das Lösegeld von den Überzähligen, die durch die Leviten nicht ausgelöst waren." },
      { number: 50, text: "Von den Erstgeborenen der Israeliten nahm er das Geld, 1 365 Silberstücke nach dem Gewicht des Heiligtums." },
      { number: 51, text: "Mose gab das Lösegeld Aaron und seinen Söhnen, wie Jahwe es ihm befohlen hatte." },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Jahwe sagte zu Mose und Aaron:", heading: "Die Kehatiten" },
      { number: 2, text: "\"Ermittelt die Zahl der Kehatiten unter den Leviten nach ihren Sippen und Familien." },
      { number: 3, text: "Es geht um alle, die zwischen 30 und 50 Jahre alt und zum Dienst am Zelt der Gottesbegegnung verpflichtet sind." },
      { number: 4, text: "Sie sind für das Höchstheilige verantwortlich." },
      { number: 5, text: "Wenn das Lager weiterzieht, sollen Aaron und seine Söhne hineingehen, den verhüllenden Vorhang abnehmen und über die Lade mit dem Bundesgesetz decken." },
      { number: 6, text: "Dann sollen sie eine Decke aus Tachasch-Leder* darüber ausbreiten und oben darauf ein Tuch aus violettem Purpur. Zum Schluss sollen sie die Stangen anbringen.", footnotes: ["Tachasch-Leder. Weichgegerbtes Leder aus Tümmler- oder Dachshäuten."] },
      { number: 7, text: "Auch über den Tisch, auf dem das geweihte Brot ausgelegt ist, sollen sie ein Tuch aus violettem Purpur ausbreiten und darauf die Schüsseln und Schalen, die Opferschalen und die Kannen zum Trankopfer stellen. Auch das beständige Brot soll darauf liegen." },
      { number: 8, text: "Darüber sollen sie ein Tuch aus Karmesin ausbreiten und dies mit einer Decke aus Tachasch-Leder bedecken. Zum Schluss sollen sie die Stangen anbringen." },
      { number: 9, text: "Dann sollen sie den Leuchter samt seinen Lichtschalen in ein Tuch aus violettem Purpur einhüllen, außerdem die Dochtscheren, Feuerbecken und Ölgefäße, die dazugehören." },
      { number: 10, text: "Dann müssen sie alles zusammen in eine Decke aus Tachasch-Leder wickeln und es auf die Trage legen." },
      { number: 11, text: "Auch über den goldenen Altar sollen sie ein Tuch aus violettem Purpur ausbreiten, eine Decke aus Tachasch-Leder darüberlegen und seine Stangen anbringen." },
      { number: 12, text: "Alle anderen Geräte, die man zum Dienst im Heiligtum braucht, sollen sie in ein Tuch aus violettem Purpur hüllen, dann in eine Decke aus Tachasch-Leder einwickeln und es auf die Trage legen." },
      { number: 13, text: "Dann sollen sie den Altar von der Fettasche* reinigen und ein Tuch aus rotem Purpur darüber ausbreiten.", footnotes: ["Fettasche bildet sich aus verbrannten Holz- und Fettstücken."] },
      { number: 14, text: "Auf dieses Tuch sollen sie alle Geräte legen, die zum Dienst am Altar gebraucht werden: die Feuerbecken, Fleischgabeln, Schaufeln und Sprengschalen. Schließlich müssen sie eine Decke aus Tachasch-Leder darüber decken und seine Stangen anbringen." },
      { number: 15, text: "Erst wenn Aaron und seine Söhne beim Aufbruch des Lagers das Heiligtum und alle seine Gegenstände vollständig bedeckt haben, sollen die Nachkommen Kehats kommen, um sie zu tragen. Sie dürfen das Heilige nicht berühren, sonst müssen sie sterben. Das alles haben die Kehatiten vom Zelt der Gottesbegegnung zu tragen." },
      { number: 16, text: "Eleasar, der Sohn des Priesters Aaron, hat die Aufsicht über das Öl für das Licht, die Weihrauchmischung, das regelmäßige Speisopfer und das Salböl, die Verantwortung für die ganze Wohnung und alles, was darin ist, das Heiligtum und alle seine Gegenstände.\"" },
      { number: 17, text: "Jahwe sagte zu Mose und Aaron:" },
      { number: 18, text: "\"Ihr müsst Sorge dafür tragen, dass der Stamm der Kehatitensippen unter den Leviten nicht ausgerottet wird." },
      { number: 19, text: "Ihr müsst Folgendes für sie tun, damit sie am Leben bleiben und nicht sterben, wenn sie in die Nähe des Höchstheiligen kommen: Aaron und seine Söhne sollen hineingehen und jedem Einzelnen zuweisen, was er zu tun und zu tragen hat." },
      { number: 20, text: "Sie dürfen nicht von sich aus hineingehen, damit sie nicht einen Augenblick lang das Heilige sehen. Sonst müssen sie sterben.\"" },
      { number: 21, text: "Jahwe sagte zu Mose:", heading: "Die Gerschoniten" },
      { number: 22, text: "\"Ermittle auch die Zahl der Gerschoniten nach ihren Sippen und Familien." },
      { number: 23, text: "Es geht um alle, die zwischen 30 und 50 Jahre alt und zum Dienst am Zelt der Gottesbegegnung verpflichtet sind." },
      { number: 24, text: "Die Gerschoniten haben Folgendes zu tun und zu tragen:" },
      { number: 25, text: "Sie sollen die Zeltbahnen der Wohnung und das Zelt tragen, seine Decke und die Tachasch-Decke, die darüber liegt, und den Vorhang vom Eingang des Zeltes," },
      { number: 26, text: "dazu die Behänge des Vorhofs, der die Wohnung und den Altar umgibt, den Vorhang vom Eingang, die Seile und alle Arbeitsgeräte. Sie sollen alles tun, was dabei anfällt." },
      { number: 27, text: "Die Arbeit der Gerschoniten soll auf Anordnung Aarons und seiner Söhne hin geschehen. Sie sollen sie anweisen, was sie zu tragen und zu tun haben.\"" },
      { number: 28, text: "Das ist die Arbeit der Gerschoniten am Zelt der Gottesbegegnung, die unter der Aufsicht des Priesters Itamar Ben-Aaron getan werden soll." },
      { number: 29, text: "Auch die Merariten sollst du nach ihren Sippen und Familien mustern.", heading: "Die Merariten" },
      { number: 30, text: "Es geht um alle, die zwischen 30 und 50 Jahre alt und zum Dienst am Zelt der Gottesbegegnung verpflichtet sind." },
      { number: 31, text: "Bei ihrem Dienst am Zelt haben sie die Bretter der Wohnung zu tragen, ihre Riegel, Säulen und Bodenplatten," },
      { number: 32, text: "die Säulen des Vorhofs ringsum, ihre Sockel, Pflöcke und Seile und alle Arbeitsgeräte dazu. Ihr sollt ihnen die Gegenstände, die sie zu tragen haben, mit Namen einzeln zuweisen.\"" },
      { number: 33, text: "Das ist die Arbeit der Merariten am Zelt der Gottesbegegnung, die unter der Aufsicht des Priesters Itamar Ben-Aaron getan werden soll." },
      { number: 34, text: "Mose, Aaron und die Oberhäupter der Gemeinschaft musterten nun die Kehatiten nach ihren Sippen und Familien", heading: "Die Zahl der dienstfähigen Leviten" },
      { number: 35, text: "und zwar alle, die zwischen 30 und 50 Jahre alt und zum Dienst am Zelt der Gottesbegegnung verpflichtet waren." },
      { number: 36, text: "Es waren 2 750 Männer" },
      { number: 37, text: "von den Sippen der Kehatiten, die am Zelt der Gottesbegegnung dienten und nach Anordnung Jahwes an Mose von Mose und Aaron gemustert wurden." },
      { number: 38, text: "Von den Gerschoniten wurden nach ihren Sippen und Familien alle gemustert," },
      { number: 39, text: "die zwischen 30 und 50 Jahre alt und zum Dienst am Zelt der Gottesbegegnung verpflichtet waren." },
      { number: 40, text: "Es waren 2 630 Männer" },
      { number: 41, text: "von den Sippen der Gerschoniten, die am Zelt der Gottesbegegnung dienten und nach Anordnung Jahwes von Mose und Aaron gemustert wurden." },
      { number: 42, text: "Von den Merariten wurden nach ihren Sippen und Familien alle gemustert," },
      { number: 43, text: "die zwischen 30 und 50 Jahre alt und zum Dienst am Zelt der Gottesbegegnung verpflichtet waren." },
      { number: 44, text: "Es waren 3 200 Männer" },
      { number: 45, text: "von den Sippen der Merariten, die nach Anordnung Jahwes an Mose von Mose und Aaron gemustert wurden." },
      { number: 46, text: "Die Gesamtzahl der gemusterten Leviten" },
      { number: 47, text: "zwischen 30 und 50 Jahren, die zum Dienst am Zelt der Gottesbegegnung verpflichtet wurden," },
      { number: 48, text: "war 8 580." },
      { number: 49, text: "Nach dem Befehl Jahwes betraute man jeden von ihnen unter Moses Leitung mit dem, was er zu tun und zu tragen hatte." },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Die Heiligung des Volkes (5-10)\nWenn jemand unrein ist" },
      { number: 2, text: "\"Befiehl den Israeliten, dass sie alle aus dem Lager weisen, die an Aussatz oder Ausfluss leiden oder sich durch die Berührung einer Leiche unrein gemacht haben." },
      { number: 3, text: "Das gilt für Männer und Frauen. Ihr sollt sie vor das Lager schicken, damit sie das Lager, in dem ich wohne, nicht verunreinigen.\"" },
      { number: 4, text: "Die Israeliten machten es so und wiesen die Betroffenen vor das Lager hinaus, wie Jahwe es Mose angewiesen hatte." },
      { number: 5, text: "Jahwe befahl Mose,", heading: "Eigentumsvergehen" },
      { number: 6, text: "den Israeliten zu sagen: \"Wenn ein Mann oder eine Frau irgendeine Sünde begeht – so wie die Menschen sie begehen und dadurch Jahwe untreu werden – wird diese Person schuldig." },
      { number: 7, text: "Dann sollen sie ihre Sünde bekennen, die sie begangen haben. Dann soll man voll erstatten, was man schuldig ist, und noch ein Fünftel hinzufügen. Man soll es dem geben, an dem man schuldig geworden ist." },
      { number: 8, text: "Gibt es aber keinen nahen Verwandten*, dem man die Schuld zurückerstatten kann, dann gehört der erstattete Schuldbetrag Jahwe und fällt dem Priester zu, zusätzlich zu dem Schafbock, mit dem er Sühne für ihn erwirkt.", footnotes: ["Verwandten. Das setzt offenbar voraus, dass der Geschädigte nicht mehr am Leben ist."] },
      { number: 9, text: "Und jede Abgabe von allen heiligen Gaben der Israeliten, die sie zum Priester bringen, soll diesem gehören." },
      { number: 10, text: "Jede heilige Gabe soll ihm gehören, was jemand dem Priester gibt, soll diesem gehören.\"" },
      { number: 11, text: "Jahwe befahl Mose,", heading: "Verdacht auf Ehebruch" },
      { number: 12, text: "den Israeliten zu sagen: \"Wenn eine Ehefrau auf Abwege gerät und ihrem Mann untreu wird," },
      { number: 13, text: "wenn sie also mit einem anderen Mann schläft und es bleibt ihrem Ehemann verborgen; sie bleibt unentdeckt, obwohl sie sich verunreinigt hat, es gibt keinen Zeugen und sie ist nicht ertappt worden;" },
      { number: 14, text: "und wenn dann ein Geist der Eifersucht über ihn kommt, dass er eifersüchtig auf seine Frau wird, weil sie sich wirklich verunreinigt hat, oder es kommt ein Geist der Eifersucht über ihn, dass er eifersüchtig auf seine Frau wird, obwohl sie sich nicht verunreinigt hat," },
      { number: 15, text: "dann soll der Mann seine Frau zum Priester bringen und als Opfergabe für sie gut zwei Liter* Gerstenmehl mitbringen. Er darf kein Öl darauf gießen und keinen Weihrauch darauf legen, denn es ist ein Eifersuchtsopfer, ein Erinnerungsopfer, das Schuld aufdeckt.", footnotes: ["zwei Liter. Wörtlich: 1/10 Efa = 2,2 Liter = bei Mehl etwa 1 Kilogramm."] },
      { number: 16, text: "Der Priester soll die Frau herantreten lassen und vor Jahwe stellen." },
      { number: 17, text: "Er soll ein Tongefäß mit geweihtem Wasser nehmen und Staub vom Boden der Wohnung hineinstreuen." },
      { number: 18, text: "Dann muss er die Frau vor Jahwe stellen. Er soll ihr das Haar auflösen und ihr das Erinnerungsopfer in die Hände legen, das Opfer der Eifersucht. Das bittere, fluchbringende Wasser soll der Priester in der Hand halten." },
      { number: 19, text: "Dann soll er die Frau schwören lassen und zu ihr sagen: 'Wenn kein fremder Mann mit dir geschlafen hat und du deinen Mann nicht betrogen hast, dann bleibst du unversehrt von diesem bitteren, fluchbringenden Wasser." },
      { number: 20, text: "Wenn du aber deinen Mann mit einem anderen betrogen hast, wenn du auf Abwege geraten bist und dich verunreinigt hast, wenn ein anderer als dein Mann mit dir geschlafen hat'-" },
      { number: 21, text: "jetzt soll der Priester die Frau den Fluch schwören lassen und zu ihr sagen – 'dann mache Jahwe dich zum Schwur- und Fluchwort in deinem Volk, indem Jahwe deine Hüfte einfallen und deinen Bauch anschwellen lässt." },
      { number: 22, text: "Dieses fluchbringende Wasser soll in deine Eingeweide kommen, deinen Bauch anschwellen und deine Hüfte schwinden lassen.' Die Frau soll sprechen: 'Amen, Amen*!'", footnotes: ["Amen. Hebräisch: Es werde wahr! Oder: So sei es!"] },
      { number: 23, text: "Danach soll der Priester diese Flüche auf ein Blatt schreiben und sie im bitteren Wasser abwaschen." },
      { number: 24, text: "Er soll die Frau das bittere, fluchbringende Wasser trinken lassen, damit dieses Fluchwasser in sie eindringt und ihr bittere Schmerzen bereitet." },
      { number: 25, text: "Dann soll der Priester aus der Hand der Frau das Eifersuchtsopfer nehmen, es vor Jahwe hin und her schwingen und zum Altar bringen." },
      { number: 26, text: "Von diesem Opfer soll er eine Handvoll zum Verbrennen nehmen und auf dem Altar in Rauch aufgehen lassen. Danach soll er der Frau das Wasser zu trinken geben." },
      { number: 27, text: "Wenn das geschehen ist, wird das Wasser in ihr wirken. Falls sie sich verunreinigt hat und ihrem Mann untreu geworden ist, wird das fluchbringende Wasser in sie eindringen und ihr bittere Schmerzen verursachen. Ihr Bauch wird anschwellen und ihre Hüfte einfallen. Die Frau wird zum Fluchwort in ihrem Volk werden." },
      { number: 28, text: "Falls sich die Frau aber nicht verunreinigt hat und rein ist, wird sie unversehrt und fruchtbar bleiben.\"" },
      { number: 29, text: "Das ist das Eifersuchtsgesetz für eine Frau, die ihren Mann betrügt und sich verunreinigt," },
      { number: 30, text: "oder wenn der Geist der Eifersucht über einen Mann kommt und er eifersüchtig auf seine Frau wird, soll er sie vor Jahwe bringen und der Priester soll mit ihr nach diesem Gesetz verfahren." },
      { number: 31, text: "Der Mann wird von Schuld frei sein, die Frau aber muss ihre Schuld tragen." },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Jahwe befahl Mose,", heading: "Wenn Menschen sich Gott weihen" },
      { number: 2, text: "den Israeliten zu sagen: \"Wenn ein Mann oder eine Frau das besondere Gelübde eines Nasiräers ablegt, um sich Jahwe zu weihen," },
      { number: 3, text: "dann soll er sich von Wein und Bier enthalten. Er soll nichts trinken, was aus Wein oder Bier zubereitet wurde, auch keinen Traubensaft. Er darf weder frische noch getrocknete Weintrauben essen." },
      { number: 4, text: "Während seiner ganzen Weihezeit darf er nichts zu sich nehmen, was vom Weinstock stammt, nicht einmal Kerne oder Schalen." },
      { number: 5, text: "Während der ganzen Zeit seines Gelübdes darf er sich Haar und Bart nicht schneiden. Bis die Zeit um ist, für die er sich Jahwe geweiht hat, soll er sein Haupthaar frei wachsen lassen." },
      { number: 6, text: "Die ganze Zeit, für die er sich Jahwe geweiht hat, darf er sich keinem Toten nähern." },
      { number: 7, text: "Nicht einmal an seinem Vater, seiner Mutter, seinem Bruder oder seiner Schwester darf er sich verunreinigen, wenn sie sterben, denn die Weihe seines Gottes ist über ihm." },
      { number: 8, text: "Während der ganzen Zeit seiner Weihe ist der Nasiräer Jahwe geweiht." },
      { number: 9, text: "Wenn nun jemand ganz plötzlich neben ihm stirbt und sein geweihtes Haupt dadurch unrein wird, dann soll er am siebten Tag, an dem er wieder rein wird, seine Haare abschneiden.*", footnotes: ["Haar abschneiden. Nach rabbinischer Tradition musste das abgeschnittene Haar begraben werden, weil es als verunreinigt galt."] },
      { number: 10, text: "Am achten Tag soll er zwei Turteltauben oder zwei andere Tauben zum Priester an den Eingang zum Zelt der Gottesbegegnung bringen." },
      { number: 11, text: "Der Priester soll die eine als Sünd- und die andere als Brandopfer* darbringen und so Sühne für den Betroffenen erwirken, weil er sich wegen des Toten versündigt hat. Dann soll er dessen Haupt an diesem Tag wieder heiligen.", footnotes: ["Beim Brandopfer wurde das geschlachtete Tier vollständig auf dem Altar verbrannt."] },
      { number: 12, text: "Der Betreffende muss sich noch einmal für die gleiche Zeit Jahwe weihen und ein einjähriges Lamm als Schuldopfer* bringen, denn die erste Zeit ist verfallen, weil seine Weihe unrein gemacht worden ist.", footnotes: ["Beim Schuldopfer wurde die Sünde auf ein Opfertier übertragen, und es musste Wiedergutmachung geleistet werden."] },
      { number: 13, text: "So lautet das Nasiräergesetz: Wenn die Zeit seiner Weihe um ist, soll man ihn an den Eingang zum Zelt der Gottesbegegnung bringen." },
      { number: 14, text: "Dort soll er Jahwe seine Gabe übergeben: ein einjähriges männliches Lamm als Brandopfer, ein einjähriges weibliches Lamm als Sündopfer* und einen Schafbock als Freudenopfer*. Alle Tiere müssen ohne Fehler sein.", footnotes: ["Beim Sündopfer musste das Opfertier die Sünde und die Todesstrafe dafür auf sich nehmen und wurde zum Teil auf dem Altar und zum Teil außerhalb vom Lager verbrannt.", "Beim Freudenopfer wurde im Gegensatz zum Brandopfer nur das Fett auf dem Altar verbrannt. Der größte Teil des Tieres durfte bei einer fröhlichen Opfermahlzeit gemeinsam mit Verwandten und Freunden verzehrt werden."] },
      { number: 15, text: "Dazu einen Korb mit ungesäuerten Broten, es sollen Lochbrote* von Feinmehl sein, das vor dem Backen mit Öl vermengt wurde, und Fladenbrote, die mit Öl bestrichen wurden, und die dazugehörigen Speis- und Trankopfer.", footnotes: ["Lochbrot. Ein runder Brotlaib, der in der Mitte durchstoßen ist und so auf einer Stange aufgehängt werden kann zum Schutz gegen Schimmel und Tierfraß."] },
      { number: 16, text: "Das alles soll der Priester zu Jahwe bringen und sowohl das Sünd- als auch das Brandopfer vollziehen." },
      { number: 17, text: "Den Schafbock soll er Jahwe als Freudenopfer darbringen, samt dem Korb mit den ungesäuerten Broten. Dann soll er das Speis- und Trankopfer darbringen." },
      { number: 18, text: "Der Nasiräer soll am Eingang vom Zelt der Gottesbegegnung sein geweihtes Haar abschneiden und in das Feuer werfen*, das unter dem Freudenopfer brennt.", footnotes: ["ins Feuer werfen. Es wurde nicht als Opfer verbrannt, sondern nur, um seine Entweihung zu verhindern."] },
      { number: 19, text: "Der Priester aber soll das gekochte Schulterstück des Schafbocks nehmen, ein ungesäuertes Lochbrot und ein Fladenbrot aus dem Korb und alles auf die Hände des Nasiräers legen, dem das Weihezeichen geschoren wurde." },
      { number: 20, text: "Der Priester soll sie dann selbst in die Hand nehmen und vor Jahwe hin und her schwingen. Es ist eine heilige Gabe für den Priester, samt der geweihten Brust und der als Abgabe bestimmten Keule. Danach darf der Nasiräer wieder Wein trinken." },
      { number: 21, text: "Das ist das Gesetz für den Nasiräer, der ein Gelübde ablegt, für seine Opfergabe, die er Jahwe bringt, abgesehen von dem, was er sonst noch aufbringen kann. Seinem Gelübde gemäß soll er handeln. So entspricht es dem Gesetz seiner Weihe.\"" },
      { number: 22, text: "Jahwe befahl Mose,", heading: "Der priesterliche Segen" },
      { number: 23, text: "Aaron und seinen Söhnen zu sagen: \"So sollt ihr die Israeliten segnen. Sagt:" },
      { number: 24, text: "Jahwe segne dich / und behüte dich!" },
      { number: 25, text: "Möge sein Angesicht über dir leuchten / und er dir gnädig sein!" },
      { number: 26, text: "Jahwe blicke dich freundlich an / und gebe dir Frieden!" },
      { number: 27, text: "So sollen sie meinen Namen auf die Israeliten legen, und ich werde sie segnen.\"" },
    ] },
    { number: 7, verses: [
      { number: 1, text: "An dem Tag, als Mose die Wohnung fertig aufgerichtet, sie mit all ihren Gegenständen, dem Altar und allen dazugehörigen Geräten gesalbt und geheiligt hatte,", heading: "Die Weihgaben der Stammesfürsten" },
      { number: 2, text: "brachten die Fürsten Israels, die Oberhäupter ihrer Sippen, die Fürsten der Stämme und Führer der Gemusterten" },
      { number: 3, text: "ihre Gaben vor Jahwe. Es waren sechs Planwagen und zwölf Rinder, je einen Wagen von zwei Fürsten und je ein Rind von einem Fürst. Sie brachten sie vor die Wohnung." },
      { number: 4, text: "Jahwe sagte zu Mose:" },
      { number: 5, text: "\"Nimm sie von ihnen an. Sie sollen am Zelt der Gottesbegegnung Verwendung finden. Übergib sie den Leviten entsprechend den Anforderungen ihrer Arbeit.\"" },
      { number: 6, text: "Da nahm Mose die Wagen und die Rinder an und übergab sie den Leviten." },
      { number: 7, text: "Zwei Wagen und vier Rinder gab er den Gerschoniten für ihren Dienst." },
      { number: 8, text: "Vier Wagen und acht Rinder gab er den Merariten entsprechend ihrem Dienst unter der Leitung des Priesters Itamar Ben-Aaron." },
      { number: 9, text: "Den Kehatiten gab er nichts, denn ihr Dienst bezog sich auf die Gegenstände im Heiligtum, die nur auf den Schultern getragen werden durften." },
      { number: 10, text: "Außerdem brachten die Fürsten an dem Tag, an dem der Altar gesalbt wurde, Gaben zu seiner Einweihung." },
      { number: 11, text: "Doch Jahwe sagte zu Mose: \"Jeden Tag soll nur ein Fürst seine Gabe zur Einweihung des Altars bringen.\"" },
      { number: 12, text: "Am ersten Tag brachte Nachschon Ben-Amminadab vom Stamm Juda seine Gabe." },
      { number: 13, text: "Es war eine Silberschüssel im Gewicht von 1500 Gramm* und eine 800 Gramm* schwere Sprengschale aus Silber, nach dem Gewicht des Heiligtums. Beide enthielten als Speisopfer Feinmehl, das mit Olivenöl vermengt war.", footnotes: ["1500 Gramm. Wörtlich: 130 Schekel. Nach dem Gewicht des Heiligtums (4. Mose 3,47) waren das 11,5 Gramm pro Schekel = 1495 Gramm.", "800 Gramm. Wörtlich: 70 Schekel."] },
      { number: 14, text: "Dazu kam noch eine 115 Gramm* schwere Schale aus Gold, die mit Weihrauch gefüllt war.", footnotes: ["120 Gramm. Wörtlich: 10 Schekel."] },
      { number: 15, text: "Dann brachte er noch einen jungen Stier, einen Schafbock und ein einjähriges Lamm zum Brandopfer," },
      { number: 16, text: "einen Ziegenbock zum Sündopfer" },
      { number: 17, text: "und zwei Rinder, fünf Schafböcke, fünf Ziegenböcke und fünf einjährige Lämmer zum Freudenopfer. Das war die Gabe von Nachschon Ben-Amminadab." },
      { number: 18, text: "Am zweiten Tag brachte Netanel Ben-Zuar, der Fürst des Stammes Issachar, seine Gabe." },
      { number: 19, text: "Es war eine Silberschüssel im Gewicht von 1500 Gramm und eine 800 Gramm schwere Sprengschale aus Silber nach dem Gewicht des Heiligtums. Beide enthielten als Speisopfer Feinmehl, das mit Olivenöl vermengt war." },
      { number: 20, text: "Dazu kam noch eine 115 Gramm schwere Schale aus Gold, die mit Weihrauch gefüllt war." },
      { number: 21, text: "Dann brachte er noch einen jungen Stier, einen Schafbock und ein einjähriges Lamm zum Brandopfer," },
      { number: 22, text: "einen Ziegenbock zum Sündopfer" },
      { number: 23, text: "und zwei Rinder, fünf Schafböcke, fünf Ziegenböcke und fünf einjährige Lämmer zum Freudenopfer. Das war die Gabe von Netanel Ben-Zuar." },
      { number: 24, text: "Am dritten Tag brachte der Fürst des Stammes Sebulon, Eliab Ben-Helon, seine Gabe." },
      { number: 25, text: "Es war eine Silberschüssel im Gewicht von 1500 Gramm und eine 800 Gramm schwere Sprengschale nach dem Gewicht des Heiligtums. Beide enthielten als Speisopfer Feinmehl, das mit Olivenöl vermengt war." },
      { number: 26, text: "Dazu kam noch eine 115 Gramm schwere Schale aus Gold, die mit Weihrauch gefüllt war." },
      { number: 27, text: "Dann brachte er noch einen jungen Stier, einen Schafbock und ein einjähriges Lamm zum Brandopfer," },
      { number: 28, text: "einen Ziegenbock zum Sündopfer" },
      { number: 29, text: "und zwei Rinder, fünf Schafböcke, fünf Ziegenböcke und fünf einjährige Lämmer zum Freudenopfer. Das war die Gabe von Eliab Ben-Helon." },
      { number: 30, text: "Am vierten Tag brachte der Fürst des Stammes Ruben, Elizur Ben-Schedëur, seine Gabe." },
      { number: 31, text: "Es war eine Silberschüssel im Gewicht von 1500 Gramm und eine 800 Gramm schwere Sprengschale nach dem Gewicht des Heiligtums. Beide enthielten als Speisopfer Feinmehl, das mit Olivenöl vermengt war." },
      { number: 32, text: "Dazu kam noch eine 115 Gramm schwere Schale aus Gold, die mit Weihrauch gefüllt war." },
      { number: 33, text: "Dann brachte er noch einen jungen Stier, einen Schafbock und ein einjähriges Lamm zum Brandopfer," },
      { number: 34, text: "einen Ziegenbock zum Sündopfer" },
      { number: 35, text: "und zwei Rinder, fünf Schafböcke, fünf Ziegenböcke und fünf einjährige Lämmer zum Freudenopfer. Das war die Gabe von Elizur Ben-Schedëur." },
      { number: 36, text: "Am fünften Tag brachte der Fürst des Stammes Simeon, Schelumiël Ben-Zurischaddai, seine Gabe." },
      { number: 37, text: "Es war eine Silberschüssel im Gewicht von 1500 Gramm und eine 800 Gramm schwere Sprengschale nach dem Gewicht des Heiligtums. Beide enthielten als Speisopfer Feinmehl, das mit Olivenöl vermengt war." },
      { number: 38, text: "Dazu kam noch eine 115 Gramm schwere Schale aus Gold, die mit Weihrauch gefüllt war." },
      { number: 39, text: "Dann brachte er noch einen jungen Stier, einen Schafbock und ein einjähriges Lamm zum Brandopfer," },
      { number: 40, text: "einen Ziegenbock zum Sündopfer" },
      { number: 41, text: "und zwei Rinder, fünf Schafböcke, fünf Ziegenböcke und fünf einjährige Lämmer zum Freudenopfer. Das war die Gabe von Schelumiël Ben-Zurischaddai." },
      { number: 42, text: "Am sechsten Tag brachte der Fürst des Stammes Gad, Eljasaf Ben-Dëuël, seine Gabe." },
      { number: 43, text: "Es war eine Silberschüssel im Gewicht von 1500 Gramm und eine 800 Gramm schwere Sprengschale nach dem Gewicht des Heiligtums. Beide enthielten als Speisopfer Feinmehl, das mit Olivenöl vermengt war." },
      { number: 44, text: "Dazu kam noch eine 115 Gramm schwere Schale aus Gold, die mit Weihrauch gefüllt war." },
      { number: 45, text: "Dann brachte er noch einen jungen Stier, einen Schafbock und ein einjähriges Lamm zum Brandopfer," },
      { number: 46, text: "einen Ziegenbock zum Sündopfer" },
      { number: 47, text: "und zwei Rinder, fünf Schafböcke, fünf Ziegenböcke und fünf einjährige Lämmer zum Freudenopfer. Das war die Gabe von Eljasaf Ben-Dëuël." },
      { number: 48, text: "Am siebten Tag brachte der Fürst des Stammes Efraïm, Elischama Ben-Ammihud, seine Gabe." },
      { number: 49, text: "Es war eine Silberschüssel im Gewicht von 1500 Gramm und eine 800 Gramm schwere Sprengschale nach dem Gewicht des Heiligtums. Beide enthielten als Speisopfer Feinmehl, das mit Olivenöl vermengt war." },
      { number: 50, text: "Dazu kam noch eine 115 Gramm schwere Schale aus Gold, die mit Weihrauch gefüllt war." },
      { number: 51, text: "Dann brachte er noch einen jungen Stier, einen Schafbock und ein einjähriges Lamm zum Brandopfer," },
      { number: 52, text: "einen Ziegenbock zum Sündopfer" },
      { number: 53, text: "und zwei Rinder, fünf Schafböcke, fünf Ziegenböcke und fünf einjährige Lämmer zum Freudenopfer. Das war die Gabe von Elischama Ben-Ammihud." },
      { number: 54, text: "Am achten Tag brachte der Fürst des Stammes Manasse, Gamliël Ben-Pedazur, seine Gabe." },
      { number: 55, text: "Es war eine Silberschüssel im Gewicht von 1500 Gramm und eine 800 Gramm schwere Sprengschale nach dem Gewicht des Heiligtums. Beide enthielten als Speisopfer Feinmehl, das mit Olivenöl vermengt war." },
      { number: 56, text: "Dazu kam noch eine 115 Gramm schwere Schale aus Gold, die mit Weihrauch gefüllt war." },
      { number: 57, text: "Dann brachte er noch einen jungen Stier, einen Schafbock und ein einjähriges Lamm zum Brandopfer," },
      { number: 58, text: "einen Ziegenbock zum Sündopfer" },
      { number: 59, text: "und zwei Rinder, fünf Schafböcke, fünf Ziegenböcke und fünf einjährige Lämmer zum Freudenopfer. Das war die Gabe von Gamliël Ben-Pedazur." },
      { number: 60, text: "Am neunten Tag brachte der Fürst des Stammes Benjamin, Abidan Ben-Gidoni, seine Gabe." },
      { number: 61, text: "Es war eine Silberschüssel im Gewicht von 1500 Gramm und eine 800 Gramm schwere Sprengschale nach dem Gewicht des Heiligtums. Beide enthielten als Speisopfer Feinmehl, das mit Olivenöl vermengt war." },
      { number: 62, text: "Dazu kam noch eine 115 Gramm schwere Schale aus Gold, die mit Weihrauch gefüllt war." },
      { number: 63, text: "Dann brachte er noch einen jungen Stier, einen Schafbock und ein einjähriges Lamm zum Brandopfer," },
      { number: 64, text: "einen Ziegenbock zum Sündopfer" },
      { number: 65, text: "und zwei Rinder, fünf Schafböcke, fünf Ziegenböcke und fünf einjährige Lämmer zum Freudenopfer. Das war die Gabe von Abidan Ben-Gidoni." },
      { number: 66, text: "Am zehnten Tag brachte der Fürst des Stammes Dan, Ahiëser Ben-Ammischaddai, seine Gabe." },
      { number: 67, text: "Es war eine Silberschüssel im Gewicht von 1500 Gramm und eine 800 Gramm schwere Sprengschale nach dem Gewicht des Heiligtums. Beide enthielten als Speisopfer Feinmehl, das mit Olivenöl vermengt war." },
      { number: 68, text: "Dazu kam noch eine 115 Gramm schwere Schale aus Gold, die mit Weihrauch gefüllt war." },
      { number: 69, text: "Dann brachte er noch einen jungen Stier, einen Schafbock und ein einjähriges Lamm zum Brandopfer," },
      { number: 70, text: "einen Ziegenbock zum Sündopfer" },
      { number: 71, text: "und zwei Rinder, fünf Schafböcke, fünf Ziegenböcke und fünf einjährige Lämmer zum Freudenopfer. Das war die Gabe von Ahiëser Ben-Ammischaddai." },
      { number: 72, text: "Am elften Tag brachte der Fürst des Stammes Ascher, Pagiël Ben-Ochran, seine Gabe." },
      { number: 73, text: "Es war eine Silberschüssel im Gewicht von 1500 Gramm und eine 800 Gramm schwere Sprengschale nach dem Gewicht des Heiligtums. Beide enthielten als Speisopfer Feinmehl, das mit Olivenöl vermengt war." },
      { number: 74, text: "Dazu kam noch eine 115 Gramm schwere Schale aus Gold, die mit Weihrauch gefüllt war." },
      { number: 75, text: "Dann brachte er noch einen jungen Stier, einen Schafbock und ein einjähriges Lamm zum Brandopfer," },
      { number: 76, text: "einen Ziegenbock zum Sündopfer" },
      { number: 77, text: "und zwei Rinder, fünf Schafböcke, fünf Ziegenböcke und fünf einjährige Lämmer zum Freudenopfer. Das war die Gabe von Pagiël Ben-Ochran." },
      { number: 78, text: "Am zwölften Tag brachte der Fürst des Stammes Naftali, Ahira Ben-Enan, seine Gabe." },
      { number: 79, text: "Es war eine Silberschüssel im Gewicht von 1500 Gramm und eine 800 Gramm schwere Sprengschale nach dem Gewicht des Heiligtums. Beide enthielten als Speisopfer Feinmehl, das mit Olivenöl vermengt war." },
      { number: 80, text: "Dazu kam noch eine 115 Gramm schwere Schale aus Gold, die mit Weihrauch gefüllt war." },
      { number: 81, text: "Dann brachte er noch einen jungen Stier, einen Schafbock und ein einjähriges Lamm zum Brandopfer," },
      { number: 82, text: "einen Ziegenbock zum Sündopfer" },
      { number: 83, text: "und zwei Rinder, fünf Schafböcke, fünf Ziegenböcke und fünf einjährige Lämmer zum Freudenopfer. Das war die Gabe von Ahira Ben-Enan." },
      { number: 84, text: "Das war die Gabe der Fürsten Israels zur Salbung und Einweihung des Altars: zwölf Silberschüsseln, zwölf Sprengschalen aus Silber und zwölf goldene Schalen." },
      { number: 85, text: "Eine Silberschüssel wog 1500 Gramm und eine Sprengschale 800 Gramm. Insgesamt waren es nach dem Gewicht des Heiligtums rund 28 Kilogramm* Silber.", footnotes: ["29 Kilogramm. Wörtlich: 2400 Schekel."] },
      { number: 86, text: "Dazu kamen die mit Weihrauch gefüllten zwölf goldenen Schalen mit einem Goldgewicht von insgesamt rund 1400 Gramm*.", footnotes: ["1500 Gramm. Wörtlich: 120 Schekel."] },
      { number: 87, text: "Es waren zum Brandopfer: zwölf Stiere, zwölf Schafböcke, zwölf einjährige Lämmer und die dazugehörigen Speisopfer, und zwölf Ziegenböcke zum Sündopfer." },
      { number: 88, text: "Zum Freudenopfer waren es insgesamt 24 Stiere, 60 Schafböcke, 60 Ziegenböcke und 60 einjährige Lämmer. Das war die Gabe zur Einweihung des Altars, nachdem er gesalbt worden war." },
      { number: 89, text: "Wenn Mose in das Zelt der Gottesbegegnung hineinging, um mit Gott zu reden, hörte er dessen Stimme von der Deckplatte herab zu ihm sprechen, die auf der Bundeslade lag, zwischen den beiden Cherubim* hervor.", footnotes: ["Cherub, Mehrzahl: Cherubim. Majestätisches (Engel-)Wesen, das Gottes Herrlichkeit repräsentiert. Zwei Cherubim-Figuren waren auf dem Deckel der Bundeslade angebracht."] },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Jahwe sagte zu Mose,", heading: "Die Pflege des goldenen Leuchters" },
      { number: 2, text: "er solle Aaron Folgendes weitergeben: \"Wenn du die sieben Lampen aufsetzt, dann sollen sie ihr Licht nach vorn fallen lassen.\"" },
      { number: 3, text: "Aaron machte es so: Er setzte die Lampen so auf, dass ihr Licht vor den Leuchter* fiel, wie Jahwe es Mose gesagt hatte.", footnotes: ["Leuchter. Hebräisch:menorah. Die genaue Beschreibung findet sich in 2. Mose 25,31-40."] },
      { number: 4, text: "Der Leuchter bestand aus reinem Gold und war vom Fuß bis zu den Blüten aus einem Stück getrieben. Nach dem Bild, das Jahwe Mose gezeigt hatte, war der Leuchter hergestellt worden." },
      { number: 5, text: "Jahwe sagte zu Mose:", heading: "Die Einsetzung der Leviten" },
      { number: 6, text: "\"Sondere die Leviten aus den Israeliten aus und reinige* sie!", footnotes: ["reinige. Leviten wurden nur gereinigt, nicht geweiht wie die Priester."] },
      { number: 7, text: "Das sollst du folgendermaßen tun: Besprenge sie mit Entsündigungswasser und sorge dafür, dass sie ihren ganzen Körper rasieren und ihre Kleidung waschen, damit sie rein werden." },
      { number: 8, text: "Dann sollen sie einen jungen Stier nehmen und das dazugehörige Speisopfer: mit Öl vermengtes Feinmehl. Auch du sollst einen jungen Stier zum Sündopfer nehmen." },
      { number: 9, text: "Lass dann die Leviten vor das Zelt der Gottesbegegnung treten und die ganze Gemeinde der Israeliten zusammenkommen." },
      { number: 10, text: "Du sollst die Leviten vor Jahwe stellen, und die Israeliten sollen ihre Hände auf sie legen." },
      { number: 11, text: "Aaron soll Jahwe die Leviten als Weihgabe der Israeliten darbringen, damit sie den Dienst für Jahwe tun." },
      { number: 12, text: "Und die Leviten sollen ihre Hände auf den Kopf der jungen Stiere stützen. Einen der beiden Stiere sollst du Jahwe als Sündopfer und den anderen als Brandopfer darbringen, um Sühne für die Leviten zu erwirken." },
      { number: 13, text: "Auf diese Weise sollst du die Leviten vor Aaron und seine Söhne stellen und sie als Weihgabe Jahwe bringen." },
      { number: 14, text: "So werden sie von den Israeliten ausgesondert, damit sie mir gehören." },
      { number: 15, text: "Danach sollen die Leviten mit ihrem Dienst am Zelt der Gottesbegegnung beginnen. Du sollst sie also reinigen und Jahwe als Weihgabe bringen." },
      { number: 16, text: "Denn sie sind mir von den Israeliten als besonderes Eigentum gegeben, als Ersatz für alle erstgeborenen Söhne Israels habe ich sie angenommen." },
      { number: 17, text: "Denn mir gehört alles, was zuerst aus dem Mutterschoß kommt, von Mensch und Tier. An dem Tag, als ich jede Erstgeburt in Ägypten erschlug, habe ich sie für mich geweiht" },
      { number: 18, text: "und die Leviten anstelle der Erstgeborenen Israels angenommen." },
      { number: 19, text: "Dann habe ich die Leviten Aaron und seinen Nachkommen als Gabe der Israeliten übergeben, damit sie den Dienst am Zelt der Gottesbegegnung anstelle der Israeliten tun, um für sie Sühne zu erwirken. So wird keine Plage über die Israeliten kommen, wenn diese sich dem Heiligtum nähern.\"" },
      { number: 20, text: "Mose, Aaron und die ganze Menge der Israeliten machten es so mit den Leviten, genauso, wie Jahwe es Mose befohlen hatte." },
      { number: 21, text: "Die Leviten ließen sich entsündigen und wuschen ihre Kleidung. Aaron brachte sie dann als Weihgabe vor Jahwe dar und erwirkte Sühne für sie, um sie zu reinigen." },
      { number: 22, text: "Danach traten die Leviten ihren Dienst bei Aaron und seinen Söhnen im Zelt der Gottesbegegnung an. So wie Jahwe es Mose für die Leviten aufgetragen hatte, machten es die Israeliten." },
      { number: 23, text: "Jahwe sagte zu Mose:", heading: "Das Dienstalter der Leviten" },
      { number: 24, text: "\"Für die Leviten gilt Folgendes: Mit 25 Jahren* soll ein Levit in die Arbeit am Zelt der Gottesbegegnung eintreten.", footnotes: ["Mit 25 Jahren. In 4. Mose 4,3.23.30 wurde das Alter mit 30 Jahren angegeben, was sich dort aber auf das Tragen verschiedener Teile der Stiftshütte bezog. Ihren allgemeinen Hilfsdienst begannen die Leviten schon mit 25 Jahren. David setzte später das Eintrittsalter auf 20 Jahre herab (1. Chronik 23,24.27; Esra 3,8)."] },
      { number: 25, text: "Wer 50 Jahre alt ist, soll von der Dienstverpflichtung zurücktreten und keinen Dienst mehr tun." },
      { number: 26, text: "Er kann seinen Brüdern bei der Arbeit am Zelt helfen, soll aber keinen Dienst mehr tun. So sollst du es mit den Leviten und ihren Aufgaben halten. \"" },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Im April* des zweiten Jahres nach dem Auszug aus Ägypten redete Jahwe in der Wüste Sinai zu Mose. Er sagte:", heading: "Zur Passaordnung", footnotes: ["April. Wörtlich: im 1. Monat. Es war noch das Jahr 1445 v.Chr."] },
      { number: 2, text: "\"Die Israeliten sollen das Passa* zur festgesetzten Zeit feiern", footnotes: ["Passa. Siehe 2. Mose 12-13."] },
      { number: 3, text: "und zwar am 14. Tag dieses Monats am späten Nachmittag* zur festgelegten Zeit. Ihr sollt es nach allen Ordnungen und Vorschriften tun.\"", footnotes: ["späten Nachmittag. Wörtlich: Zwischen den zwei Abenden. Gemeint ist wahrscheinlich die Zeit zwischen Niedergang (15 Uhr) und Untergang der Sonne."] },
      { number: 4, text: "Mose sagte den Israeliten, dass sie das Passa feiern sollten." },
      { number: 5, text: "So feierten sie das Fest am späten Nachmittag des 14. April in der Wüste Sinai, wie Jahwe es Mose angewiesen hatte. Genauso taten sie es." },
      { number: 6, text: "Es gab aber Männer, die an einem Toten unrein geworden waren und das Passa an diesem Tag nicht feiern konnten. Sie kamen zu Mose und Aaron" },
      { number: 7, text: "und sagten zu ihnen: \"Wir sind an einem Toten unrein geworden. Warum soll es uns verwehrt sein, die Opfergabe für Jahwe zur festgesetzten Zeit zu bringen?\"" },
      { number: 8, text: "Mose entgegnete: \"Wartet, ich will hören, was Jahwe für euch anordnet.\"" },
      { number: 9, text: "Jahwe befahl Mose," },
      { number: 10, text: "den Israeliten zu sagen: \"Wenn jemand bei euch oder euren nachfolgenden Generationen an einem Toten unrein geworden ist oder sich auf einer weiten Reise befindet und trotzdem Jahwe das Passa feiern will," },
      { number: 11, text: "der soll es am 14. des nächsten Monats am späten Nachmittag tun. Man soll es zu ungesäuerten Broten und bitteren Kräutern essen." },
      { number: 12, text: "Sie dürfen nichts bis zum nächsten Morgen übrig lassen und keinen der Knochen des Lammes zerbrechen. Sie müssen die Passaordnung einhalten." },
      { number: 13, text: "Wer aber rein ist und sich nicht auf einer Reise befindet und es trotzdem unterlässt, das Passa zu feiern, soll von der Volksgemeinschaft beseitigt werden, denn er hat die Opfergabe für Jahwe nicht zur festgesetzten Zeit gebracht. Dieser Mann muss seine Schuld tragen." },
      { number: 14, text: "Wenn ein Fremder bei euch lebt und Jahwe das Passa feiern will, soll er es nach den Ordnungen und Vorschriften des Passafestes tun. Für den Fremden und den Einheimischen im Land gilt dieselbe Ordnung.\"" },
      { number: 15, text: "An dem Tag, als man die Wohnung, das Zelt der Gottesbegegnung, aufrichtete, wurde sie von der Wolke bedeckt – der Wolke, die vom Abend bis zum Morgen wie ein Feuerschein leuchtete.", heading: "Die Wolken- und Feuersäule" },
      { number: 16, text: "So war es ständig: Tagsüber stand die Wolke über der Wohnung, nachts war es der Feuerschein." },
      { number: 17, text: "Immer, wenn die Wolke sich vom Zelt erhob, brachen die Israeliten auf. Und dort, wo die Wolke sich niederließ, lagerten sie." },
      { number: 18, text: "Nach dem Befehl Jahwes brachen die Israeliten auf und nach seinem Befehl schlugen sie ihr Lager auf. Sie blieben immer so lange, wie die Wolke auf dem Zelt ruhte." },
      { number: 19, text: "Wenn die Wolke viele Tage auf der Wohnung stehen blieb, folgten die Israeliten der Weisung Jahwes und machten einen längeren Aufenthalt." },
      { number: 20, text: "Blieb sie nur wenige Tage, zogen sie entsprechend früher weiter, immer nach Jahwes Befehl." },
      { number: 21, text: "Es kam auch vor, dass die Wolke nur eine Nacht blieb oder nur einen Tag und eine Nacht. Wenn die Wolke sich erhob, brachen sie auf." },
      { number: 22, text: "Oder es waren zwei Tage oder einen Monat oder längere Zeit – wenn die Wolke auf der Wohnung ruhte, schlugen die Israeliten ihr Lager auf und blieben so lange, bis sie sich wieder erhob." },
      { number: 23, text: "Nach dem Befehl Jahwes blieben sie und nach dem Befehl Jahwes brachen sie auf. Sie befolgten die Anweisung, die Jahwe ihnen durch Mose gegeben hatte." },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Die silbernen Trompeten" },
      { number: 2, text: "\"Lass zwei Trompeten aus getriebenem Silber anfertigen. Sie sollen dazu dienen, die Gemeinschaft zusammenzurufen und das Zeichen zum Aufbruch zu geben." },
      { number: 3, text: "Wenn man beide bläst, soll sich die ganze Gemeinschaft bei dir am Eingang zum Zelt der Gottesbegegnung versammeln." },
      { number: 4, text: "Wenn man nur eine bläst, sollen sich die Fürsten, die Oberhäupter der Heereseinheiten Israels bei dir versammeln." },
      { number: 5, text: "Wenn ihr das Signal blast, sollen die Stämme aufbrechen, die im Osten lagern." },
      { number: 6, text: "Blast ihr das Signal zum zweiten Mal, sollen die Stämme aufbrechen, die im Süden lagern." },
      { number: 7, text: "Wenn aber die Versammlung einberufen werden soll, dürft ihr nicht dieses Signal blasen." },
      { number: 8, text: "Die Trompeten sollen von den Nachkommen Aarons, den Priestern, geblasen werden. Das ist eine immerwährende Ordnung, die auch für nachfolgende Generationen gilt." },
      { number: 9, text: "Und wenn ihr gegen einen Feind, der in euer Land einfällt, in den Krieg ziehen müsst, dann sollt ihr mit den Trompeten das Signal geben. Dann wird bei Jahwe, eurem Gott, an euch gedacht werden, und ihr werdet vor euren Feinden gerettet." },
      { number: 10, text: "Auch bei freudigen Anlässen, an den Festen und Neumondstagen, sollt ihr die Trompeten zu euren Brand- und Freudenopfern blasen. Sie sollen euch vor Gott in Erinnerung bringen. Ich bin Jahwe, euer Gott.\"" },
      { number: 11, text: "Im zweiten Jahr nach dem Auszug aus Ägypten, am 20. Mai*, erhob sich die Wolke von der Wohnung des Bundesgesetzes.", heading: "Aufbruch vom Sinai", footnotes: ["Mai. Wörtlich: im 2. Monat. Es war noch das Jahr 1445 v.Chr."] },
      { number: 12, text: "Da zogen die Israeliten aus der Wüste Sinai weiter von Lagerplatz zu Lagerplatz, bis sich die Wolke in der Wüste Paran* niederließ.", footnotes: ["Die Wüste Paran hat man vermutlich in der nördlichen Sinaihalbinsel westlich der Araba zu suchen."] },
      { number: 13, text: "So brachen sie zum ersten Mal auf, wie Jahwe es Mose befohlen hatte." },
      { number: 14, text: "Zuerst brach die Abteilung unter dem Feldzeichen des Stammes Juda auf. Judas Heeresverband wurde von Nachschon Ben-Amminadab geführt." },
      { number: 15, text: "Der Heeresverband des Stammes Issachar wurde von Netanel Ben-Zuar geführt" },
      { number: 16, text: "und der Heeresverband des Stammes Sebulon von Eliab Ben-Helon." },
      { number: 17, text: "Nachdem die Wohnung abgebaut war, brachen die Gerschoniten und die Merariten auf, die die Wohnung trugen." },
      { number: 18, text: "Dann kam die Abteilung unter dem Feldzeichen des Stammes Ruben. Rubens Heeresverband wurde von Elizur Ben-Schedëur geführt." },
      { number: 19, text: "Der Heeresverband des Stammes Simeon wurde von Schelumiël Ben-Zurischaddai geführt und" },
      { number: 20, text: "der Heeresverband des Stammes Gad von Eljasaf Ben-Dëuël." },
      { number: 21, text: "Dann brachen die Kehatiten auf, die das Heilige trugen. Und man baute die Wohnung auf, bis sie ankamen." },
      { number: 22, text: "Hinter ihnen zog die Abteilung unter dem Feldzeichen des Stammes Efraïm. Efraïms Heeresverband wurde von Elischama Ben-Ammihud geführt." },
      { number: 23, text: "Der Heeresverband des Stammes Manasse wurde von Gamliël Ben-Pedazur geführt und" },
      { number: 24, text: "der Heeresverband des Stammes Benjamin von Abidan Ben-Gidoni." },
      { number: 25, text: "Die Nachhut für alle Lager bildete die Abteilung unter dem Feldzeichen des Stammes Dan. Dans Heeresverband wurde von Ahiëser Ben-Ammischaddai geführt." },
      { number: 26, text: "Der Heeresverband des Stammes Ascher wurde von Pagiël Ben-Ochran geführt" },
      { number: 27, text: "und der Heeresverband des Stammes Naftali von Ahira Ben-Enan." },
      { number: 28, text: "So brachen die Israeliten auf, Heerschar um Heerschar." },
      { number: 29, text: "Mose sagte zu Hobab, dem Sohn seines midianitischen Schwiegervaters Reguël*: \"Wir machen uns jetzt auf den Weg zu dem Ort, den Jahwe uns versprochen hat. Geh mit uns! Wir werden dir Gutes tun, denn Jahwe hat Israel Gutes zugesagt.\"", footnotes: ["Reguël. Siehe 2. Mose 2,18-21!"] },
      { number: 30, text: "Doch Hobab erwiderte: \"Nein, ich werde nicht mitkommen, sondern in mein Land und zu meiner Verwandtschaft gehen.\"" },
      { number: 31, text: "\"Verlass uns doch nicht!\", bat Mose. \"Du weißt, wo wir uns in der Wüste lagern können, und sollst uns als Auge dienen." },
      { number: 32, text: "Wenn du mit uns kommst und all das Gute geschieht, das Jahwe uns zugesagt hat, werden wir auch dir Gutes tun.\"" },
      { number: 33, text: "So zogen sie vom Berg Jahwes aus drei Tagereisen weit. Die Bundeslade Jahwes zog vor ihnen her, um den Lagerplatz zu bestimmen," },
      { number: 34, text: "und die Wolke Jahwes war über ihnen, wenn sie auszogen." },
      { number: 35, text: "Immer wenn die Lade aufbrach, sagte Mose:\"Steh auf, Jahwe! / Dann laufen deine Feinde auseinander, / dann fliehen die, die dich hassen.\"" },
      { number: 36, text: "Und wenn sie Halt machte, sagte er:\"Komm wieder Jahwe, / zu den Abertausenden* Israels!\"", footnotes: ["Abertausenden. Wörtlich: Zehntausenden der Tausenden (Heereseinheiten)."] },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Das Volk lag Jahwe mit schweren Klagen in den Ohren. Als Jahwe das vernahm, entflammte sein Zorn. Er schickte ein Feuer, das am Rand des Lagers aufloderte und um sich fraß.", heading: "11-20: Unterwegs nach Kadesch\nOffener Ungehorsam im Volk (11-14)\nUnzufriedenheit unter dem Volk" },
      { number: 2, text: "Da schrie das Volk zu Mose um Hilfe. Mose betete zu Jahwe und das Feuer fiel in sich zusammen." },
      { number: 3, text: "Den Ort nannte man Tabera, Brand, weil das Feuer Jahwes gegen sie aufgelodert war." },
      { number: 4, text: "Doch das hergelaufene Gesindel* unter ihnen wurde gierig. Aber auch die Israeliten fingen wieder an zu jammern und sagten: \"Wer gibt uns Fleisch zu essen?", footnotes: ["hergelaufenes Gesindel. Siehe 2. Mose 12,38!"] },
      { number: 5, text: "Wir denken an die Fische, die wir in Ägypten umsonst bekamen, an die Gurken und Melonen, den Porree, die Zwiebeln und den Knoblauch." },
      { number: 6, text: "Uns ist jetzt der Appetit vergangen, denn nichts von alldem ist da. Hier sehen wir immer nur das Manna.\"" },
      { number: 7, text: "Das Manna war wie Koriandersamen* und sah aus wie Bedolach-Harz*.", footnotes: ["Koriandersamen. Die Übersetzung des hebräischen Wortes \"gad\" mit Koriander, dessen 2-3 Millimeter große Samenkörner grau-weiß sind, ist nicht sicher.", "Bedolach. Ein duftendes durchscheinendes Edelharz."] },
      { number: 8, text: "Die Leute streiften umher, sammelten es ein, zermahlten es in Handmühlen oder zerstampften es in Mörsern, sie kochten es im Topf oder machten Brotfladen daraus. Es hatte einen Geschmack wie Ölkuchen." },
      { number: 9, text: "Wenn nachts der Tau auf das Lager fiel, fiel auch das Manna." },
      { number: 10, text: "Mose hörte die Leute jammern, eine Sippe wie die andere. Sie standen vor ihren Zelten und der Zorn Jahwes flammte heftig auf. Das missfiel Mose sehr." },
      { number: 11, text: "Er sagte zu Jahwe: \"Warum behandelst du deinen Diener so schlecht und womit habe ich es verdient, dass du die Last dieses ganzen Volkes auf mich legst?" },
      { number: 12, text: "Bin ich denn mit diesem Volk schwanger gegangen oder habe ich es geboren, dass du von mir verlangst, es wie ein Wärter an der Brust zu tragen und in das Land zu bringen, das du ihren Vätern zugesagt hast?" },
      { number: 13, text: "Woher soll ich denn Fleisch nehmen, um es diesem ganzen Volk zu geben? Sie liegen mir in den Ohren mit ihrem Geschrei und wollen Fleisch zu essen haben." },
      { number: 14, text: "Ich allein kann dieses Volk nicht tragen. Das ist mir zu schwer." },
      { number: 15, text: "Wenn du aber weiter so mit mir umgehen willst, dann töte mich lieber, wenn du mir gnädig bist, damit ich mein Unglück nicht länger ansehen muss.\"" },
      { number: 16, text: "Da sagte Jahwe zu Mose: \"Versammle mir siebzig Männer von den Ältesten Israels, von denen du weißt, dass sie sich als Aufseher des Volkes bewährt haben, und nimm sie mit zum Zelt der Gottesbegegnung. Dort sollen sie sich mit dir hinstellen." },
      { number: 17, text: "Dann komme ich herab und rede dort mit dir. Ich nehme von dem Geist, der auf dir ruht, und lege ihn auf sie. So können sie zusammen mit dir an der Last des Volkes tragen, und du musst es nicht mehr allein tun." },
      { number: 18, text: "Zum Volk aber sollst du sagen: 'Heiligt euch für morgen, da werdet ihr Fleisch zu essen haben, denn ihr habt Jahwe die Ohren vollgejammert und gefragt, wer euch Fleisch zu essen gibt, denn in Ägypten wäre es euch ja gut gegangen.' Jahwe wird euch Fleisch geben, das ihr essen könnt." },
      { number: 19, text: "Und das nicht nur ein, zwei Tage lang, auch nicht nur fünf, zehn oder zwanzig Tage," },
      { number: 20, text: "sondern einen ganzen Monat, bis es euch zum Hals heraushängt und euch übel davon wird. Denn ihr habt Jahwe verworfen, der unter euch gegenwärtig ist, und vor ihm gesagt: 'Warum sind wir nur aus Ägypten gezogen?'\"" },
      { number: 21, text: "Da erwiderte Mose: \"Das Volk, zu dem ich gehöre, zählt allein 600.000 wehrfähige Männer, und du sagst, dass du ihnen einen Monat lang Fleisch zu essen geben willst?" },
      { number: 22, text: "Können denn so viele Schafe, Ziegen und Rinder für sie geschlachtet werden, dass es für alle genug ist? Oder soll man alle Fische des Meeres für sie fangen, dass es reicht?\"" },
      { number: 23, text: "Jahwe sagte zu Mose: \"Ist die Hand Jahwes etwa zu kurz? Jetzt wirst du sehen, ob mein Wort eintrifft oder nicht.\"" },
      { number: 24, text: "Mose ging hinaus und teilte dem Volk mit, was Jahwe ihm gesagt hatte. Dann versammelte er siebzig Männer von den Ältesten Israels und stellte sie rings um das Zelt auf." },
      { number: 25, text: "Da kam Jahwe in der Wolke herab und sprach mit ihm. Er nahm von dem Geist, der auf ihm ruhte, und legte ihn auf die siebzig Männer, die Ältesten. Als der Geist Gottes über sie kam, redeten sie auf einmal wie Propheten, aber nur für kurze Zeit." },
      { number: 26, text: "Zwei von den Männern, die auf der Liste standen, waren nicht zum Zelt hinausgegangen, sondern im Lager zurückgeblieben. Einer hieß Eldad, der andere Medad. Auch auf sie kam der Geist und sie redeten wie Propheten im Lager." },
      { number: 27, text: "Da lief ein junger Mann zu Mose und berichtete ihm: \"Im Lager reden Eldad und Medad wie Propheten.\"" },
      { number: 28, text: "Josua Ben-Nun, der von Jugend an Moses Diener war, sagte: \"Lass das nicht zu, mein Herr, Mose!\"" },
      { number: 29, text: "Aber Mose sagte zu ihm: \"Was eiferst du für mich? Könnten doch alle im Volk Jahwes Propheten sein, weil Jahwe seinen Geist auf sie legt!\"" },
      { number: 30, text: "Dann zog Mose sich mit den Ältesten Israels ins Lager zurück." },
      { number: 31, text: "Nun brach ein Wind los, von Jahwe geschickt. Er trieb Wachteln vom Meer heran und ließ sie ins Lager einfallen. Sie flatterten im Umkreis von etwa 30 Kilometern in einer Höhe einem Meter* über dem Boden.", footnotes: ["30 ... Meter. Wörtlich: einen Tagesmarsch weit und zwei Ellen Höhe. Andere verstehen den Text so, dass die Vögel einen Meter hoch auf dem Boden lagen und die Israeliten hindurchwaten mussten, was aber nicht zu Vers 32 passt."] },
      { number: 32, text: "Den ganzen Rest des Tages, die folgende Nacht und noch den nächsten Tag sammelte das Volk die Wachteln ein. Das wenigste, was einer zusammenbrachte, waren etwa eine halbe Tonne* Fleisch. Sie breiteten die Tiere rings um das Lager zum Dörren aus.", footnotes: ["eine halbe Tonne. Wörtlich: 10 Homer (Eselsladungen) = 2200 Liter Hohlraum = etwa 5000 Wachteln."] },
      { number: 33, text: "Doch hatten sie das Fleisch noch zwischen den Zähnen, es war noch nicht zerkaut, da flammte Jahwes Zorn gegen sie auf. Er schlug zu und traf das Volk mit einem schweren Schlag." },
      { number: 34, text: "Deshalb nannte man den Ort Kibrot-Taawa, Lustgräber, weil man dort die Leute begrub, die von der Gier gepackt worden waren." },
      { number: 35, text: "Von Kibrot-Taawa zog das Volk nach Hazerot* und schlug dort sein Lager auf.", footnotes: ["Hazerot. Dritter Lagerplatz, nachdem die Israeliten den Sinai verlassen hatten. Vielleicht En Khadra, 64 Kilometer nordöstlich von Dschebel Musa, wenn dies der Berg Sinai bzw. Horeb war (2. Mose 3,1)."] },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Mirjam und Aaron* redeten schlecht über Mose, weil er eine kuschitische* Frau geheiratet hatte.", heading: "Rebellion der eigenen Geschwister", footnotes: ["Mirjam und Aaron waren ältere Geschwister vonMose. Mirjam war etwa sieben Jahre älter (2. Mose 2,4), Aaron drei Jahre (2. Mose 7,7). Mose war zu diesem Zeitpunkt (ein reichliches Jahr nach dem Auszug aus Ägypten) 81 Jahre alt.", "Kuschitisch. Gemeint ist wohl nicht das Land Kusch (Nubien), sondern Kuschan in der Nachbarschaft von Midian (Habakuk 3,7). Dann würde es sich um die midianitische Priestertochter (2. Mose 2,15-22) handeln, die Anstoß erregte."] },
      { number: 2, text: "Sie sagten: \"Spricht Jahwe wirklich nur durch Mose? Spricht er nicht auch durch uns?\" Jahwe hörte es." },
      { number: 3, text: "Mose war ein demütiger Mann, bescheidener als alle anderen Menschen auf der Welt." },
      { number: 4, text: "Da sagte Jahwe plötzlich zu Mose, Aaron und Mirjam: \"Geht zum Zelt der Gottesbegegnung hinaus, ihr drei!\" So gingen sie aus dem Lager." },
      { number: 5, text: "Da kam Jahwe in einer Wolkensäule herab, stellte sich an den Eingang des Zeltes und rief Aaron und Mirjam. Beide traten vor," },
      { number: 6, text: "und er sagte: \"Hört her! Wenn ein Prophet Jahwes unter euch ist, dann offenbare ich mich ihm in einer Vision oder ich spreche im Traum zu ihm." },
      { number: 7, text: "Mit meinem Diener Mose aber ist es anders. Ihm habe ich die Verwaltung über mein ganzes Volk anvertraut." },
      { number: 8, text: "Mit ihm rede ich von Mund zu Mund, in klaren und eindeutigen Worten. Er nimmt sogar Jahwes Gestalt wahr. Wie konntet ihr es wagen, schlecht über meinen Diener Mose zu reden?\"" },
      { number: 9, text: "Der Zorn Jahwes flammte gegen sie auf, und er ging weg." },
      { number: 10, text: "Als die Wolke das Zelt verlassen hatte, stellte sich plötzlich heraus, dass Mirjam von Aussatz überschneit war. Aaron drehte sich zu ihr um, und wirklich: Sie war aussätzig." },
      { number: 11, text: "Da sagte er zu Mose: \"Bitte, mein Herr, leg nicht die Schuld dafür auf uns, dass wir uns erdreistet und gesündigt haben." },
      { number: 12, text: "Lass Mirjam doch nicht wie eine Totgeburt sein, deren Körper schon halb verwest ist, wenn sie aus dem Mutterschoß kommt!\"" },
      { number: 13, text: "Da schrie Mose zu Jahwe: \"Gott, lass sie doch wieder gesund werden!\"" },
      { number: 14, text: "Jahwe antwortete: \"Wenn ihr Vater ihr ins Gesicht gespuckt hätte, müsste sie sich sieben Tage lang schämen. Deshalb soll sie auch sieben Tage lang außerhalb des Lagers eingeschlossen bleiben. Dann könnt ihr sie wieder aufnehmen.\"" },
      { number: 15, text: "So wurde Mirjam sieben Tage außerhalb vom Lager eingeschlossen. Das Volk zog aber nicht weiter, bis Mirjam wieder aufgenommen war." },
      { number: 16, text: "Dann verließen sie Hazerot und schlugen ihr Lager in der Wüste Paran auf." },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Die Erkundung des Landes Kanaan" },
      { number: 2, text: "\"Du kannst einige Männer losschicken*, die das Land Kanaan erkunden sollen, das ich den Israeliten geben will! Nimm dazu aus jedem Stamm je einen der führenden Männer!\"", footnotes: ["losschicken. Die Verbform macht deutlich, dass Gott hier keinen Befehl, sondern eine Erlaubnis gab (siehe 5. Mose 1,22)."] },
      { number: 3, text: "Da schickte Mose die Männer von der Wüste Paran aus los, wie Jahwe es ihm erlaubt hatte. Sie alle waren Führer unter den Israeliten." },
      { number: 4, text: "Es waren aus dem Stamm Ruben: Schammua Ben-Sakkur;" },
      { number: 5, text: "aus dem Stamm Simeon: Schafat Ben-Hori;" },
      { number: 6, text: "aus dem Stamm Juda: Kaleb Ben-Jefunne;" },
      { number: 7, text: "aus dem Stamm Issachar: Jigal Ben-Josef;" },
      { number: 8, text: "aus dem Stamm Efraïm: Hoschea Ben-Nun;" },
      { number: 9, text: "aus dem Stamm Benjamin: Palti Ben-Rafu;" },
      { number: 10, text: "aus dem Stamm Sebulon: Gaddiël Ben-Sodi;" },
      { number: 11, text: "aus dem Stamm Manasse: Gaddi Ben-Susi;" },
      { number: 12, text: "aus dem Stamm Dan: Ammiël Ben-Gemalli;" },
      { number: 13, text: "aus dem Stamm Ascher: Setur Ben-Michael;" },
      { number: 14, text: "aus dem Stamm Naftali: Nachbi Ben-Wofsi;" },
      { number: 15, text: "aus dem Stamm Gad: Gëuël Ben-Machi." },
      { number: 16, text: "Diese zwölf Männer schickte Mose aus, um das Land zu erkunden. Hoschea Ben-Nun gab er den Namen Josua*.", footnotes: ["Josua. Hebräisch: Jehoschua. Hoschea bedeutet: Rettung. Durch Hinzufügung des J verweisen die ersten beiden Konsonanten JH jetzt auf Jahwe. Also bedeutet Josua: Jahwe ist Rettung."] },
      { number: 17, text: "Als Mose sie losschickte, sagte er zu ihnen: \"Nehmt den Weg durch den Negev* und steigt dann auf das Gebirge.", footnotes: ["Negev. Das heiße Südland Israels, zum Teil gebirgige Wüste. In biblischer Zeit war der Negev noch fruchtbar und besaß 29 Städte (Josua 15,21-32)."] },
      { number: 18, text: "Seht euch das Land und die Menschen dort genau an. Findet heraus, ob sie stark oder schwach, wenig oder zahlreich sind," },
      { number: 19, text: "ob das Land gut oder schlecht ist! Achtet darauf, ob sie in offenen Siedlungen wohnen oder in befestigten Städten." },
      { number: 20, text: "Seht, ob das Land fruchtbar ist und ob es dort Wälder gibt. Fasst Mut und bringt Proben von den Früchten des Landes mit!\" Es war gerade die Jahreszeit, in der die ersten Trauben reif werden." },
      { number: 21, text: "So zogen sie hinauf und erkundeten das Land von der Wüste Zin* bis Rehob bei Lebo-Hamat*.", footnotes: ["Zin. Wüste südlich von Kanaan, offenbar ein Teil der Wüste Paran.", "Rehob bei Lebo-Hamat. Orte im Libanon, etwa 70 Kilometer nördlich vom Gipfel des Hermon entfernt."] },
      { number: 22, text: "Sie zogen durch den Negev und kamen nach Hebron*. Dort wohnten Ahiman, Scheschai und Talmai, die Nachkommen Anaks. Die Stadt Hebron war noch vor Zoan* in Ägypten gegründet worden.", footnotes: ["Hebron. Die Stadt liegt etwa 35 km südlich von Jerusalem und 30 km westlich vom Toten Meer.", "Zoan. Die Stadt ist wahrscheinlich mit Tanis identisch, das im nordöstlichen Teil des Nildeltas lag."] },
      { number: 23, text: "Als die Männer schließlich ins Traubental* kamen, schnitten sie eine Weinranke mit einer Traube ab und trugen sie an einer Stange, auch Granatäpfel und Feigen nahmen sie mit.", footnotes: ["Traubental. Offenbar auf der Rückreise kamen die Kundschafter durch dieses Bach- oder Flusstal (Wadi), das nur in der Regenzeit Wasser führte. Das muss wieder in der Nähe von Hebron gewesen sein."] },
      { number: 24, text: "Das Tal bekam erst später den Namen Wadi Eschkol, Traubental, weil die Israeliten dort eine Traube abgeschnitten hatten." },
      { number: 25, text: "Vierzig Tage lang hatten sie das Land erkundet" },
      { number: 26, text: "und kehrten dann zu Mose und Aaron und der ganzen Gemeinschaft Israels nach Kadesch* in die Wüste Paran zurück. Sie erstatteten ihnen Bericht und zeigten die mitgebrachten Früchte.", footnotes: ["Kadesch (Kadesch-Barnea) lag an der Südgrenze von Kanaan, etwa 80 km südwestlich von Beerscheba."] },
      { number: 27, text: "Sie berichteten Mose: \"Wir sind in dem Land gewesen, in das du uns geschickt hast. Es ist wirklich ein Land, das von Milch und Honig überfließt. Sieh dir nur diese Früchte an!" },
      { number: 28, text: "Allerdings ist das Volk, das dort wohnt, stark, und seine Städte sind groß und gut befestigt. Und dann haben wir auch noch die Söhne Anaks dort gesehen!" },
      { number: 29, text: "Im Negev wohnen die Amalekiter, im Bergland die Hetiter, Jebusiter und Amoriter, am Meer und in der Jordanebene die Kanaaniter.\"" },
      { number: 30, text: "Kaleb beschwichtigte das Volk, das über Mose aufgebracht war. Er sagte: \"Wir werden hinaufziehen und das Land in Besitz nehmen! Wir können es sehr wohl erobern.\"" },
      { number: 31, text: "Aber die anderen Kundschafter sagten: \"Wir können es nicht! Das Volk im Land ist stärker als wir.\"" },
      { number: 32, text: "Sie erzählten den Israeliten schreckliche Dinge über das Land, das sie erkundet hatten. \"Dieses Land verschlingt seine Bewohner\", sagten sie. \"Alle Leute, die wir gesehen haben, sind sehr groß," },
      { number: 33, text: "besonders die Nachkommen Anaks, die Riesen. Ihnen gegenüber kamen wir uns wie Heuschrecken vor. Und so haben sie auch uns angesehen.\"" },
    ] },
    { number: 14, verses: [
      { number: 1, text: "Da fing die ganze Volksgemeinschaft an, laut zu schreien. Und sie weinten die ganze Nacht.", heading: "Aufruhr im Volk" },
      { number: 2, text: "Alle Israeliten beklagten sich über Mose und Aaron, und die ganze Menge sagte zu ihnen: \"Wären wir doch im Land Ägypten gestorben oder hier in der Wüste." },
      { number: 3, text: "Wozu bringt uns Jahwe in dieses Land? Sollen wir jetzt im Kampf umkommen, sollen unsere Frauen und unsere kleinen Kinder zur Beute werden? Wäre es nicht besser für uns, nach Ägypten zurückzukehren?\"" },
      { number: 4, text: "Schon sagten einige zueinander: \"Lasst uns einen neuen Anführer wählen und nach Ägypten zurückkehren!\"" },
      { number: 5, text: "Da warfen sich Mose und Aaron vor den Augen der ganzen Versammlung der Israeliten nieder, mit dem Gesicht zum Boden." },
      { number: 6, text: "Doch Josua Ben-Nun und Kaleb Ben-Jefunne von den Kundschaftern rissen entsetzt ihre Obergewänder ein*", footnotes: ["rissen ... ein. Als Zeichen von Trauer und Entsetzen riss man vom Halsausschnitt an das Gewand mit einem heftigen Ruck etwa eine Handlänge ein."] },
      { number: 7, text: "und sagten der ganzen Menge der Israeliten: \"Das Land, das wir erkundet haben, ist sehr, sehr gut." },
      { number: 8, text: "Wenn Jahwe Gefallen an uns hat, wird er uns in dieses Land bringen, ein Land, das von Milch und Honig überfließt." },
      { number: 9, text: "Lehnt euch doch nicht gegen ihn auf! Und habt doch keine Angst vor dem Volk dieses Landes! Wir werden sie verschlingen wie Brot, denn ihr Schutz ist von ihnen gewichen und Jahwe ist mit uns! Fürchtet euch doch nicht vor ihnen!\"" },
      { number: 10, text: "Schon sprach die ganze Menge davon, sie zu steinigen, da erschien die Herrlichkeit Jahwes allen Israeliten am Zelt der Gottesbegegnung." },
      { number: 11, text: "Jahwe sagte zu Mose: \"Wie lange will mich dieses Volk noch verachten? Wie lange noch wollen sie mir nicht glauben, obwohl ich ihnen so viele Zeichen meiner Macht und Fürsorge gab?" },
      { number: 12, text: "Ich will sie mit der Pest schlagen und beseitigen. Aber dich werde ich zu einem Volk machen, größer und stärker als sie.\"" },
      { number: 13, text: "Doch Mose sagte zu Jahwe: \"Aber das werden die Ägypter hören. Denn aus ihrer Mitte hast du dieses Volk durch deine Kraft herausgeführt." },
      { number: 14, text: "Und sie werden zu den Bewohnern dieses Landes sagen, sie hätten gehört, dass du, Jahwe, bei diesem Volk bist, dass du ihnen Auge in Auge erscheinst, dass deine Wolke über ihnen steht und du in einer Wolkensäule vor ihnen hergehst bei Tag und in einer Feuersäule bei Nacht." },
      { number: 15, text: "Wenn du nun dieses Volk auf einen Schlag tötest, werden die Völker, die von deinen Taten gehört haben, sagen:" },
      { number: 16, text: "'Weil Jahwe dieses Volk nicht in das Land bringen konnte, das er ihnen mit Eid zugesichert hatte, schlachtete er sie in der Wüste ab.'" },
      { number: 17, text: "Gerade jetzt möge die Kraft Jahwes sich als groß erweisen, wie du gesagt hast:" },
      { number: 18, text: "'Jahwe ist sehr geduldig und gnädig, er vergibt Schuld und Vergehen, lässt aber nicht ungestraft, sondern sucht die Schuld der Väter an den Söhnen heim bis zur dritten und vierten Generation.'" },
      { number: 19, text: "Vergib doch die Schuld dieses Volkes, wie es deiner großen Gnade entspricht und wie du diesem Volk von Ägypten an bis hierher immer wieder vergeben hast!\"" },
      { number: 20, text: "Da sagte Jahwe: \"Ich vergebe nach deinem Wort!" },
      { number: 21, text: "Aber so gewiss ich lebe, und die ganze Erde von der Herrlichkeit Jahwes erfüllt werden wird:" },
      { number: 22, text: "Alle Männer, die meine Herrlichkeit und meine Wunderzeichen gesehen haben, die ich in Ägypten und in der Wüste tat, und die mich nun zehnmal auf die Probe gestellt und nicht auf mich gehört haben," },
      { number: 23, text: "sie werden das Land nicht sehen, das ich ihren Vorfahren unter Eid zugesagt habe. Alle, die mich verachten, werden es nicht sehen." },
      { number: 24, text: "Aber meinen Diener Kaleb, in dem ein anderer Geist war und der treu zu mir gehalten hat, ihn werde ich in das Land bringen, das er schon betreten hat, und seine Nachkommen werden es in Besitz nehmen." },
      { number: 25, text: "Die Amalekiter und Kanaaniter bleiben in der Ebene wohnen. Brecht also morgen auf und zieht durch die Wüste in Richtung Schilfmeer.\"" },
      { number: 26, text: "Jahwe sagte zu Mose und Aaron:", heading: "Vierzig Jahre Wüste" },
      { number: 27, text: "\"Wie lange soll es mit dem Murren dieser bösen Versammlung von Israeliten noch weitergehen? Ich habe wohl gehört, wie sie gegen mich murren." },
      { number: 28, text: "Sag zu ihnen: 'So wahr ich lebe, spricht Jahwe, ich werde genau das mit euch machen, was ihr vor mir gesagt habt:" },
      { number: 29, text: "In dieser Wüste werden eure Leichen zerfallen, alle wehrfähigen Männer, die zwanzig Jahre und älter sind, weil ihr gegen mich gemurrt habt." },
      { number: 30, text: "Niemals werdet ihr in das Land kommen, das ich euch mit Eid zugesichert habe. Ausgenommen sind nur Kaleb Ben-Jefunne und Josua Ben-Nun." },
      { number: 31, text: "Aber eure kleinen Kinder, von denen ihr gesagt habt, sie würden zur Beute werden, sie werde ich hinbringen, sie sollen das Land kennenlernen, das ihr verschmäht habt." },
      { number: 32, text: "Doch eure Leichen werden hier in der Wüste zerfallen." },
      { number: 33, text: "Und eure Kinder werden vierzig Jahre lang in der Wüste Hirten sein und eure Hurereien tragen müssen, bis eure Leichen in der Wüste vollzählig sind." },
      { number: 34, text: "Nach der Zahl der Tage, die ihr das Land erkundet habt, werdet ihr nun vierzig Jahre, für jeden Tag ein Jahr, eure Schuld tragen müssen. Ihr sollt merken, wie es ist, wenn ich mich abwende!'" },
      { number: 35, text: "Ich, Jahwe, habe es gesagt. Das werde ich dieser ganzen bösen Gemeinschaft antun, die sich gegen mich zusammengerottet hat! Hier in dieser Wüste werden sie umkommen, hier sollen sie sterben!\"" },
      { number: 36, text: "Die Männer, die Mose geschickt hatte, um das Land zu erkunden, und die nach ihrer Rückkehr die ganze Menge dazu gebracht hatten, gegen ihn aufzubegehren, indem sie ein böses Gerücht über das Land verbreiteten," },
      { number: 37, text: "diese Männer starben auf einen Schlag vor Jahwe." },
      { number: 38, text: "Von den Kundschaftern blieben nur Josua Ben-Nun und Kaleb Ben-Jefunne am Leben." },
      { number: 39, text: "Mose brachte allen Israeliten die Antwort Jahwes, und das Volk trauerte sehr." },
      { number: 40, text: "Früh am anderen Morgen aber rüsteten sie sich, um zum Kamm des Gebirges hinaufzuziehen. Sie sagten: \"Jetzt sind wir bereit. Wir ziehen zu dem Ort hinauf, von dem Jahwe geredet hat. Ja, wir haben gesündigt.\"" },
      { number: 41, text: "Aber Mose sagte zu ihnen: \"Warum wollt ihr den Befehl Jahwes schon wieder übertreten? Es wird euch nicht gelingen!" },
      { number: 42, text: "Zieht nicht hinauf, sonst werdet ihr von euren Feinden geschlagen, denn Jahwe ist nicht bei euch!" },
      { number: 43, text: "Dort stehen euch die Amalekiter und Kanaaniter entgegen, und ihr werdet im Kampf umkommen. Jahwe wird nicht mit euch sein, denn ihr habt euch von ihm abgekehrt.\"" },
      { number: 44, text: "Aber sie hatten es sich in den Kopf gesetzt, zum Kamm des Gebirges hinauf zu ziehen. Doch Mose und die Lade des Bundes mit Jahwe verließen das Lager nicht." },
      { number: 45, text: "Die Amalekiter und Kanaaniter, die das Gebirge bewohnten, griffen die Israeliten von oben her an, schlugen sie in die Flucht und versprengten sie bis Horma*.", footnotes: ["Horma war eine Stadt, 27 km südlich von Hebron."] },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Jahwe befahl Mose,", heading: "Die Jahre in der Wüste (15-20)\nVorschriften für Speis- und Trankopfer" },
      { number: 2, text: "den Israeliten zu sagen: \"Wenn ihr einmal in das Land eurer Wohnstätten kommt, das ich euch gebe," },
      { number: 3, text: "und ihr Jahwe ein Feueropfer von Rindern, Schafen oder Ziegen darbringt, ein Brand- oder Schlachtopfer, um ein Gelübde zu erfüllen oder als freiwillige Gabe, oder an euren Festen, um Jahwe einen Geruch zu bereiten, der ihm angenehm ist," },
      { number: 4, text: "dann soll der, der Jahwe seine Opfergabe bringt, auch ein Speisopfer dabei haben: zwei Litergefäße* mit Feinmehl, das mit einem knappen Liter* Öl vermengt ist.", footnotes: ["zwei Litergefäße. Wörtlich: ein Zehntel (Efa) = 2,2 Liter", "ein knapper Liter. Wörtlich: ein Viertel Hin = 0,9 Liter"] },
      { number: 5, text: "Wenn du ein Lamm als Brand- oder Schlachtopfer bringst, muss als Trankopfer auch ein knapper Liter Wein dabei sein." },
      { number: 6, text: "Bei einem Schafbock sollst du als Speisopfer viereinhalb Liter* Feinmehl bringen, das mit eineindrittel Liter* Öl vermengt wurde,", footnotes: ["viereinhalb Liter. Wörtlich: zwei Zehntel (Efa) = 4,4 Liter", "eineindrittel Liter. Wörtlich: ein Drittel Hin = 1,3 Liter"] },
      { number: 7, text: "und als Trankopfer eineindrittel Liter Wein: ein Geruch, der Jahwe angenehm ist." },
      { number: 8, text: "Wenn du ein junges Rind als Brand- oder Schlachtopfer bringst, um ein besonderes Gelübde zu erfüllen oder einfach als Freudenopfer für Jahwe," },
      { number: 9, text: "dann sollst du dazu sechseinhalb Liter* Feinmehl bringen, das mit knapp zwei Litern* Öl vermengt wurde,", footnotes: ["secheinhalb Liter. Wörtlich: drei Zehntel (Efa) = 6,6 Liter", "zwei Liter. Wörtlich: ein halbes Hin = 1,9 Liter"] },
      { number: 10, text: "und als Trankopfer knapp zwei Liter Wein. Es ist ein Feueropfer zum angenehmen Geruch für Jahwe." },
      { number: 11, text: "So soll man es bei jedem Rind und jedem Schafbock, bei jedem Schaf und jeder Ziege machen," },
      { number: 12, text: "und zwar bei jedem einzelnen Tier, wie viel ihr auch opfert." },
      { number: 13, text: "Das gilt für jeden Einheimischen, der ein Feueropfer zum angenehmen Geruch für Jahwe darbringt." },
      { number: 14, text: "Wenn ein Fremder, der bei euch weilt oder schon seit Generationen unter euch lebt, Jahwe ein Feueropfer zum angenehmen Geruch bringen will, dann soll er es genauso machen wie ihr." },
      { number: 15, text: "Im ganzen Reich soll ein und dieselbe Ordnung für euch und den Fremden gelten, der bei euch lebt. Das gilt auch für alle kommenden Generationen. Vor Jahwe ist der Fremde euch gleich." },
      { number: 16, text: "Ein und dasselbe Gesetz, ein und dasselbe Recht gelten für euch und den Fremden, der bei euch wohnt.\"" },
      { number: 17, text: "Jahwe befahl Mose,", heading: "Das erste Brot" },
      { number: 18, text: "den Israeliten zu sagen: \"Wenn ihr in das Land kommt, in das ich euch bringe," },
      { number: 19, text: "und vom Brot des Landes esst, sollt ihr eine Abgabe für Jahwe entrichten." },
      { number: 20, text: "Als erste Gabe eures Teigs sollt ihr ein Lochbrot als Abgabe entrichten, genauso wie die Abgabe vom Dreschplatz." },
      { number: 21, text: "Das erste Brot der neuen Ernte gehört Jahwe. Das gilt auch für alle kommenden Generationen.\"" },
      { number: 22, text: "\"Und wenn ihr oder eure Nachkommen aus Versehen gegen eins dieser Gebote sündigt, die Jahwe Mose", heading: "Opfer für Vergehen aus Versehen" },
      { number: 23, text: "von Anfang an mitgeteilt hat," },
      { number: 24, text: "falls es von der Gemeinschaft unbemerkt aus Versehen geschehen ist, dann soll die ganze Versammlung Jahwe einen jungen Stier als Brandopfer zum angenehmen Geruch bringen und dazu gemäß der Vorschrift das Speis- und Trankopfer und einen Ziegenbock als Sündopfer." },
      { number: 25, text: "Der Priester soll für die ganze Versammlung der Israeliten Sühne erwirken. Dann wird ihnen vergeben werden, denn es war ein Versehen, und sie haben ihre Opfergabe, ein Feueropfer für Jahwe und das Sündopfer, für ihr Versehen vor Jahwe gebracht." },
      { number: 26, text: "Der ganzen Gemeinschaft der Israeliten und den Fremden, die unter ihnen leben, wird vergeben werden, denn es passierte dem Volk aus Versehen." },
      { number: 27, text: "Wenn eine Einzelperson aus Versehen sündigt, dann soll sie eine einjährige Ziege als Sündopfer bringen." },
      { number: 28, text: "Der Priester soll Sühne für die Person erwirken, die aus Versehen vor Jahwe gesündigt hat, dann wird ihr vergeben." },
      { number: 29, text: "Für den Einheimischen bei den Israeliten und für den Fremden, der unter ihnen lebt, soll ein und dasselbe Gesetz gelten, wenn jemand etwas aus Versehen tut." },
      { number: 30, text: "Wenn jemand aber mit Absicht handelt, der lästert Jahwe. Diese Person muss vom Volk beseitigt werden, sei es ein Einheimischer oder ein Fremder." },
      { number: 31, text: "Denn sie hat das Wort Jahwes verachtet und sein Gebot ungültig gemacht. Diese Person muss unbedingt beseitigt werden. Die Schuld dafür liegt auf ihr selbst.\"" },
      { number: 32, text: "Als die Israeliten noch in der Wüste waren, ertappten sie einen Mann, der am Sabbat Holz aufsammelte.", heading: "Ein Fall von Sabbatschändung" },
      { number: 33, text: "Die Leute, die ihn ertappt hatten, brachten ihn zu Mose und Aaron vor die ganze Versammlung." },
      { number: 34, text: "Sie sperrten ihn ein, denn es war noch nicht entschieden, was mit ihm geschehen sollte." },
      { number: 35, text: "Da sagte Jahwe zu Mose: \"Der Mann muss unbedingt getötet werden. Die ganze Menge soll ihn außerhalb vom Lager steinigen.\"" },
      { number: 36, text: "Da führte ihn die ganze Menge vor das Lager und steinigte ihn dort, dass er starb, wie Jahwe es Mose befohlen hatte." },
      { number: 37, text: "Jahwe sagte zu Mose:", heading: "Quasten an der Kleidung" },
      { number: 38, text: "\"Sag den Israeliten, dass sie sich Quasten an die Zipfel ihrer Obergewänder nähen. Das gilt auch für die kommenden Generationen. Und an jeder Quaste soll eine violette Kordel sein." },
      { number: 39, text: "Und wenn ihr die Quasten seht, sollt ihr an alle Gebote Jahwes denken und sie einhalten. Ihr sollt euch nicht von euren Herzen und Augen zur Untreue verführen lassen," },
      { number: 40, text: "sondern an alle meine Gebote denken und sie tun. Ihr sollt eurem Gott heilig sein." },
      { number: 41, text: "Ich bin Jahwe, euer Gott, der euch aus Ägypten herausgeführt hat, um euer Gott zu sein. Ich bin Jahwe, euer Gott!\"" },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Korach Ben-Jizhar, ein Levit von den Nachkommen Kehats, erhob sich zusammen mit den Rubeniten Datan und Abiram, den Söhnen Eliabs, und On Ben-Pelet", heading: "Aufruhr der Anhänger Korachs" },
      { number: 2, text: "gegen Mose. Hinter ihnen standen 250 führende Israeliten, Berufene der Gemeinschaft, angesehene Männer." },
      { number: 3, text: "Sie rotteten sich gegen Mose und Aaron zusammen und warfen ihnen vor: \"Ihr nehmt euch zu viel heraus! Die ganze Gemeinschaft ist heilig, und zwar alle. Und Jahwe ist in ihrer Mitte. Warum erhebt ihr euch über die Gemeinde Jahwes?\"" },
      { number: 4, text: "Als Mose das hörte, warf er sich nieder, mit dem Gesicht zum Boden." },
      { number: 5, text: "Dann sagte er zu Korach und seiner ganzen Versammlung: \"Morgen wird Jahwe zeigen, wer zu ihm gehört und wer heilig ist, dass er ihn in seine Nähe kommen lässt." },
      { number: 6, text: "Macht Folgendes, du, Korach, und ihr, seine Anhänger: Nehmt euch Räucherpfannen," },
      { number: 7, text: "tut morgen früh Glut hinein und legt Weihrauch vor Jahwe darauf. Und der Mann, den Jahwe erwählen wird, der ist heilig. Ihr nehmt euch zu viel heraus, ihr Leviten!\"" },
      { number: 8, text: "Dann sagte Mose zu Korach: \"Hört zu, ihr Leviten!" },
      { number: 9, text: "Ist es euch zu wenig, dass Israels Gott euch aus der Menge der Israeliten ausgesondert hat, sodass ihr in seine Nähe kommen und den Dienst an der Wohnung Jahwes ausüben dürft und dass ihr vor der Gemeinde steht, um ihr zu dienen?" },
      { number: 10, text: "Er ließ dich und deine Brüder, die Leviten, in seine Nähe kommen. Und jetzt wollt ihr auch noch das Priesteramt!" },
      { number: 11, text: "Du und dein ganzer Anhang, ihr habt euch gegen Jahwe zusammengerottet. Denn wer ist schon Aaron, dass ihr gegen ihn murrt?\"" },
      { number: 12, text: "Mose ließ Datan und Abiram, die Söhne Eliabs, rufen. Aber sie ließen ihm sagen: \"Wir kommen nicht!" },
      { number: 13, text: "Ist es dir zu wenig, dass du uns aus einem Land, wo Milch und Honig fließen, heraufgeführt hast, um uns in der Wüste sterben zu lassen? Musst du dich auch noch als Herrscher aufspielen?" },
      { number: 14, text: "Hast du uns denn in ein Land geführt, wo Milch und Honig fließen, hast uns Äcker und Weinberge zum Besitz gegeben? Hältst du uns denn für blind? Nein, wir kommen nicht!\"" },
      { number: 15, text: "Da wurde Mose sehr zornig und sagte zu Jahwe: \"Wende dich ihrem Opfer nicht zu! Nicht einen einzigen Esel habe ich ihnen weggenommen. Keinem Einzigen von ihnen habe ich etwas angetan.\"" },
      { number: 16, text: "Zu Korach sagte Mose: \"Morgen wirst du mit deinem Anhang vor Jahwe erscheinen, du, sie und Aaron!" },
      { number: 17, text: "Jeder nehme seine Räucherpfanne, lege Weihrauch darauf und bringe sie vor Jahwe, 250 Räucherpfannen, auch du und Aaron, jeder seine Räucherpfanne!\"" },
      { number: 18, text: "So nahm jeder seine Räucherpfanne, legte Glut und Weihrauch darauf und trat an den Eingang vom Zelt der Gottesbegegnung, auch Mose und Aaron." },
      { number: 19, text: "Korach hatte seine ganze Anhängerschaft gegen Mose und Aaron am Eingang vom Zelt der Gottesbegegnung zusammengebracht. Da erschien die Herrlichkeit Jahwes vor der ganzen Versammlung." },
      { number: 20, text: "Und Jahwe sagte zu Mose und Aaron:" },
      { number: 21, text: "\"Entfernt euch aus dieser Versammlung! Ich will sie in einem Augenblick vernichten.\"" },
      { number: 22, text: "Da warfen die beiden sich nieder und sagten: \"Gott, du Gott des Lebens aller Menschen! Ein einziger Mann hat gesündigt, und du wirst zornig über die ganze Versammlung?\"" },
      { number: 23, text: "Da befahl Jahwe Mose," },
      { number: 24, text: "der Versammlung zu sagen: \"Entfernt euch aus dem Umkreis der Wohnungen von Korach, Datan und Abiram!\"" },
      { number: 25, text: "Mose stand auf und ging mit den Ältesten Israels zu Datan und Abiram." },
      { number: 26, text: "Er sagte zu der ganzen Versammlung: \"Entfernt euch von den Zelten dieser gottlosen Männer! Fasst nichts an, was ihnen gehört! Sonst werdet ihr samt ihnen und ihren Sünden weggerissen!\"" },
      { number: 27, text: "Alle entfernten sich aus dem Umkreis der Wohnungen von Korach, Datan und Abiram. Datan und Abiram waren herausgekommen und standen mit ihren Frauen, ihren Söhnen und kleinen Kindern am Eingang ihrer Zelte." },
      { number: 28, text: "Mose sagte: \"An dem, was jetzt geschieht, sollt ihr erkennen, dass Jahwe mich beauftragt hat, all diese Taten zu vollbringen, und dass ich das nicht eigenmächtig getan habe." },
      { number: 29, text: "Wenn diese hier sterben, wie alle Menschen sterben; wenn sie zur Rechenschaft gezogen werden, wie das bei allen Menschen geschieht, dann hat Jahwe mich nicht beauftragt." },
      { number: 30, text: "Wenn Jahwe aber etwas Unerhörtes schafft, wenn die Erde ihren Rachen aufsperrt und sie mit allem, was zu ihnen gehört, verschlingt und sie lebendig zu den Toten hinabstürzen, dann werdet ihr erkennen, dass diese Männer Jahwe verachtet haben.\"" },
      { number: 31, text: "Kaum hatte er das gesagt, da spaltete sich der Boden unter ihnen," },
      { number: 32, text: "die Erde öffnete ihren Rachen und verschlang sie mit allem Hab und Gut, mit ihren Familien und allen Anhängern Korachs." },
      { number: 33, text: "So stürzten sie mit allem, was zu ihnen gehörte, lebendig zu den Toten hinab, und die Erde schloss sich über ihnen. So wurden sie mitten aus der Versammlung weggerissen." },
      { number: 34, text: "Ganz Israel, das um sie herumstand, floh bei ihrem Geschrei. \"Dass uns nur die Erde nicht verschlingt!\", riefen sie." },
      { number: 35, text: "Und die 250 Männer, die das Rauchopfer dargebracht hatten, verzehrte ein Feuer, das von Jahwe ausging." },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Dann sagte Jahwe zu Mose:" },
      { number: 2, text: "\"Befiehl dem Priester Eleasar Ben-Aaron, die Räucherpfannen aus der Brandstätte aufzuheben – sie sind nun einmal geheiligt – und die glühenden Kohlen darin weit umher zu verstreuen." },
      { number: 3, text: "Aus den Räucherpfannen dieser Männer, die durch ihre Sünde das Leben verloren haben, lass Bleche zum Überzug für den Altar schmieden. Denn sie haben die Pfannen vor Jahwe gebracht, und so sind sie heilig geworden. Nun sollen sie den Israeliten zu einem Zeichen sein.\"" },
      { number: 4, text: "Da hob der Priester Eleasar die Räucherpfannen aus Bronze auf, die die Verbrannten mitgebracht hatten, und ließ sie als Überzug für den Altar breithämmern." },
      { number: 5, text: "Es wurde ein Erinnerungszeichen für die Israeliten, damit kein Unbefugter, jemand, der nicht zu den Nachkommen Aarons gehört, in die Nähe Jahwes kommt, um Weihrauch aufsteigen zu lassen, damit es ihm nicht ergehe wie Korach und seinen Anhängern. So hatte Jahwe es durch Mose befohlen." },
      { number: 6, text: "Am nächsten Tag murrte die ganze Menge der Israeliten gegen Mose und Aaron. \"Ihr habt das Volk Jahwes sterben lassen!\", warfen sie ihnen vor.", heading: "Dauerndes Murren" },
      { number: 7, text: "Als die Versammlung, die sich gegen Mose und Aaron gestellt hatte, zum Zelt der Gottesbegegnung blickte, sahen sie es auf einmal von der Wolke bedeckt und die Herrlichkeit Jahwes erschien." },
      { number: 8, text: "Da traten Mose und Aaron vor das Zelt der Gottesbegegnung." },
      { number: 9, text: "Jahwe sagte zu Mose:" },
      { number: 10, text: "\"Entfernt euch aus dieser Versammlung! Ich will sie in einem Augenblick vernichten.\" Da warfen die beiden sich nieder." },
      { number: 11, text: "Mose sagte zu Aaron: \"Nimm die Räucherpfanne und Glut vom Altar und gib Weihrauch darauf und bring es schnell zur Versammlung, um Sühne für sie zu erwirken. Denn der Zorn ist von Jahwe ausgegangen und das Sterben hat schon begonnen.\"" },
      { number: 12, text: "Aaron nahm die Räucherpfanne, wie Mose es gesagt hatte, und lief mitten in die Versammlung hinein. Tatsächlich hatte das Sterben schon begonnen. Aaron legte den Weihrauch auf und erwirkte so Sühne für das Volk." },
      { number: 13, text: "Er stand zwischen den Toten und den Lebenden. Da hörte das Sterben auf." },
      { number: 14, text: "14.700 Menschen waren gestorben, nicht gerechnet die, die wegen Korach umgekommen waren." },
      { number: 15, text: "Aaron kehrte zu Mose an den Eingang vom Zelt der Gottesbegegnung zurück. Dem Sterben war Einhalt geboten." },
      { number: 16, text: "Jahwe sagte zu Mose:", heading: "Der blühende Stab Aarons" },
      { number: 17, text: "\"Rede zu den Israeliten und lass dir von jeder Familie einen Stab geben, von ihren Fürsten, Familie um Familie, insgesamt zwölf. Schreib auf jeden Stab den Namen des Stammes." },
      { number: 18, text: "Aarons Namen schreibst du auf den Stab Levis, denn je ein Stab soll für ein Stammesoberhaupt stehen." },
      { number: 19, text: "Dann sollst du die Stäbe ins Zelt der Gottesbegegnung bringen und vor dem Bundesgesetz niederlegen, dort, wo ich euch begegne." },
      { number: 20, text: "Der Stab von dem Mann, den ich auswähle, wird Blätter treiben. So werde ich das Murren der Israeliten gegen euch zum Schweigen bringen.\"" },
      { number: 21, text: "Mose sagte das alles den Israeliten, und ihre Fürsten gaben ihm je einen Stab für ein Stammesoberhaupt. Es waren zwölf Stäbe, und der Stab Aarons war dabei." },
      { number: 22, text: "Mose legte die Stäbe im Zelt vor Jahwe und dem Bundesgesetz nieder." },
      { number: 23, text: "Als er am nächsten Morgen ins Zelt zum Bundesgesetz ging, hatte der Stab Aarons auf einmal ausgeschlagen, Knospen hervorgebracht, Blüten getrieben und Mandeln reifen lassen." },
      { number: 24, text: "Mose brachte alle Stäbe von Jahwe zu allen Israeliten hinaus. Sie sahen sie und jeder nahm seinen Stab." },
      { number: 25, text: "Jahwe sagte zu Mose: \"Bring den Stab Aarons zurück vor das Bundesgesetz. Er soll dort als Zeichen für Widerspenstige aufbewahrt werden. So sollst du ihrem Murren vor mir ein Ende machen, damit sie nicht sterben.\"" },
      { number: 26, text: "Mose machte es, wie Jahwe ihm befohlen hatte." },
      { number: 27, text: "Die Israeliten aber sagten zu Mose: \"Wir werden alle noch umkommen, wir sind verloren. Bald wird keiner von uns mehr übrig sein." },
      { number: 28, text: "Jeder, der in die Nähe von Jahwes Wohnung kommt, stirbt. Sollen wir denn allesamt umkommen?\"" },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Jahwe sagte zu Aaron: \"Du, deine Söhne und dein ganzes Vaterhaus, ihr müsst die Schuld tragen, wenn sich jemand am Heiligtum vergeht. Und wenn sich jemand im Priesterdienst vergeht, dann musst du mit deinen Söhnen die Schuld tragen.", heading: "Die Verantwortung der Priester und Leviten" },
      { number: 2, text: "Lass auch deine Brüder vom Stamm Levi, deinem väterlichen Stamm, sich dir anschließen und dir dienen, während du mit deinen Söhnen vor dem Zelt des Bundesgesetzes bist." },
      { number: 3, text: "Sie sollen ihre Aufgaben für dich und das Zelt erfüllen, aber sie dürfen nicht in die Nähe der Gegenstände im Heiligtum und zum Altar kommen, damit sie nicht sterben, und ihr mit ihnen." },
      { number: 4, text: "Sie sollen dir beigeordnet sein und den Dienst am Zelt der Gottesbegegnung verrichten, alle Arbeiten, die dort anfallen. Aber kein Unbefugter darf in eure Nähe kommen." },
      { number: 5, text: "Ihr sollt eure Aufgaben am Heiligtum und am Altar verrichten, damit kein Zorngericht mehr über die Israeliten kommt." },
      { number: 6, text: "Seht, ich habe eure Brüder, die Leviten, von den Israeliten ausgesondert und euch als Geschenk für Jahwe übergeben, damit sie die Arbeit am Zelt der Gottesbegegnung tun." },
      { number: 7, text: "Du und deine Söhne mit dir, ihr sollt den Priesterdienst am Altar und innerhalb des Vorhangs tun. Das Priesteramt habe ich euch als Geschenk übergeben. Jeder Unbefugte, der sich nähert, muss getötet werden.\"" },
      { number: 8, text: "Jahwe sagte zu Aaron: \"Pass auf, ich habe dir die Verwaltung der für mich bestimmten Abgaben übertragen. Von allen heiligen Opfergaben der Israeliten habe ich dir und deinen Söhnen einen Anteil gegeben. Das gilt für alle Zeiten." },
      { number: 9, text: "Vom Höchstheiligen soll dir alles gehören, was nicht verbrannt wird: von allen Speisopfern, Sündopfern und Schuldopfern, die die Israeliten mir bringen. Als Höchstheiliges gehört es dir und deinen Nachkommen." },
      { number: 10, text: "Die männlichen Angehörigen der Priesterfamilien sollen es am höchst heiligen Ort essen, denn es soll dir heilig sein." },
      { number: 11, text: "Die Weihgaben der Israeliten gehören dir und allen deinen Nachkommen, Söhnen und Töchtern. Diese Ordnung gilt für alle Zeit. Jede Person in deinem Haus, die rein ist, darf davon essen." },
      { number: 12, text: "Das Beste vom Öl und das Beste von Most und Getreide, die ersten Gaben jeder Ernte, die sie Jahwe bringen, habe ich dir gegeben." },
      { number: 13, text: "Die ersten Früchte von allem, was auf ihrem Land wächst, die sie Jahwe bringen, sollen dir gehören. Jede Person in deinem Haus, die rein ist, darf davon essen." },
      { number: 14, text: "Alles geweihte Gut in Israel soll dir gehören." },
      { number: 15, text: "Alles, was zuerst aus dem Mutterschoß kommt, von Mensch und Tier, das sie Jahwe darbringen, soll dir gehören. Nur die Erstgeburt bei Menschen und bei unreinen Tieren musst du auslösen lassen." },
      { number: 16, text: "Das soll im Alter von einem Monat geschehen. Je nach deiner Schätzung soll der Wert fünf Silberstücke betragen, gewogen nach dem Vollgewicht des Heiligtums, ein Silberstück zu zwölf Gramm*.", footnotes: ["zwölf Gramm. Wörtlich: ein Schekel zu zwanzig Gera. Das Gewicht eines Schekels betrug nach archäologischen Funden durchschnittlich etwa 11,5 Gramm, ein Gera demnach rund 0,6 Gramm."] },
      { number: 17, text: "Die Erstgeburten von Rindern, Schafen oder Ziegen dürft ihr nicht auslösen lassen. Sie sind heilig. Ihr Blut sollst du an den Altar sprengen, und ihr Fett sollst du als Feueropfer in Rauch aufgehen lassen zum angenehmen Geruch für Jahwe." },
      { number: 18, text: "Ihr Fleisch soll dir gehören, so wie die Brust beim Schwingopfer und die rechte Keule." },
      { number: 19, text: "Alle Abgaben von den heiligen Gaben, die die Israeliten Jahwe bringen, habe ich dir und deinen Familienangehörigen gegeben. Diese Ordnung gilt für alle Zeit. Es ist ein ewiger Salzbund* vor Jahwe für dich und deine Nachkommen.\"", footnotes: ["Salzbund. Nach 3. Mose 2,13 war Salz ein Zeichen des Gottesbundes. Vielleicht sollte es die Priesterfamilien immer an diesen Bund erinnern, wenn sie von dem Opferfleisch aßen."] },
      { number: 20, text: "Jahwe sagte zu Aaron: \"Wenn die Israeliten in ihr Land kommen, wirst du keinen Grundbesitz unter ihnen erhalten, denn ich bin dein Anteil und dein Besitz unter ihnen." },
      { number: 21, text: "Den Leviten weise ich als Erbgut für ihre Arbeit und ihren Dienst am Zelt der Gottesbegegnung den gesamten Zehnten Israels zu." },
      { number: 22, text: "Die Israeliten aber sollen dem Zelt der Gottesbegegnung nicht mehr nahe kommen, sonst laden sie Schuld auf sich und müssen sterben." },
      { number: 23, text: "Vielmehr sollen die Leviten die Arbeit am Zelt der Gottesbegegnung tun, und sie allein sollen die Verantwortung dafür tragen. Diese Ordnung gilt auch für die nachfolgenden Generationen. Aber einen Grundbesitz unter den Israeliten sollen sie nicht erhalten," },
      { number: 24, text: "denn ich habe ihnen den Zehnten der Israeliten gegeben, den diese als Abgabe für Jahwe entrichten. Deshalb sagte ich, dass sie keinen Erbbesitz unter den Israeliten erhalten.\"" },
      { number: 25, text: "Jahwe befahl Mose," },
      { number: 26, text: "den Leviten zu sagen: \"Wenn ihr den Zehnten von den Israeliten nehmt, den ich euch als euren Erbanteil gegeben habe, dann sollt auch ihr eine Abgabe davon für Jahwe entrichten, den Zehnten vom Zehnten." },
      { number: 27, text: "Das wird euch als eure Abgabe angerechnet werden, so wie das Getreide vom Dreschplatz und der Ertrag von der Kelter." },
      { number: 28, text: "Auf diese Weise sollt auch ihr eine Abgabe für Jahwe von dem Zehnten entrichten, den ihr von den Israeliten nehmt, und sie als Abgabe für Jahwe dem Priester Aaron geben." },
      { number: 29, text: "Von allen Gaben, die euch zufallen, sollt ihr die ganze Abgabe Jahwe entrichten, vom Besten den heiligen Teil." },
      { number: 30, text: "Wenn ihr das Beste davon entrichtet, wird es den Leviten angerechnet werden wie der Ertrag vom Dreschplatz und der Ertrag von der Kelter." },
      { number: 31, text: "Ihr dürft es mit euren Familien essen, wo ihr wollt. Das ist der Lohn für eure Arbeit am Zelt der Gottesbegegnung." },
      { number: 32, text: "Wenn ihr das Beste davon entrichtet, werdet ihr keine Sünde auf euch laden und die heiligen Gaben der Israeliten nicht entweihen und nicht sterben müssen, wenn ihr davon esst.\"" },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Jahwe sagte zu Mose und Aaron:", heading: "Das Reinigungswasser" },
      { number: 2, text: "\"Das ist die gesetzliche Anordnung*, die Jahwe erlassen hat: Sag den Israeliten, dass sie dir eine rote junge Kuh bringen, die ohne Fehler ist, an der sich kein Makel findet und die noch kein Joch getragen hat.", footnotes: ["gesetzliche Anordnung. Hebräisch: Tora, was auf die Wurzel jarah = lehren/leiten zurückgeht und Belehrung, Unterweisung, Gesetz bedeutet."] },
      { number: 3, text: "Übergebt sie dem Priester Eleasar. Der soll sie vor das Lager führen, und man soll sie dort in seiner Gegenwart schlachten." },
      { number: 4, text: "Dann soll der Priester Eleasar mit dem Finger von ihrem Blut siebenmal etwas in Richtung auf die Vorderseite des Zeltes der Gottesbegegnung hin sprengen." },
      { number: 5, text: "Anschließend soll man die junge Kuh vor seinen Augen verbrennen: Ihr Fell, ihr Fleisch, ihr Blut und den Inhalt ihres Magens soll man verbrennen." },
      { number: 6, text: "In dieses Feuer hinein soll der Priester Zedernholz, Ysop* und Karmesin* werfen.", footnotes: ["Ysop, ein Busch mit stark riechenden Blättern, der bei Reinigungsopfern zum Besprengen verwendet wurde. Seine Stängel werden bis zu 80 Zentimeter lang.", "Karmesin, (scharlach)roter Farbstoff, der aus getrockneten weiblichen Koschenilleläusen gewonnen wird."] },
      { number: 7, text: "Dann soll der Priester seine Kleidung waschen und sich mit Wasser übergießen. Danach darf er ins Lager zurückgehen. Er wird aber bis zum Abend unrein bleiben." },
      { number: 8, text: "Auch derjenige, der die Kuh verbrannt hat, soll seine Kleidung waschen und sich mit Wasser übergießen. Auch er wird bis zum Abend unrein sein." },
      { number: 9, text: "Jemand, der rein ist, soll dann die Asche der jungen Kuh einsammeln und an einen reinen Platz außerhalb vom Lager bringen. Dort soll die Asche für die Gemeinschaft der Israeliten aufbewahrt werden. Sie ist für das Reinigungswasser bestimmt. Es ist ein Sündopfer." },
      { number: 10, text: "Derjenige, der die Asche der jungen Kuh eingesammelt hat, soll seine Kleidung waschen. Er wird bis zum Abend unrein sein.Und das soll eine immerwährende Ordnung sein für die Israeliten und die Fremden bei ihnen:" },
      { number: 11, text: "Wer einen Toten berührt, den Leichnam eines Menschen, wird für sieben Tage unrein sein." },
      { number: 12, text: "Am dritten Tag soll er sich mit diesem Wasser entsündigen und wird dann am siebten Tag rein sein. Wenn er das nicht tut, wird er auch am siebten Tag nicht rein werden." },
      { number: 13, text: "Jeder, der einen Toten berührt, die Leiche eines Menschen, der gestorben ist, und sich nicht entsündigt, hat die Wohnung Jahwes unrein gemacht. Er soll aus Israel beseitigt werden. Weil das Reinigungswasser nicht auf ihn gesprengt wurde, ist und bleibt er unrein." },
      { number: 14, text: "Folgendes Gesetz gilt, wenn ein Mensch in einem Zelt stirbt: Jeder, der dieses Zelt betritt, und jeder, der sich darin befindet, wird für sieben Tage unrein sein." },
      { number: 15, text: "Jedes offene Gefäß, auf dem kein Deckel festgebunden ist, wird unrein sein." },
      { number: 16, text: "Und jeder, der auf dem freien Feld einen berührt, der mit dem Schwert erschlagen wurde, oder einen Verstorbenen oder die Knochen eines Menschen oder ein Grab, wird für sieben Tage unrein sein." },
      { number: 17, text: "Um die Unreinheit zu beseitigen, nehmt ihr etwas Asche des verbrannten Sündopfers in ein Gefäß und gießt frisches Wasser darüber." },
      { number: 18, text: "Dann soll ein reiner Mann ein Ysopbüschel in die Hand nehmen, ihn in das Wasser eintauchen und damit das Zelt, die Gefäße und die Menschen, die dort gewesen sind, besprengen, auch die Person, die die Knochen oder den Erschlagenen, den Verstorbenen oder das Grab berührt hat." },
      { number: 19, text: "Ein Reiner soll den Unreinen am dritten und am siebten Tag besprengen und ihn so entsündigen. Dieser soll seine Kleidung waschen und sich mit Wasser übergießen. Am Abend wird er dann rein sein." },
      { number: 20, text: "Wenn aber jemand unrein wird und sich nicht entsündigt, ein solcher Mensch muss von der Gemeinschaft beseitigt werden, denn er hat das Heiligtum Jahwes unrein gemacht. Es ist kein Reinigungswasser auf ihn gesprengt worden. Er ist unrein." },
      { number: 21, text: "Das soll eine immerwährende Ordnung für sie sein. Auch der, der das Reinigungswasser versprengt hat, soll seine Kleidung waschen. Und wer mit dem Reinigungswasser in Berührung kommt, ist bis zum Abend unrein." },
      { number: 22, text: "Alles, was ein Unreiner berührt, wird unrein sein, und wer einen Unreinen berührt, wird bis zum Abend unrein sein.\"" },
    ] },
    { number: 20, verses: [
      { number: 1, text: "Die ganze Menge der Israeliten kam nun in die Wüste Zin. Das war im April*. Sie blieben in Kadesch. Dort starb Mirjam und wurde auch dort begraben.", heading: "Nach 40 Jahren an der Grenze des Landes: Das Wasser von Meriba", footnotes: ["April. Wörtlich: im 1. Monat. Ein Vergleich von V. 22-29 mit Kapitel 33,38 zeigt, dass es sich um das 40. Jahr nach dem Auszug aus Ägypten handelte, April 1406 v.Chr."] },
      { number: 2, text: "Als das Volk kein Wasser mehr hatte, rotteten sich die Leute gegen Mose und Aaron zusammen." },
      { number: 3, text: "Sie waren wütend auf Mose und sagten: \"Wären wir doch umgekommen wie die anderen, die Jahwe sterben ließ!" },
      { number: 4, text: "Warum habt ihr die Gemeinde Jahwes in diese Wüste gebracht? Damit wir hier sterben, samt unserem Vieh?" },
      { number: 5, text: "Warum habt ihr uns überhaupt aus Ägypten herausgeführt? Um uns an diesen bösen Ort hier zu bringen? Hier kann man nicht säen, es gibt keine Feigenbäume, keine Weinstöcke, keine Granatapfelbäume, nicht einmal Wasser zum Trinken!\"" },
      { number: 6, text: "Mose und Aaron gingen aus der Versammlung weg zum Eingang vom Zelt der Gottesbegegnung und warfen sich dort nieder, mit dem Gesicht zum Boden. Da erschien ihnen die Herrlichkeit Jahwes." },
      { number: 7, text: "Jahwe sagte zu Mose:" },
      { number: 8, text: "\"Nimm den Stab und versammle die Gemeinde, du und dein Bruder Aaron. Sprecht dann vor ihren Augen zu dem Felsen, dass er sein Wasser hergebe. So wirst du ihnen aus dem Felsen Wasser hervorbringen und Menschen und Vieh zu trinken geben.\"" },
      { number: 9, text: "Mose nahm den Stab, der im Heiligtum vor Jahwe lag, und tat, wie ihm befohlen war." },
      { number: 10, text: "Zusammen mit Aaron brachte er die Menge vor dem Felsen zusammen und rief: \"Hört her, ihr Widerspenstigen! Können wir denn aus diesem Felsen Wasser für euch hervorkommen lassen?\"" },
      { number: 11, text: "Mose hob den Stab und schlug damit zweimal gegen den Felsen. Da kam viel Wasser heraus, sodass Menschen und Vieh genug zu trinken hatten." },
      { number: 12, text: "Da sagte Jahwe zu Mose und Aaron: \"Weil ihr mir nicht vertraut und mich den Israeliten nicht als heilig vor Augen gestellt habt, dürft ihr diese Gemeinschaft nicht in das Land bringen, das ich ihnen gegeben habe.\"" },
      { number: 13, text: "Das ist die Quelle von Meriba, Vorwurf, weil die Israeliten hier Jahwe Vorwürfe machten, und er sich ihnen als der Heilige erwies." },
      { number: 14, text: "Von Kadesch aus schickte Mose Boten an den König von Edom. Sie sollten ihm Folgendes ausrichten: \"So spricht dein Bruder Israel: Du weißt, was wir alles durchgemacht haben.", heading: "Die Edomiter verweigern den Durchzug" },
      { number: 15, text: "Unsere Vorfahren zogen nach Ägypten und haben lange dort gewohnt. Aber die Ägypter behandelten uns und unsere Väter schlecht." },
      { number: 16, text: "Da schrien wir zu Jahwe, und er hat uns gehört. Er schickte einen Engel, der uns aus Ägypten herausführte. Und nun sind wir in Kadesch, einer Stadt am Rand deines Gebiets." },
      { number: 17, text: "Lass uns doch durch dein Land ziehen! Wir werden eure Felder und Weinberge nicht betreten und auch kein Wasser aus den Brunnen trinken. Wir werden auf der Königsstraße bleiben und keinen Schritt von ihr abweichen, solange wir durch dein Gebiet ziehen.\"" },
      { number: 18, text: "Doch Edom ließ Mose sagen: \"Du wirst nicht bei mir durchziehen, sonst werde ich gegen dich kämpfen.\"" },
      { number: 19, text: "Die Israeliten versicherten noch einmal: \"Wir wollen auf der festen Straße bleiben. Und wenn wir oder unser Vieh Wasser brauchen, werden wir es euch bezahlen. Wir kommen zu Fuß und wollen nur durch euer Land hindurch, weiter nichts.\"" },
      { number: 20, text: "Doch Edom sagte: \"Du wirst nicht durchziehen!\" und rückte mit starker Heeresmacht gegen sie aus." },
      { number: 21, text: "So weigerte sich Edom, Israel durch sein Gebiet ziehen zu lassen. Deshalb wählten die Israeliten einen anderen Weg." },
      { number: 22, text: "Sie brachen von Kadesch auf, und die ganze Gemeinschaft der Israeliten kam zum Berg Hor*,", heading: "Aarons Tod", footnotes: ["Berg Hor. Vielleicht ist der Hor Hahar im Massiv des Dschebel Madeira südlich vom Toten Meer gemeint."] },
      { number: 23, text: "der an der Grenze des Landes Edom liegt. Dort sagte Jahwe zu Mose und Aaron:" },
      { number: 24, text: "\"Aaron wird nun mit seinen Vorfahren vereint werden, denn er soll nicht in das Land kommen, das ich den Israeliten gegeben habe, weil ihr euch am Wasser von Meriba gegen meinen Befehl aufgelehnt habt." },
      { number: 25, text: "Steig mit Aaron und seinem Sohn Eleasar auf den Berg Hor!" },
      { number: 26, text: "Dort ziehst du Aaron die Amtsgewänder aus und legst sie seinem Sohn Eleasar an. Aaron wird dort sterben und mit seinen Vorfahren vereint werden.\"" },
      { number: 27, text: "Mose machte es so, wie Jahwe ihm befohlen hatte. Vor den Augen der ganzen Gemeinschaft stiegen sie auf den Berg Hor." },
      { number: 28, text: "Mose streifte Aaron die Amtsgewänder ab und legte sie dessen Sohn Eleasar an. Aaron starb dort auf dem Gipfel des Berges. Und Mose stieg mit Eleasar wieder den Berg hinab." },
      { number: 29, text: "Die ganze Versammlung sah nun, dass Aaron gestorben war. Dreißig Tage lang trauerte das ganze Haus Israel um Aaron." },
    ] },
    { number: 21, verses: [
      { number: 1, text: "Als der Kanaaniterkönig von Arad* im Negev erfuhr, dass Israel auf dem Weg der Kundschafter heranzog, griff er die Israeliten an und nahm einige von ihnen gefangen.", heading: "21-36: An der Grenze des Landes\nDer Marsch nach Moab (21)\nDie Zerstörung von Arad", footnotes: ["Arad. Stadt an der Südgrenze Kanaans. Heute Tell Arad, 27 km südlich von Hebron."] },
      { number: 2, text: "Da legte Israel Jahwe ein Gelübde ab und sagte: \"Wenn du dieses Volk wirklich in meine Hand gibst, werde ich seine Städte mit dem Bann belegen.*\"", footnotes: ["mit dem Bann belegen. Das bedeutete die vollständige Vernichtung von Menschen, Tieren und Gütern."] },
      { number: 3, text: "Jahwe hörte auf Israel und gab die Kanaaniter preis. Israel vernichtete sie und ihre Städte und nannte den Ort Horma, Bann." },
      { number: 4, text: "Als die Israeliten vom Berg Hor weiterzogen, wandten sie sich zunächst in Richtung Schilfmeer, um das Land Edom zu umgehen. Doch auf dem Weg wurde das Volk ungeduldig.", heading: "Die Bronzeschlange" },
      { number: 5, text: "Es lehnte sich gegen Gott und Mose auf und sagte: \"Wozu habt ihr uns aus Ägypten heraufgeführt? Damit wir in der Wüste sterben? Hier gibt es weder Brot noch Wasser, und es ekelt uns vor diesem elenden Fraß.\"" },
      { number: 6, text: "Da schickte Jahwe Brandnattern unter das Volk, sodass viele der Israeliten gebissen wurden und starben." },
      { number: 7, text: "Da lief das Volk zu Mose und sagte: \"Wir haben gesündigt, dass wir uns gegen Jahwe und gegen dich aufgelehnt haben. Bete doch zu Jahwe, dass er uns von den Schlangen befreit!\" Mose betete für das Volk." },
      { number: 8, text: "Und Jahwe sagte zu ihm: \"Mach dir eine Brandnatter und befestige sie an einer Stange. Dann wird jeder, der gebissen wurde und sie ansieht, am Leben bleiben.\"" },
      { number: 9, text: "So fertigte Mose eine Bronzeschlange und machte sie am Ende einer Stange fest. Wer nun von einer Schlange gebissen wurde und zur Bronzeschlange aufblickte, blieb am Leben." },
      { number: 10, text: "Die Israeliten zogen weiter und schlugen ihr Lager in Obot* auf.", heading: "Die Siege über die Könige Sihon und Og", footnotes: ["Obot. Vermutlich ist die heutige Oase Ain el-Weibe (neuhebräisch: Ein Yahav) gemeint."] },
      { number: 11, text: "Ihr nächstes Lager schlugen sie in Ije-Abarim* auf, in der Wüste, die östlich von Moab* liegt.", footnotes: ["Ije-Abarim, die Hügel von Abarim. Vielleicht das heutige Mahai, südöstlich vom Toten Meer.", "Die Moabiter lebten östlich des Toten Meeres zwischen den Flüssen Arnon und Zered."] },
      { number: 12, text: "Von dort aus zogen sie ins Tal des Sered-Bachs*", footnotes: ["Sered-Bach. Wadi el-Hesa, das ins südöstliche Ende des Toten Meeres mündet."] },
      { number: 13, text: "und von da aus weiter bis an den Arnon, der durch die Wüste fließt und im Gebiet der Amoriter entspringt. Denn der Arnon bildet die Grenze zwischen Moab und den Amoritern." },
      { number: 14, text: "Darum heißt es im Buch der Kriege Jahwes*:Waheb in Sufa* und die Bäche des Arnon", footnotes: ["Buch der Kriege Jahwes. Dieses Buch wird nur hier erwähnt. Es enthielt wahrscheinlich Loblieder auf Gott.", "Waheb in Sufa. Vielleicht Orte in der Arnon-Schlucht."] },
      { number: 15, text: "und den Hang der Täler, / der sich neigt zur Wohnstatt von Ar* / und sich lehnt an die Grenze von Moab.", footnotes: ["Ar. Stadt oder Region in Moab in der Nähe des Arnon."] },
      { number: 16, text: "Von dort aus ging es weiter nach Beër. Das ist der Brunnen, von dem Jahwe zu Mose gesagt hatte: \"Versammle das Volk, ich will ihnen Wasser geben.\"" },
      { number: 17, text: "Damals sang Israel dieses Lied:Brunnen, steige auf, / singt von ihm," },
      { number: 18, text: "dem Brunnen, den Fürsten gegraben, / den die Edlen des Volkes gebohrt / mit dem Führerstab und mit ihren Stäben.Aus der Wüste zogen sie weiter nach Mattana," },
      { number: 19, text: "von dort nach Nahaliël und dann weiter nach Bamot*.", footnotes: ["Mattana ... Bamot. Die erwähnten Orte müssen östlich des Toten Meeres und nördlich des Arnon gelegen haben."] },
      { number: 20, text: "Von Bamot zogen sie in das Tal, das im Gebiet von Moab liegt beim Gipfel des Pisga*, der auf das Ödland schaut.", footnotes: ["Pisga. Berg oder Bergkette, wahrscheinlich in der Nähe des Nebo, 14 km östlich vom Nordende des Toten Meeres."] },
      { number: 21, text: "Israel schickte Boten zu Sihon, dem König der Amoriter, und ließ ihm sagen:" },
      { number: 22, text: "\"Lass uns durch dein Land ziehen! Wir werden eure Felder und Weinberge nicht betreten und auch kein Wasser aus den Brunnen trinken. Wir werden auf der Königsstraße bleiben, solange wir durch dein Gebiet ziehen.\"" },
      { number: 23, text: "Aber Sihon gab Israel den Durchzug nicht frei, sondern rief sein Heer zusammen und zog Israel in die Wüste entgegen. Bei Jahaz kam es zur Schlacht." },
      { number: 24, text: "Aber Israel brachte ihm eine schwere Niederlage bei und nahm sein Land in Besitz vom Arnon bis an den Jabbok. Dort begann das Gebiet der Ammoniter, deren Grenze gut gesichert war." },
      { number: 25, text: "Israel besetzte die Städte der Amoriter, besonders Heschbon* und seine Tochterstädte und ließ sich darin nieder.", footnotes: ["Heschbon. Hauptstadt der Amoriter, später der Moabiter, 25 km östlich der Jordanmündung."] },
      { number: 26, text: "Heschbon war die Stadt des Amoriterkönigs Sihon gewesen. Dieser hatte gegen den früheren König der Moabiter gekämpft und ihm das ganze Gebiet bis zum Arnon weggenommen." },
      { number: 27, text: "Darum sagen die Spruchdichter:Kommt nach Heschbon! / Baut Sihons Stadt und macht sie stark!" },
      { number: 28, text: "Feuer ging von Heschbon aus, / eine Flamme von der Stadt Sihons. / Sie fraß Ar-Moab, / die Herren der Höhen am Arnon." },
      { number: 29, text: "Weh dir Moab! / Volk des Kemosch*, du bist verloren! / Seine Söhne gab er als Flüchtlinge hin, / seine Töchter als Gefangene / von Sihon, dem König der Amoriter.", footnotes: ["Kemosch. Gott der Moabiter und zeitweise auch der Amoriter."] },
      { number: 30, text: "Aber wir haben sie beschossen. / Bis nach Dibon* ist Heschbon verloren, / wir haben es bis Nofach verwüstet, / das bei Medeba* liegt.", footnotes: ["Dibon. Eine der bedeutendsten Städte Moabs. Heute: Dhiban, 21 km östlich vom Toten Meer und 5 km nördlich der Arnon-Schlucht.", "Medeba. Moabitische Stadt. Heute: Madeba in Jordanien, 32 km südlich von Amman, 20 km östlich vom Toten Meer."] },
      { number: 31, text: "So ließ Israel sich im Land der Amoriter nieder." },
      { number: 32, text: "Mose ließ die Stadt Jaser* erkunden. Die Israeliten eroberten ihre Tochterstädte und vertrieben die Amoriter, die dort wohnten.", footnotes: ["Jaser. Vielleicht Khirbet es Sar, 10 km westlich von Amman."] },
      { number: 33, text: "Dann zogen sie nordwärts zum Baschan*. Og, der König von Baschan, trat ihnen mit seinem Heer bei Edreï* entgegen.", footnotes: ["Baschan. Fruchtbare Bergregion östlich vom See Gennesaret.", "Edreï. Heute: Dera, 96 km südlich von Damaskus."] },
      { number: 34, text: "Jahwe sagte zu Mose: \"Hab keine Angst vor ihm. Denn in deine Hand habe ich ihn, sein Volk und sein Land gegeben. Mach mit ihm, was du mit dem Amoriterkönig Sihon gemacht hast, der in Heschbon thronte.\"" },
      { number: 35, text: "Da schlugen sie ihn, seine Söhne und sein ganzes Volk. Nicht ein Einziger entkam. Und sie nahmen sein Land in Besitz." },
    ] },
    { number: 22, verses: [
      { number: 1, text: "Die Israeliten brachen wieder auf und schlugen ihr Lager in den Steppen Moabs auf, gegenüber von Jericho, auf der Ostseite des Jordan.", heading: "Erfahrungen mit Bileam (22-25)\nBalaks Auftrag an den Seher Bileam" },
      { number: 2, text: "Als Balak Ben-Zippor sah, was Israel den Amoritern angetan hatte" },
      { number: 3, text: "und wie groß das Volk war, bekam ganz Moab Angst vor den Israeliten, das Grauen packte sie." },
      { number: 4, text: "Die Moabiter ließen den Ältesten von Midian sagen: \"Nun wird dieser Haufen alles um uns herum abfressen, wie das Rind das letzte Grün auf dem Feld abfrisst.\" Balak Ben-Zippor war damals König von Moab." },
      { number: 5, text: "Da schickte er Boten zu Bileam Ben-Beor nach Petor* am Euphrat, wo Leute aus seinem Volk lebten, um ihn zu rufen. Er ließ ihm sagen: \"Da ist ein Volk aus Ägypten herangezogen, das das ganze Land bedeckt. Es hat sich direkt neben mir niedergelassen.", footnotes: ["Petor. Vielleicht Tell el-Abmar, 19 km südlich von Karkemisch am Westufer des oberen Euphrat."] },
      { number: 6, text: "Komm doch und verfluche dieses Volk, denn es ist mir zu stark! Vielleicht kann ich es dann schlagen und aus dem Land vertreiben. Ich weiß ja: Wen du segnest, der ist gesegnet, und wen du verfluchst, der ist verflucht.\"" },
      { number: 7, text: "Da gingen die Ältesten von Moab und Midian los. Den Wahrsagerlohn nahmen sie mit. Als sie zu Bileam kamen, richteten sie ihm die Botschaft Balaks aus." },
      { number: 8, text: "Der sagte zu ihnen: \"Bleibt heute Nacht hier, dann will ich euch Bescheid geben, wie Jahwe zu mir gesprochen hat.\" Da blieben die Abgesandten von Moab bei Bileam." },
      { number: 9, text: "Gott kam zu Bileam und fragte: \"Wer sind diese Männer bei dir?\"" },
      { number: 10, text: "Bileam erwiderte: \"König Balak Ben-Zippor von Moab hat sie zu mir geschickt:" },
      { number: 11, text: "Da ist ein Volk aus Ägypten herangezogen, das das ganze Land bedeckt. Komm doch und verfluche es mir! Vielleicht kann ich es dann bekämpfen und aus dem Land vertreiben.\"" },
      { number: 12, text: "Doch Gott sagte zu Bileam: \"Du sollst nicht mitgehen! Du sollst das Volk nicht verfluchen, denn es ist gesegnet.\"" },
      { number: 13, text: "Am Morgen stand Bileam auf und sagte zu den Fürsten Balaks: \"Ihr müsst allein in euer Land zurück. Jahwe hat sich geweigert, mir zu gestatten, mit euch zu gehen.\"" },
      { number: 14, text: "Da machten sich die Abgesandten Moabs wieder auf den Weg. Als sie zu Balak kamen, sagten sie: \"Bileam hat sich geweigert, mit uns zu gehen.\"" },
      { number: 15, text: "Da schickte Balak eine noch größere Gesandtschaft von Männern, die noch angesehener waren." },
      { number: 16, text: "Als sie zu Bileam kamen, sagten sie zu ihm: \"So spricht Balak Ben-Zippor: Lass dich doch nicht abhalten, zu mir zu kommen!" },
      { number: 17, text: "Ich werde dich reich belohnen und alles tun, was du von mir verlangst. Komm doch und verfluche dieses Volk für mich!\"" },
      { number: 18, text: "Doch Bileam erwiderte den Gesandten Balaks: \"Selbst wenn Balak mir sein Haus voll Silber und Gold geben würde, könnte ich den Befehl meines Gottes Jahwe nicht übertreten, weder im Kleinen noch im Großen." },
      { number: 19, text: "Aber bleibt auch ihr die Nacht über bei mir. Dann werde ich erfahren, was Jahwe mir noch sagt.\"" },
      { number: 20, text: "In der Nacht kam Gott zu Bileam und sagte: \"Wenn die Männer gekommen sind, um dich zu holen, dann mach dich auf den Weg! Aber du darfst nur das tun, was ich dir sage!\"" },
      { number: 21, text: "Am Morgen brach Bileam auf, sattelte seine Eselin und machte sich mit der Gesandtschaft Moabs auf den Weg.", heading: "Bileams Eselin" },
      { number: 22, text: "Da flammte Gottes Zorn auf, weil er mitging, und der Engel Jahwes stellte sich ihm als Gegner in den Weg. Bileam ritt gerade auf seiner Eselin und wurde von zwei Dienern begleitet." },
      { number: 23, text: "Die Eselin sah den Engel Jahwes mit dem gezückten Schwert auf dem Weg stehen. Sie wich vom Weg ab und ging auf dem Feld weiter. Bileam schlug sie und trieb sie auf den Weg zurück." },
      { number: 24, text: "Da stellte sich der Engel Jahwes in einen Hohlweg zwischen den Weinbergen. Links und rechts waren Mauern." },
      { number: 25, text: "Die Eselin sah den Engel Jahwes und drückte sich an die Mauer. Dabei drückte sie den Fuß Bileams an die Wand. Da schlug er sie wieder." },
      { number: 26, text: "Der Engel Jahwes ging nochmals ein Stück weiter und trat an eine so enge Stelle, dass es keine Möglichkeit zum Ausweichen gab, weder rechts noch links." },
      { number: 27, text: "Als die Eselin ihn sah, legte sie sich unter Bileam hin. Bileam schlug wütend mit dem Stock auf sie ein." },
      { number: 28, text: "Da ließ Jahwe die Eselin sprechen. Sie sagte zu Bileam: \"Was habe ich dir denn getan, dass du mich nun schon dreimal geschlagen hast?\"" },
      { number: 29, text: "\"Weil du mich zum Narren hältst\", schrie Bileam. \"Hätte ich nur ein Schwert in der Hand, wärst du jetzt schon tot.\"" },
      { number: 30, text: "Das Tier erwiderte: \"Bin ich nicht deine Eselin, auf der du zeitlebens geritten bist? Habe ich jemals so reagiert wie heute?\" – \"Nein\", sagte er." },
      { number: 31, text: "Da öffnete Jahwe ihm die Augen, und er sah den Engel Jahwes mit dem gezückten Schwert auf dem Weg. Bileam verneigte sich und kniete sich hin mit dem Gesicht zum Boden." },
      { number: 32, text: "Der Engel Jahwes sagte zu ihm: \"Warum hast du deine Eselin nun schon dreimal geschlagen? Ich selbst habe mich gegen dich gestellt. Denn dein Weg ist ganz gegen mich." },
      { number: 33, text: "Die Eselin sah mich und wich vor mir aus, nun schon dreimal! Hätte sie das nicht getan, dann hätte ich dich erschlagen und sie am Leben gelassen.\"" },
      { number: 34, text: "Da sagte Bileam zu dem Engel Jahwes: \"Ich habe Unrecht getan. Ich habe nicht gemerkt, dass du dich mir entgegengestellt hast. Wenn dir nun die Sache missfällt, will ich umkehren.\"" },
      { number: 35, text: "\"Geh mit den Männern!\", sagte der Engel Jahwes. \"Aber du darfst nur das aussprechen, was ich dir sage!\" So zog Bileam mit der Gesandtschaft Balaks weiter." },
      { number: 36, text: "Als Balak hörte, dass Bileam zu ihm unterwegs war, zog er ihm bis zur Grenzstadt Moabs am Arnonfluss entgegen.", heading: "Bileam trifft Balak" },
      { number: 37, text: "\"Warum bist du nicht gleich gekommen?\", sagte er zu Bileam. \"Ich habe doch dringend nach dir geschickt! Kann ich dich vielleicht nicht angemessen belohnen?\"" },
      { number: 38, text: "\"Nun bin ich ja hier\", erwiderte Bileam. \"Ob ich aber wirklich etwas sagen kann, weiß ich nicht. Ich werde nur das sagen, was Gott mir befiehlt.\"" },
      { number: 39, text: "Bileam ging mit Balak bis nach Kirjat-Huzot*.", footnotes: ["Kirjat-Huzot. Die genaue Ortslage ist unbekannt."] },
      { number: 40, text: "Dort ließ der König Rinder, Schafe und Ziegen für ein Opfermahl schlachten und bewirtete Bileam und die Fürsten, die bei ihm waren." },
      { number: 41, text: "Am nächsten Morgen ging Balak mit Bileam auf die Baalshöhen. Von dort aus konnte er ein kleines Stück von Israel sehen." },
    ] },
    { number: 23, verses: [
      { number: 1, text: "Bileam sagte zu Balak: \"Errichte mir hier sieben Altäre und halte mir sieben Stiere und sieben Schafböcke bereit.\"", heading: "Bileams erster Spruch" },
      { number: 2, text: "Balak tat, was Bileam gesagt hatte, und beide opferten auf jedem Altar einen Stier und einen Schafbock." },
      { number: 3, text: "Dann sagte Bileam zu Balak: \"Bleib hier neben deinem Brandopfer stehen! Ich aber will ein Stück weggehen. Vielleicht wird Jahwe mir begegnen. Und was er mich sehen lassen wird, werde ich dir berichten.\" Bileam stieg auf eine kahle Anhöhe." },
      { number: 4, text: "Gott kam Bileam entgegen. Dieser sagte zu ihm: \"Die sieben Altäre habe ich errichtet und auf jedem Altar einen Stier und einen Schafbock geopfert.\"" },
      { number: 5, text: "Jahwe wies Bileam an, was er sagen sollte, und schickte ihn zu Balak zurück." },
      { number: 6, text: "Balak stand noch bei seinem Brandopfer. Und alle Fürsten Moabs waren bei ihm." },
      { number: 7, text: "Bileam begann seinen Spruch:\"Aus Syrien führte Balak mich her, / Moabs König von den Bergen des Ostens: / Komm, verfluche Jakob für mich, / ja, komm, verfluche Israel." },
      { number: 8, text: "Wie kann ich fluchen, wem Gott nicht flucht, / wie soll ich drohen, wem Jahwe nicht droht?" },
      { number: 9, text: "Vom Gipfel der Felsen sehe ich es, / ich erblicke es vom Hügel aus. / Seht, ein Volk, das abgesondert wohnt / und sich nicht zu den anderen Völkern zählt." },
      { number: 10, text: "Wer weiß die Zahl von Jakobs Staub / und wer kann Israels Gewimmel ermessen? / Den Tod der Aufrechten möchte ich sterben, / mein Ende sei dem ihren gleich.\"" },
      { number: 11, text: "Da sagte Balak zu Bileam: \"Was hast du mir da angetan? Ich habe dich holen lassen, um meine Feinde zu verfluchen, und nun segnest du sie!\"" },
      { number: 12, text: "Bileam antwortete: \"Ich darf doch nur das aussprechen, was Jahwe mir zu sagen befiehlt!\"" },
      { number: 13, text: "Da sagte Balak zu ihm: \"Komm mit an eine andere Stelle, von wo aus du das Volk sehen kannst. Du wirst freilich nur einen Bruchteil von ihm sehen, ganz überblicken kannst du es nicht. Und dort verfluche es für mich.\"", heading: "Bileams zweiter Spruch" },
      { number: 14, text: "Er nahm ihn mit zum Beobachtungsplatz auf den Gipfel des Pisga. Auch dort ließ er sieben Altäre bauen und opferte einen Stier und einen Schafbock auf jedem." },
      { number: 15, text: "Bileam sagte zu Balak: \"Stell dich hier neben dein Brandopfer, ich aber will dort auf eine Begegnung warten.\"" },
      { number: 16, text: "Jahwe kam zu Bileam, wies ihn an, was er sagen sollte, und schickte ihn zu Balak zurück." },
      { number: 17, text: "Balak stand noch bei seinem Brandopfer und fragte: \"Was hat Jahwe gesagt?\" Die Fürsten Moabs waren bei ihm." },
      { number: 18, text: "Bileam begann seinen Spruch:\"Steh auf, Balak, und höre, / Ben-Zippor, hör zu!" },
      { number: 19, text: "Gott ist ja kein Mensch, der lügt, / kein Menschensohn, der etwas bereut. / Wenn er etwas sagt, dann tut er es auch, / und was er verspricht, das hält er gewiss." },
      { number: 20, text: "Er wies mich an, das Volk zu segnen. / Er hat gesegnet, ich kann es nicht ändern!" },
      { number: 21, text: "Er sieht nichts Böses in Jakob, / kein Unglück wird Israel treffen. / Denn Jahwe, sein Gott, ist mit ihm, / und diesem König jubeln sie zu." },
      { number: 22, text: "Gott hat sie aus Ägypten geführt, / stark wie die Hörner des Wildstiers sind sie." },
      { number: 23, text: "Gegen Jakob wirkt keine Zauberei, / gegen Israel hilft Wahrsagen nicht. / Jetzt sagt man von ihnen: / Was hat Gott gewirkt!" },
      { number: 24, text: "Ein Volk wie ein Löwe, der aufsteht, / wie eine Löwin, die sich erhebt. / Es legt sich nicht hin, bis es Beute verzehrt / und das Blut der Erschlagenen trinkt.\"" },
      { number: 25, text: "Da sagte Balak zu Bileam: \"Wenn du sie schon nicht verfluchen kannst, dann segne sie nicht auch noch!\"" },
      { number: 26, text: "Aber Bileam erwiderte: \"Ich habe dir doch schon gesagt, dass ich nur das tun kann, was Jahwe mir befiehlt.\"" },
      { number: 27, text: "Da sagte Balak zu Bileam: \"Komm mit an eine andere Stelle. Vielleicht ist es Gott recht, wenn du mir das Volk von dort aus verfluchst.\"", heading: "Bileams dritter Spruch" },
      { number: 28, text: "Balak führte Bileam auf den Gipfel des Peor, von dem aus man das untere Jordantal sieht." },
      { number: 29, text: "Bileam sagte zu Balak: \"Errichte mir hier sieben Altäre und halte mir sieben Stiere und sieben Schafböcke bereit.\"" },
      { number: 30, text: "Balak tat, was Bileam gesagt hatte, und opferte einen Stier und einen Schafbock auf jedem Altar." },
    ] },
    { number: 24, verses: [
      { number: 1, text: "Bileam wusste nun, dass Jahwe Israel segnen wollte. So ging er nicht wie die vorigen Male aus, um Wahrsagezeichen zu finden, sondern wandte sein Gesicht der Wüste zu." },
      { number: 2, text: "Er richtete seinen Blick auf die Israeliten, die dort nach ihren Stämmen geordnet lagerten. Da kam der Geist Gottes über ihn," },
      { number: 3, text: "und er begann seinen Spruch:\"Es spricht Bileam Ben-Beor, / der Mann mit offenen Augen." },
      { number: 4, text: "Es spricht der, der Gottesworte hört, / der eine Schau des Allmächtigen hat, / hingesunken mit entschleiertem Blick." },
      { number: 5, text: "Wie schön sind deine Zelte, Jakob, / und deine Heime, Israel!" },
      { number: 6, text: "Wie Täler ziehen sie sich hin, / wie Gärten am Strom, / wie Aloebäume* von Jahwe gepflanzt, / wie Zedern*, die am Wasser stehn.", footnotes: ["Aloebäume. Schlanke Bäume, wegen ihres Öls und Dufts sehr gefragt.", "Zeder. Prächtiger Nadelbaum mit ausgebreiteter Krone, kann mehr als 1000 Jahre alt und bis zu 40 m hoch werden."] },
      { number: 7, text: "Wasser strömt aus seinen Schöpfeimern, / und seine Saat steht gut bewässert da. / Sein König wird mächtiger als Agag sein. / Sein Königtum wird sich erheben." },
      { number: 8, text: "Gott hat es aus Ägypten geführt, / stark wie die Hörner des Wildstiers ist es. / Seine Feinde, ganze Völker, wird es fressen / und ihre Gebeine zermalmen. / Seine Pfeile reißen tödliche Wunden." },
      { number: 9, text: "Es kauert, liegt da wie ein Löwe / und wie eine Löwin – wer stört es auf? / Ja, wer dich segnet, ist gesegnet / und wer dir flucht, ist verflucht.\"" },
      { number: 10, text: "Da wurde Balak wütend über Bileam, er schlug seine Hände zusammen und sagte: \"Meine Feinde zu verfluchen habe ich dich gerufen. Und jetzt hast du sie schon dreimal gesegnet!" },
      { number: 11, text: "Mach, dass du fortkommst, wo du hingehörst! Ich hatte dir reiche Belohnung versprochen. Du siehst, Jahwe hat sie dir verwehrt.\"" },
      { number: 12, text: "Bileam erwiderte Balak: \"Schon zu deinen Boten, die du mir geschickt hast, habe ich gesagt:" },
      { number: 13, text: "'Selbst wenn Balak mir sein Haus voll Silber und Gold geben würde, könnte ich den Befehl Jahwes nicht übertreten, um irgendetwas von mir aus zu tun. Ich muss das sagen, was Jahwe mir befiehlt.'" },
      { number: 14, text: "Pass auf, ich gehe jetzt zu meinem Volk. Vorher werde ich dir aber verkünden, was dieses Volk deinem Volk in Zukunft antun wird.\"" },
      { number: 15, text: "Er begann seinen Spruch:\"Es spricht Bileam Ben-Beor, / der Mann mit offenen Augen." },
      { number: 16, text: "Es spricht der, der Gottesworte hört, / der Erkenntnisse vom Höchsten hat, / eine Schau des Allmächtigen, / hingesunken mit entschleiertem Blick." },
      { number: 17, text: "Ich sehe ihn, aber nicht jetzt, / ich schaue ihn, aber nicht nah. / Ein Stern tritt aus Jakob hervor, / ein Zepter erhebt sich aus Israel, / das die Fronten Moabs zerschmettert / das Schlachtgetümmel zerschlägt." },
      { number: 18, text: "Das ganze Seïr nimmt er in Besitz, / das Land seiner edomitischen Feinde. / Israel wird mächtig sein." },
      { number: 19, text: "Und einer aus Jakob wird herrschen / und vernichten, die aus der Stadt fliehen.\"" },
      { number: 20, text: "Dann sah er Amalek vor sich und begann seinen Spruch:\"Amalek ist der Erstling der Völker, / doch zuletzt geht es unter.\"" },
      { number: 21, text: "Er sah die Keniter vor sich und begann seinen Spruch:\"Dein Wohnsitz, Kain*, ist sicher und fest, / dein Nest ist auf Felsen gebaut.", footnotes: ["Kain. Hier eine andere Bezeichnung für die Keniter."] },
      { number: 22, text: "Doch es wird der Verwüstung verfallen, / wenn Assyrien dich in Gefangenschaft führt.\"" },
      { number: 23, text: "Er begann seinen Spruch:\"Weh, wer bleibt am Leben, wenn Gott das tut?" },
      { number: 24, text: "Schiffe von der Küste der Kittäer* / beugen Assyrien nieder und auch Eber*. / Doch auch das führt zum Untergang.\"", footnotes: ["Kittäer. Bewohner der Insel Zypern. Hier sind vielleicht auch alle westlichen Mittelmeermächte gemeint.", "Eber ist hier wohl eine poetische Beschreibung Israels, von Hebräer abgeleitet."] },
      { number: 25, text: "Bileam machte sich auf den Weg und kehrte an seinen Ort zurück. Auch Balak ging seines Wegs." },
    ] },
    { number: 25, verses: [
      { number: 1, text: "Als Israel sich in Schittim aufhielt, begann das Volk, sich sexuell mit moabitischen Frauen einzulassen.", heading: "Verführung zum Götzendienst" },
      { number: 2, text: "Diese luden die Israeliten zu den Opferfesten ihres Gottes ein. Sie kamen und aßen mit ihnen und warfen sich vor ihrem Gott nieder." },
      { number: 3, text: "So ließ sich Israel in das Joch des Baal-Peor einspannen. Da flammte Jahwes Zorn gegen Israel auf." },
      { number: 4, text: "Er sagte zu Mose: \"Nimm alle Anführer des Volkes fest und richte sie im Licht der Sonne vor Jahwe hin, damit Jahwes glühender Zorn sich von Israel abwendet.\"" },
      { number: 5, text: "Mose befahl den Richtern Israels: \"Jeder töte die von seinen Leuten, die sich an den Baal-Peor gehängt haben!\"" },
      { number: 6, text: "Die ganze Gemeinschaft der Israeliten hatte sich inzwischen bei Mose vor dem Zelt der Gottesbegegnung versammelt und weinte. Da kam ein Israelit und brachte vor aller Augen eine Midianiterin ins Lager seiner Sippe." },
      { number: 7, text: "Als der Priester Pinhas Ben-Eleasar, der Enkel Aarons, das sah, stand er auf und verließ die Versammlung. Er nahm einen Speer," },
      { number: 8, text: "ging den beiden nach in den innersten Raum des Zeltes und stieß ihn dem Israeliten und der Frau durch den Bauch. Da hörte die unter den Israeliten wütende Plage auf." },
      { number: 9, text: "An dieser Plage waren bereits 24.000 Menschen gestorben." },
      { number: 10, text: "Jahwe sagte zu Mose:" },
      { number: 11, text: "\"Der Priester Pinhas Ben-Eleasar, der Enkel des Priesters Aaron, hat meinen Grimm von den Israeliten abgewendet, weil er an meiner Statt unter ihnen geeifert hat. So habe ich die Israeliten in meinem Zorneseifer nicht völlig vernichtet." },
      { number: 12, text: "Darum sag ihm, dass ich ihm meinen Friedensbund gewähre." },
      { number: 13, text: "Ihm und seinen Nachkommen soll ein Bund dauerhaften Priestertums zuteil werden, weil er für seinen Gott geeifert und Sühne für die Israeliten erwirkt hat.\"" },
      { number: 14, text: "Der Israelit, der zusammen mit der Midianiterin getötet wurde, war Simri Ben-Salu, das Oberhaupt einer Sippe der Simeoniten." },
      { number: 15, text: "Die Midianiterin war Kosbi, die Tochter Zurs, dem Oberhaupt einer midianitischen Stammesgruppe." },
      { number: 16, text: "Jahwe sagte zu Mose:" },
      { number: 17, text: "\"Greift die Midianiter an und schlagt sie!" },
      { number: 18, text: "Denn sie haben euch durch ihre List in der Sache mit dem Peor heimtückisch angegriffen und auch in der Sache mit Kosbi, der Tochter eines Oberhaupts von Midian, die am Tag der Plage wegen des Peor erschlagen wurde.\"" },
    ] },
    { number: 26, verses: [
      { number: 25, text: "Nach der Plage", heading: "Neuordnung der 2. Generation (26-30)\nDie zweite Volkszählung" },
      { number: 1, text: "sagte Jahwe zu Mose und dem Priester Eleasar Ben-Aaron:" },
      { number: 2, text: "\"Zählt die ganze Gemeinschaft der Israeliten. Erfasst alle wehrfähigen Männer ab 20 Jahren nach ihren Sippen geordnet.\"" },
      { number: 3, text: "Mose und Eleasar sagten das den Israeliten. Das geschah in der Jordanebene bei Jericho, dem moabitischen Steppengebiet." },
      { number: 4, text: "Es ging um die Männer ab 20 Jahren, wie Jahwe es Mose befohlen hatte. Nun folgt die Liste der Männer Israels, die aus Ägypten ausgezogen waren:" },
      { number: 5, text: "Ruben, der Erstgeborene Israels. Von seinen Söhnen Henoch, Pallu, Hezron und Karmi" },
      { number: 6, text: "stammen die Sippen der Henochiten, Palluiten, Hezroniten und Karmiten ab." },
      { number: 7, text: "Insgesamt waren es 43.730 Wehrfähige." },
      { number: 8, text: "Von Pallu stammten Eliab" },
      { number: 9, text: "und dessen Söhne Nemuel, Datan und Abiram ab, die Berufene der Gemeinschaft waren und sich zusammen mit den Anhängern Korachs gegen Mose und Aaron aufgelehnt hatten, als jene Gruppe gegen Jahwe rebellierte." },
      { number: 10, text: "Damals hatte sich die Erde geöffnet und sie und Korach verschlungen, damals, als Korachs Rotte von 250 Männern durch das Feuer starb. Sie wurden zu einem warnenden Beispiel." },
      { number: 11, text: "Aber die Nachkommen Korachs starben nicht." },
      { number: 12, text: "Von Simeons Söhnen Jemuël, Jamin, Jachin, Serach und Schaul" },
      { number: 13, text: "stammen die Sippen der Jemuëliten, Jaminiten, Jachiniten, Serachiten und Schauliten ab." },
      { number: 14, text: "Insgesamt waren es 22.200 Männer." },
      { number: 15, text: "Von Gads Söhnen Zifjon, Haggi, Schuni, Osni, Eri, Arod und Areli" },
      { number: 16, text: "stammen die Sippen der Zifjoniten, Haggiten, Schuniten, Osniten, Eriten," },
      { number: 17, text: "Aroditen und Areliten ab." },
      { number: 18, text: "Insgesamt waren es 40.500 Wehrfähige." },
      { number: 19, text: "Judas Söhne Er und Onan starben schon im Land Kanaan." },
      { number: 20, text: "Von Judas Söhnen Schela, Perez, Serach, Hezron und Hamul" },
      { number: 21, text: "stammen die Sippen der Schelaniten, Pereziten, Serachiten, Hezroniten und Hamuliten ab." },
      { number: 22, text: "Insgesamt waren es 76.500 Wehrfähige." },
      { number: 23, text: "Von den Söhnen Issachars Tola, Puwa, Jaschub und Schimron" },
      { number: 24, text: "stammen die Sippen der Tolaiten, Puwaniten, Jaschubiten und Schimroniten ab." },
      { number: 25, text: "Insgesamt waren es 64.300 Wehrfähige." },
      { number: 26, text: "Von Sebulons Söhnen Sered, Elon und Jachleel stammen die Sippen der Serediten, Eloniten und Jachleeliten ab." },
      { number: 27, text: "Insgesamt waren es 60.500 Wehrfähige." },
      { number: 28, text: "Die Söhne Josefs waren Manasse und Efraïm." },
      { number: 29, text: "Von Manasses Sohn Machir stammt die Sippe der Machiriten ab. Machir wurde der Vater von Gilead, vom dem die Sippe der Gileaditer abstammt." },
      { number: 30, text: "Von Gileads Söhnen Ieser, Helke, Asriël, Sichem, Schemida und Hefer" },
      { number: 31, text: "stammen die Sippen der Iesriten, Helekiten, Asriëliten," },
      { number: 32, text: "der Sichemiten, Schemidaiten und Hefriten ab." },
      { number: 33, text: "Zelofhad, der Sohn Hefers, hatte keine Söhne, sondern Töchter. Es waren Machla, Noa, Hogla, Milka und Tirza." },
      { number: 34, text: "Insgesamt waren es 52.700 Wehrfähige." },
      { number: 35, text: "Von Efraïms Söhnen Schutelach, Becher und Tahan stammen die Sippen der Schutelachiten, Becheriten und Tahaniten ab." },
      { number: 36, text: "Von Schutelachs Sohn Eran stammt die Sippe der Eraniten ab." },
      { number: 37, text: "Insgesamt waren es 32.500 Männer.Das waren die Sippen der Nachkommen Josefs." },
      { number: 38, text: "Von Benjamins Söhnen Bela, Aschbel, Ahiram, Schufam und Hufam" },
      { number: 39, text: "stammen die Sippen der Belaiten, Aschbeliten, Ahiramiten, Schufamiten und Hufamiten ab." },
      { number: 40, text: "Von Belas Söhnen Arad und Naaman stammen die Sippen der Araditen und Naamaniten ab." },
      { number: 41, text: "Insgesamt waren es 45.600 Wehrfähige." },
      { number: 42, text: "Von Dans Sohn Schuham stammen die Sippen der Schuhamiten ab." },
      { number: 43, text: "Insgesamt waren es 64.400 Wehrfähige." },
      { number: 44, text: "Von Aschers Söhnen Jimna, Jischwi und Beria stammen die Sippen der Jimnaiten, Jischwiten und Beriiten ab." },
      { number: 45, text: "Von Berias Söhnen Heber und Malkiël stammen die Sippen der Heberiten und Malkiëliten ab." },
      { number: 46, text: "Aschers Tochter hieß Serach." },
      { number: 47, text: "Insgesamt waren es 53.400 Wehrfähige." },
      { number: 48, text: "Von Naftalis Söhnen Jachzeel, Guni, Jezer und Schillem" },
      { number: 49, text: "stammen die Sippen der Jachzeeliten, Guniten, Jezeriten und Schillemiten ab." },
      { number: 50, text: "Insgesamt waren es 45.400 Wehrfähige." },
      { number: 51, text: "Die Gesamtzahl der wehrfähigen Männer Israels betrug 601 730." },
      { number: 52, text: "Jahwe sagte zu Mose:" },
      { number: 53, text: "\"Diesen soll das Land als Erbbesitz zugeteilt werden, und zwar entsprechend ihrer Anzahl." },
      { number: 54, text: "Einem großen Stamm sollst du einen großen Erbbesitz zuteilen und einem kleinen einen kleinen. Jedem Stamm soll sein Erbbesitz nach der Zahl seiner Gemusterten zugeteilt werden." },
      { number: 55, text: "Die Verteilung selbst soll dann durch das Los geschehen. Nach dem Namen der Stämme ihrer Vorfahren sollen sie Erbbesitz erhalten." },
      { number: 56, text: "Nach dem Losentscheid soll der Erbbesitz zwischen den größeren und kleineren Stämmen verteilt werden.\"" },
      { number: 57, text: "Von Levis Söhnen Gerschon, Kehat und Merari stammen die Sippen der Gerschoniten, Kehatiten und Merariten ab." },
      { number: 58, text: "Zu Levi gehören auch die Sippen der Libniten, Hebroniten, Machliten, Muschiten und Korachiten. Kehat war der Vater von Amram." },
      { number: 59, text: "Dessen Frau hieß Jochebed. Sie war eine Tochter Levis und wurde schon in Ägypten geboren. Mit Amram bekam sie Mose, Aaron und deren Schwester Mirjam." },
      { number: 60, text: "Aaron wurde der Vater von Nadab, Abihu, Eleasar und Itamar." },
      { number: 61, text: "Nadab und Abihu starben, als sie Jahwe ein unerlaubtes Feueropfer brachten." },
      { number: 62, text: "Die Gesamtzahl aller männlichen gemusterten Leviten betrug 23.000. Sie wurden nicht zusammen mit den Israeliten erfasst, weil ihnen kein Erbbesitz zustand." },
      { number: 63, text: "Das waren diejenigen, die durch Mose und Eleasar im moabitischen Steppengebiet der Jordanebene gegenüber von Jericho gemustert wurden." },
      { number: 64, text: "Es war keiner unter ihnen, der schon von Mose und Aaron in der Wüste Sinai erfasst worden war." },
      { number: 65, text: "Denn Jahwe hatte ihnen gesagt, sie müssten alle in der Wüste sterben. Nur Kaleb Ben-Jefunne und Josua Ben-Nun waren von ihnen allen übrig geblieben." },
    ] },
    { number: 27, verses: [
      { number: 1, text: "Da kamen die Töchter von Zelofhad Ben-Hefer, dem Enkel Gileads, der über Machir und Manasse von Josef abstammte. Es waren Machla, Noa, Hogla, Milka und Tirza.", heading: "Das Erbrecht von Töchtern" },
      { number: 2, text: "Sie traten vor den Eingang vom Zelt der Gottesbegegnung und sagten zu Mose und Eleasar, den Oberen und der ganzen Versammlung:" },
      { number: 3, text: "\"Unser Vater ist in der Wüste gestorben. Er gehörte aber nicht zu den Anhängern Korachs, die sich gegen Jahwe auflehnten, sondern ist wie alle anderen seiner Generation an seiner Sünde gestorben. Aber er hatte keine Söhne." },
      { number: 4, text: "Warum soll der Name unseres Vaters aus seiner Sippe verschwinden, nur weil er keinen Sohn hat? Gib uns Grundbesitz bei den Brüdern unseres Vaters!\"" },
      { number: 5, text: "Mose brachte ihre Rechtssache vor Jahwe." },
      { number: 6, text: "Jahwe erwiderte ihm:" },
      { number: 7, text: "\"Die Töchter Zelofhads haben Recht, du sollst ihnen erblichen Grundbesitz bei den Brüdern ihres Vaters geben und seinen Erbbesitz auf seine Töchter übergehen lassen!" },
      { number: 8, text: "Zu den Israeliten sollst du Folgendes sagen: Wenn ein Mann stirbt und keinen Sohn hat, soll sein Erbbesitz auf seine Tochter übergehen." },
      { number: 9, text: "Hat er aber keine Tochter, soll sein Erbbesitz seinen Brüdern zufallen." },
      { number: 10, text: "Hat er keine Brüder, dann fällt der Erbbesitz den Brüdern seines Vaters zu." },
      { number: 11, text: "Hat auch sein Vater keine Brüder, dann fällt der Erbbesitz dem Nächstverwandten aus seiner Sippe zu. Das soll bei den Israeliten gültiges Recht werden, wie Jahwe es Mose befohlen hat.\"" },
      { number: 12, text: "Jahwe sagte zu Mose: \"Steig auf das Abarim-Gebirge* und sieh dir das Land an, das ich den Israeliten gegeben habe!", heading: "Die Einsetzung Josuas", footnotes: ["Abarim-Gebirge. Bergkette in Transjordanien, östlich vom Nordende des Toten Meeres. Der Berg Nebo war Teil dieser Bergkette."] },
      { number: 13, text: "Wenn du es gesehen hast, wirst auch du mit deinen Vorfahren vereint werden wie dein Bruder Aaron," },
      { number: 14, text: "weil ihr euch in der Wüste Zin, als die Menge Israels aufbegehrte, meinem Befehl widersetzt habt. Ihr habt mich ihnen durch das Wasser nicht als heilig vor Augen gestellt. Das ist das Wasser von Meriba bei Kadesch in der Wüste Zin.\"" },
      { number: 15, text: "Mose sagte zu Jahwe:" },
      { number: 16, text: "\"Jahwe, der Gott, von dem alles Leben kommt, setze einen Mann ein, der die Gemeinschaft führt," },
      { number: 17, text: "der vor ihnen her auszieht und vor ihnen her einzieht, der sie hinausführt und sie heimführt, damit die Gemeinde Jahwes nicht wie eine Schafherde ohne Hirten ist.\"" },
      { number: 18, text: "Jahwe sagte zu Mose: \"Nimm Josua Ben-Nun, einen Mann, in dem der Geist ist, und lege deine Hand auf ihn!" },
      { number: 19, text: "Stell ihn vor den Priester Eleasar und die ganze Versammlung und beauftrage ihn vor ihren Augen." },
      { number: 20, text: "Und gib ihm von deiner Autorität ab, damit die ganze Gemeinschaft der Israeliten auf ihn hört." },
      { number: 21, text: "Er soll bei jeder Entscheidung vor den Priester Eleasar treten, und der soll vor Jahwe die Entscheidung der Urim* für ihn einholen. Nach diesem Befehl sollen sie ausziehen und nach diesem Befehl zurückkehren. Das gilt für Josua und alle Israeliten, die ganze Gemeinschaft.\"", footnotes: ["Urim (und Tummim)waren die heiligen Lose, die bei schwierigen Entscheidungen den Schiedsspruch herbeiführten. Die Bedeutung der hebräischen Begriffe ist unsicher. Nach der LXX, der griechischen Übersetzung des Alten Testaments, bedeuteten sie Licht und Recht."] },
      { number: 22, text: "Mose machte es, wie Jahwe ihm befohlen hatte. Er holte Josua, stellte ihn vor den Priester Eleasar und die ganze Versammlung." },
      { number: 23, text: "Er legte ihm die Hände auf und beauftragte ihn, wie Jahwe es ihm gesagt hatte." },
    ] },
    { number: 28, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Die täglichen Opfer" },
      { number: 2, text: "\"Befiehl den Israeliten, darauf zu achten, mir meine Opfergaben zur festgesetzten Zeit zu bringen, meine Speise als Feueropfer zum angenehmen Geruch." },
      { number: 3, text: "Sag zu ihnen: Das Feueropfer, das ihr Jahwe bringen sollt, besteht täglich aus zwei makellosen einjährigen Lämmern als regelmäßiges Brandopfer." },
      { number: 4, text: "Das erste Lamm sollst du am Morgen bringen und das andere am späten Nachmittag." },
      { number: 5, text: "Dazu kommen als Speisopfer jeweils zwei Litergefäße* voll Feinmehl, das mit einem knappen Liter* Öl aus zerstoßenen Oliven vermengt ist.", footnotes: ["zwei Litergefäße. Wörtlich: ein Zehntel (Efa) = 2,2 Liter", "ein knapper Liter. Wörtlich: ein Viertel Hin = 0,9 Liter"] },
      { number: 6, text: "Das ist das ständige Brandopfer, wie es zum ersten Mal am Berg Sinai dargebracht wurde. Es ist ein Feueropfer für Jahwe zum angenehmen Geruch." },
      { number: 7, text: "Das dazugehörige Trankopfer: ein knapper Liter Wein je Lamm. Dieses berauschende Getränk sollst du im Heiligtum für Jahwe ausgießen." },
      { number: 8, text: "Das zweite Lamm sollst du am späten Nachmittag zurichten. Mit dem gleichen Speisopfer wie am Morgen und dem dazugehörenden Trankopfer sollst du es bringen als Feueropfer angenehmen Geruchs für Jahwe.\"" },
      { number: 9, text: "\"Am Sabbat bringe zwei einjährige makellose Lämmer, dazu als Speisopfer viereinhalb Liter* Feinmehl, das mit Öl vermengt ist, und das dazugehörende Trankopfer.", heading: "Die Sabbat-Opfer", footnotes: ["viereinhalb Liter. Wörtlich: zwei Zehntel (Efa) = 4,4 Liter"] },
      { number: 10, text: "Es ist das Sabbat-Brandopfer, das an jedem Sabbat zusätzlich zum ständigen Brandopfer und dem dazugehörenden Trankopfer gebracht werden soll.\"" },
      { number: 11, text: "\"Am Anfang jedes Monats sollt ihr Jahwe ein Brandopfer bringen: zwei junge Stiere, einen Schafbock und sieben makellose einjährige Lämmer.", heading: "Die monatlichen Opfer" },
      { number: 12, text: "Zu jedem Stier gehören als Speisopfer sechseinhalb Liter* mit Öl vermengtes Feinmehl und zu jedem Schafbock viereinhalb Liter.", footnotes: ["secheinhalb Liter. Wörtlich: drei Zehntel (Efa) = 6,6 Liter"] },
      { number: 13, text: "Auch zu jedem Lamm gehören als Speisopfer zwei Liter mit Öl vermengtes Feinmehl. Es ist ein Brandopfer zum angenehmen Geruch, ein Feueropfer für Jahwe." },
      { number: 14, text: "Dazu kommen noch die Trankopfer: Zum Stier gehören knapp zwei Liter* Wein, zum Schafbock ein guter Liter* und zum Lamm ein knapper Liter. Das ist das Brandopfer an jedem Neumondstag des Jahres.", footnotes: ["knapp zwei Liter. Wörtlich: ein halbes Hin = 1,9 Liter", "ein guter Liter. Wörtlich: ein Drittel Hin = 1,3 Liter"] },
      { number: 15, text: "Zusätzlich zum regelmäßigen Brand- und Trankopfer soll Jahwe ein Ziegenbock als Sündopfer gebracht werden.\"" },
      { number: 16, text: "\"Am 14. April* ist Passa für Jahwe.", heading: "Das Passaopfer", footnotes: ["April. Wörtlich: im 1. Monat."] },
      { number: 17, text: "Am 15. beginnt ein siebentägiges Fest, an dem ihr ungesäuerte Brotfladen essen sollt." },
      { number: 18, text: "Am ersten Tag sollt ihr euch zu einem heiligen Fest versammeln. Da muss jede Arbeit ruhen." },
      { number: 19, text: "Ihr sollt ein Feueropfer bringen, ein Brandopfer für Jahwe: zwei junge Stiere, einen Schafbock und sieben einjährige makellose Lämmer." },
      { number: 20, text: "Dazu als Speisopfer mit Öl vermengtes Feinmehl: sechseinhalb Liter für einen Stier und viereinhalb Liter für einen Schafbock" },
      { number: 21, text: "und für jedes der sieben Lämmer zwei Liter." },
      { number: 22, text: "Dazu kommt noch ein Ziegenbock als Sündopfer, um Sühne für euch zu erwirken." },
      { number: 23, text: "Diese Opfer sollen zusätzlich zu den normalen Morgen-Brandopfern dargebracht werden." },
      { number: 24, text: "Dieselben Opfer sollt ihr jeden Tag sieben Tage lang bringen, als eine Feueropferspeise, zum angenehmen Geruch für Jahwe. Das soll zusätzlich zu dem regelmäßigen Brandopfer und den dazugehörenden Trankopfern dargebracht werden." },
      { number: 25, text: "Am siebten Tag sollt ihr euch zu einem heiligen Fest versammeln. Da muss jede Arbeit ruhen.\"" },
      { number: 26, text: "\"Am Tag der Erstlingsfrüchte, wenn ihr Jahwe ein neues Speisopfer bringt, an eurem Wochenfest, sollt ihr zu einer heiligen Versammlung zusammenkommen. Da muss jede Arbeit ruhen.", heading: "Das Wochenfest" },
      { number: 27, text: "Ihr sollt zum angenehmen Geruch für Jahwe ein Brandopfer bringen: zwei junge Stiere, einen Schafbock, sieben einjährige Lämmer" },
      { number: 28, text: "und das dazugehörige Speisopfer, mit Öl vermengtes Feinmehl: sechseinhalb Liter zu jedem Stier, viereinhalb Liter zu jedem Schafbock" },
      { number: 29, text: "und je zwei Liter für jedes der sieben Lämmer." },
      { number: 30, text: "Dazu kommt noch ein Ziegenbock, um Sühne für euch zu erwirken." },
      { number: 31, text: "Das soll zusätzlich zu dem regelmäßigen Brandopfer und den dazugehörenden Speisopfern mit den Trankopfern dargebracht werden. Alles soll makellos sein.\"" },
    ] },
    { number: 29, verses: [
      { number: 1, text: "\"Am 1. Oktober* sollt ihr euch zu einem heiligen Fest versammeln. Da muss jede Arbeit ruhen. Es soll ein Tag des Signalblasens für euch sein.", heading: "Der Neujahrstag", footnotes: ["Oktober. Wörtlich: des 7. Monats."] },
      { number: 2, text: "Ihr sollt ein Brandopfer zum angenehmen Geruch für Jahwe bringen: einen jungen Stier, einen Schafbock und sieben makellose einjährige Lämmer," },
      { number: 3, text: "und das dazugehörige Speisopfer, mit Öl vermengtes Feinmehl: sechseinhalb Liter zu jedem Stier, viereinhalb Liter zu jedem Schafbock" },
      { number: 4, text: "und zwei Liter für jedes der sieben Lämmer." },
      { number: 5, text: "Dazu kommt noch ein Ziegenbock als Sündopfer, um Sühne für euch zu erwirken." },
      { number: 6, text: "Das soll zusätzlich zu dem Brandopfer am Neumondstag und dem dazugehörenden Speisopfer gebracht werden und dem regelmäßigen Brandopfer und den dazugehörenden Speis- und Trankopfern nach den für sie geltenden Vorschriften als angenehmen Geruch, ein Feueropfer für Jahwe.\"" },
      { number: 7, text: "\"Am 10. Oktober* sollt ihr euch zu einem heiligen Fest versammeln und euch demütigen. Da muss jede Arbeit ruhen.", heading: "Der Versöhnungstag", footnotes: ["Oktober. Wörtlich: des 7. Monats."] },
      { number: 8, text: "Ihr sollt Jahwe ein Brandopfer zum angenehmen Geruch bringen: einen jungen Stier, einen Schafbock und sieben makellose einjährige Lämmer," },
      { number: 9, text: "und das dazugehörige Speisopfer, mit Öl vermengtes Feinmehl: sechseinhalb Liter zu jedem Stier, viereinhalb Liter zu jedem Schafbock" },
      { number: 10, text: "und zwei Liter für jedes der sieben Lämmer." },
      { number: 11, text: "Dazu kommt noch ein Ziegenbock als Sündopfer, zusätzlich zu dem Sündopfer der Versöhnung und dem regelmäßigen Brandopfer und den dazugehörenden Speis- und Trankopfern.\"" },
      { number: 12, text: "\"Am 15. Oktober sollt ihr euch zu einem heiligen Fest versammeln. Da muss jede Arbeit ruhen. Sieben Tage lang sollt ihr Jahwe ein Fest feiern.", heading: "Das Laubhüttenfest" },
      { number: 13, text: "Ihr sollt ihm ein Brandopfer bringen, ein Feueropfer zum angenehmen Geruch: dreizehn junge Stiere, zwei Schafböcke und vierzehn makellose einjährige Lämmer," },
      { number: 14, text: "und das dazugehörige Speisopfer, mit Öl vermengtes Feinmehl: sechseinhalb Liter zu jedem der dreizehn Stiere, viereinhalb Liter zu jedem der beiden Schafböcke" },
      { number: 15, text: "und zwei Liter für jedes der vierzehn Lämmer." },
      { number: 16, text: "Dazu kommt noch ein Ziegenbock als Sündopfer, zusätzlich zu dem regelmäßigen Brandopfer und den dazugehörenden Speis- und Trankopfern." },
      { number: 17, text: "Am zweiten Tag sollt ihr zwölf junge Stiere, zwei Schafböcke und vierzehn makellose einjährige Lämmer bringen," },
      { number: 18, text: "und das dazugehörige Speis- und Trankopfer zu den Stieren, den Schafböcken und den Lämmern entsprechend ihrer Anzahl und Vorschrift." },
      { number: 19, text: "Dazu kommt noch ein Ziegenbock als Sündopfer, zusätzlich zu dem regelmäßigen Brandopfer und den dazugehörenden Speis- und Trankopfern." },
      { number: 20, text: "Am dritten Tag sollt ihr elf junge Stiere, zwei Schafböcke und vierzehn makellose einjährige Lämmer bringen," },
      { number: 21, text: "und das dazugehörige Speis- und Trankopfer zu den Stieren, den Schafböcken und den Lämmern entsprechend ihrer Anzahl und Vorschrift." },
      { number: 22, text: "Dazu kommt noch ein Ziegenbock als Sündopfer, zusätzlich zu dem regelmäßigen Brandopfer und den dazugehörenden Speis- und Trankopfern." },
      { number: 23, text: "Am vierten Tag sollt ihr zehn Stiere, zwei Schafböcke und vierzehn makellose einjährige Lämmer bringen," },
      { number: 24, text: "und das dazugehörige Speis- und Trankopfer zu den Stieren, den Schafböcken und den Lämmern entsprechend ihrer Anzahl und Vorschrift." },
      { number: 25, text: "Dazu kommt noch ein Ziegenbock als Sündopfer, zusätzlich zu dem regelmäßigen Brandopfer und den dazugehörenden Speis- und Trankopfern." },
      { number: 26, text: "Am fünften Tag sollt ihr neun Stiere, zwei Schafböcke und vierzehn makellose einjährige Lämmer bringen," },
      { number: 27, text: "und das dazugehörige Speis- und Trankopfer zu den Stieren, den Schafböcken und den Lämmern entsprechend ihrer Anzahl und Vorschrift." },
      { number: 28, text: "Dazu kommt noch ein Ziegenbock als Sündopfer, zusätzlich zu dem regelmäßigen Brandopfer und den dazugehörenden Speis- und Trankopfern." },
      { number: 29, text: "Am sechsten Tag sollt ihr acht Stiere, zwei Schafböcke und vierzehn makellose einjährige Lämmer bringen," },
      { number: 30, text: "und das dazugehörige Speis- und Trankopfer zu den Stieren, den Schafböcken und den Lämmern entsprechend ihrer Anzahl und Vorschrift." },
      { number: 31, text: "Dazu kommt noch ein Ziegenbock als Sündopfer, zusätzlich zu dem regelmäßigen Brandopfer und den dazugehörenden Speis- und Trankopfern." },
      { number: 32, text: "Am siebten Tag sollt ihr sieben Stiere, zwei Schafböcke und vierzehn makellose einjährige Lämmer bringen," },
      { number: 33, text: "und das dazugehörige Speis- und Trankopfer zu den Stieren, den Schafböcken und den Lämmern entsprechend ihrer Anzahl und Vorschrift." },
      { number: 34, text: "Dazu kommt noch ein Ziegenbock als Sündopfer, zusätzlich zu dem regelmäßigen Brandopfer und den dazugehörenden Speis- und Trankopfern." },
      { number: 35, text: "Am achten Tag sollt ihr euch zu einem heiligen Fest versammeln. Da muss jede Arbeit ruhen." },
      { number: 36, text: "Ihr sollt ein Brandopfer bringen, ein Feueropfer für Jahwe zum angenehmen Geruch: einen Stier, einen Schafbock und sieben makellose einjährige Lämmer," },
      { number: 37, text: "und das dazugehörige Speis- und Trankopfer zu dem Stier, dem Schafbock und den Lämmern entsprechend ihrer Anzahl und Vorschrift." },
      { number: 38, text: "Dazu kommt noch ein Ziegenbock als Sündopfer, zusätzlich zu dem regelmäßigen Brandopfer und den dazugehörenden Speis- und Trankopfern." },
      { number: 39, text: "Das sollt ihr an euren Festtagen Jahwe opfern, zusätzlich zu dem, was ihr gelobt und was ihr freiwillig gebt an Brand- und Speisopfern, an Trank- und Freudenopfern.\"" },
    ] },
    { number: 30, verses: [
      { number: 1, text: "Mose sagte den Israeliten alles genauso, wie Jahwe es ihm geboten hatte." },
      { number: 2, text: "Mose sagte zu den Stammeshäuptern der Israeliten: \"Folgendes hat Jahwe geboten:", heading: "Die Gültigkeit von Gelübden" },
      { number: 3, text: "Wenn ein Mann Jahwe etwas gelobt oder einen Eid ablegt, sich von etwas zu enthalten, dann darf er sein Wort nicht brechen. Er muss alles genauso machen, wie er es ausgesprochen hat." },
      { number: 4, text: "Wenn eine Frau Jahwe etwas gelobt oder ein Enthaltungsgelübde auf sich nimmt und sie ist noch ledig und lebt im Haus ihres Vaters," },
      { number: 5, text: "dann ist ihr Gelübde gültig, wenn ihr Vater, sobald er davon hört, keinen Einspruch erhebt." },
      { number: 6, text: "Hat ihr Vater aber an dem Tag, als er davon hörte, seine Zustimmung versagt, so sind alle Gelübde und Enthaltungen, die sie sich auferlegt hat, ungültig. Jahwe wird ihr vergeben, weil ihr Vater seine Zustimmung versagt hat." },
      { number: 7, text: "Heiratet sie einen Mann, während sie durch ein Gelübde oder ein unbedachtes Wort gebunden ist," },
      { number: 8, text: "dann ist ihr Gelübde gültig, wenn ihr Mann, sobald er davon hört, keinen Einspruch erhebt." },
      { number: 9, text: "Wenn ihr Mann aber am gleichen Tag, an dem er davon hört, seine Zustimmung verweigert, setzt er das Gelübde oder das unbedachte Wort außer Kraft und Jahwe wird ihr vergeben." },
      { number: 10, text: "Aber das Gelübde einer Witwe oder einer Geschiedenen ist in allem gültig." },
      { number: 11, text: "Wenn eine verheiratete Frau etwas gelobt oder ein Enthaltungsgelübde auf sich nimmt" },
      { number: 12, text: "und ihr Mann sagt nichts dagegen, dann gelten alle ihre Gelübde." },
      { number: 13, text: "Wenn ihr Mann aber am gleichen Tag, an dem er davon hörte, sie ausdrücklich aufgehoben hat, dann ist alles, was seine Frau gelobt hat, ungültig geworden. Ihr Mann hat ihre Gelübde aufgehoben und Jahwe wird ihr vergeben." },
      { number: 14, text: "Ihr Mann kann jedes Gelübde und jeden Eid, der sie zu einer Enthaltung verpflichtet, bestätigen oder außer Kraft setzen." },
      { number: 15, text: "Schweigt ihr Mann dazu bis zum nächsten Tag, bestätigt er alle ihre Gelübde." },
      { number: 16, text: "Wenn er sie aber ausdrücklich aufhebt, nachdem er davon gehört hat, muss er die Folgen tragen.\"" },
      { number: 17, text: "Das sind die Anweisungen, die Jahwe Mose gegeben hat. Sie gelten für einen Mann gegenüber seiner Frau und für einen Vater gegenüber seiner Tochter, solange sie noch bei ihm zu Hause ist." },
    ] },
    { number: 31, verses: [
      { number: 1, text: "Jahwe sagte zu Mose:", heading: "Die Bestrafung der Midianiter (31)\nDer Krieg" },
      { number: 2, text: "\"Bestrafe die Midianiter für das, was sie Israel angetan haben. Danach wirst du mit deinen Vorfahren vereint werden.\"" },
      { number: 3, text: "Daraufhin sagte Mose zum Volk: \"Ein Teil eurer Männer soll sich zum Kriegsdienst bewaffnen. Sie werden gegen die Midianiter ziehen, um die Rache Jahwes an ihnen zu vollstrecken." },
      { number: 4, text: "Von jedem Stamm sollen 1000 Mann in den Kampf ziehen.\"" },
      { number: 5, text: "So wählten sie aus jedem Stamm der vielen Israeliten tausend Kämpfer aus, sodass ein Heer von 12.000 Mann zusammenkam." },
      { number: 6, text: "Mose schickte auch Pinhas, den Sohn des Priesters Eleasar, mit den heiligen Geräten und den Signaltrompeten zum Heer." },
      { number: 7, text: "Sie kämpften gegen Midian, wie Jahwe es Mose befohlen hatte, und brachten alle Männer um," },
      { number: 8, text: "auch die fünf Könige der Midianiter: Ewi, Rekem, Zur, Hur und Reba. Auch Bileam Ben-Beor töteten sie." },
      { number: 9, text: "Die Frauen und Kinder der Midianiter nahmen sie gefangen. Sie erbeuteten ihre Viehherden und ihren ganzen Besitz." },
      { number: 10, text: "Doch all ihre Städte und Dörfer brannten sie nieder." },
      { number: 11, text: "Die ganze Beute, auch alle Menschen und das Vieh" },
      { number: 12, text: "brachten sie zu Mose und Eleasar und der Gemeinschaft der Israeliten ins Lager in der moabitischen Steppe am Jordan bei Jericho." },
      { number: 13, text: "Mose ging ihnen mit Eleasar und den Oberhäuptern der Gemeinschaft entgegen." },
      { number: 14, text: "Als er sie sah, wurde er zornig über die Befehlshaber des Heeres, die Führer der Tausend- und Hundertschaften, die aus dem Krieg kamen." },
      { number: 15, text: "Er sagte zu ihnen: \"Warum habt ihr die Frauen am Leben gelassen?" },
      { number: 16, text: "Gerade sie brachten doch auf den Rat Bileams die Israeliten dazu, in der Sache mit dem Peor von Jahwe abzufallen, sodass sein schwerer Schlag die Gemeinde Jahwes traf." },
      { number: 17, text: "Tötet jetzt alle Kinder männlichen Geschlechts und alle Frauen, die schon mit einem Mann geschlafen haben." },
      { number: 18, text: "Alle Mädchen, die noch nicht mit einem Mann Verkehr hatten, dürft ihr für euch am Leben lassen." },
      { number: 19, text: "Ihr bleibt sieben Tage vor dem Lager. Und jeder, der einen Menschen erschlagen hat, und jeder, der einen Toten berührte, soll sich am dritten und am siebten Tag samt seinen Gefangenen entsündigen." },
      { number: 20, text: "Auch alle Kleidungsstücke, alles Lederzeug und alles, was aus Ziegenhaar oder Holz hergestellt ist, muss entsündigt werden.\"" },
      { number: 21, text: "Der Priester Eleasar sagte den Männern, die aus dem Kampf heimgekehrt waren: \"Folgende gesetzliche Verordnung hat Jahwe uns durch Mose gegeben:" },
      { number: 22, text: "Alle Beutestücke aus Gold, Silber, Bronze, Eisen, Zinn und Blei," },
      { number: 23, text: "also alles, was nicht verbrennen kann, sollt ihr ins Feuer halten und anschließend mit dem Reinigungswasser entsündigen. Alles, was verbrennen kann, sollt ihr ins Wasser tauchen." },
      { number: 24, text: "Am siebten Tag sollt ihr eure Kleidung waschen. Dann seid ihr wieder rein und dürft ins Lager zurückkommen.\"" },
      { number: 25, text: "Jahwe sagte zu Mose:", heading: "Die Verteilung der Beute" },
      { number: 26, text: "\"Zähle mit dem Priester Eleasar und den Oberen der Gemeinschaft, was als Beute mitgebracht worden ist, Menschen und Vieh." },
      { number: 27, text: "Dann gib die eine Hälfte der Beute denen, die ins Feld gezogen sind und gekämpft haben, und die andere Hälfte der ganzen übrigen Gemeinschaft." },
      { number: 28, text: "Von den Kämpfern, die in den Krieg gezogen sind, sollst du darüber hinaus eine Abgabe für Jahwe erheben: je eins von 500 bei Menschen, Rindern, Eseln oder Kleinvieh." },
      { number: 29, text: "Das sollst du von der Hälfte nehmen, die ihnen zusteht, und es dem Priester Eleasar als Opfer für Jahwe übergeben." },
      { number: 30, text: "Von der Hälfte, die den übrigen Israeliten zusteht, sollst du je eins von 50 erheben, bei Menschen und Vieh, bei Rindern, Eseln, Schafen oder Ziegen, und sollst es den Leviten übergeben, die den Dienst an der Wohnung Jahwes tun.\"" },
      { number: 31, text: "Mose und Eleasar machten, was Jahwe Mose befohlen hatte." },
      { number: 32, text: "Die Zählung der gesamten Beute erbrachte 675.000 Schafe und Ziegen," },
      { number: 33, text: "72.000 Rinder," },
      { number: 34, text: "61.000 Esel" },
      { number: 35, text: "und 32.000 Menschen, unberührte Mädchen." },
      { number: 36, text: "Die Hälfte davon, der Anteil für die Kämpfer, betrug 337.500 Stück Kleinvieh" },
      { number: 37, text: "und die Abgabe für Jahwe: 675 Stück;" },
      { number: 38, text: "36.000 Rinder und die Abgabe für Jahwe: 72;" },
      { number: 39, text: "30.500 Esel und die Abgabe für Jahwe: 61;" },
      { number: 40, text: "16.000 Menschen und die Abgabe für Jahwe: 32 Menschen." },
      { number: 41, text: "Mose übergab diesen Anteil dem Priester Eleasar als Opfergabe für Jahwe, so wie Jahwe es ihm befohlen hatte." },
      { number: 42, text: "Von der Hälfte für die Israeliten, die Mose von der Beute der Kämpfer abgezogen hatte," },
      { number: 43, text: "also von der Hälfte, die für die Gemeinschaft bestimmt war, nämlich 337 500 Stück Kleinvieh," },
      { number: 44, text: "36.000 Rinder," },
      { number: 45, text: "30.500 Esel" },
      { number: 46, text: "und 16.000 Menschen," },
      { number: 47, text: "von dieser den Israeliten gehörenden Hälfte nahm Mose von 50 Menschen und Tieren je eins heraus und übergab sie den Leviten, die den Dienst an der Wohnung Jahwes versahen, so wie Jahwe es ihm befohlen hatte." },
      { number: 48, text: "Da traten die Befehlshaber des Heeres an Mose heran, die Führer der Tausend- und Hundertschaften," },
      { number: 49, text: "und sagten zu ihm: \"Deine Diener haben die Krieger gezählt, die unter unserem Befehl standen, und es fehlt nicht ein einziger Mann." },
      { number: 50, text: "So bringen wir das als Opfergabe für Jahwe, was jeder von uns an Goldschmuck gefunden hat: Schrittkettchen und Armspangen, Siegelringe, Ohrringe und Halsschmuck, um Sühne vor Jahwe für uns zu erwirken.\"" },
      { number: 51, text: "Mose und der Priester Eleasar nahmen das Gold von ihnen an, alles kunstvoll gearbeitete Schmuckstücke." },
      { number: 52, text: "Das Gold, das sie als Abgabe von den Führern der Tausend- und Hundertschaften für Jahwe erhoben, hatte ein Gewicht von fast 193 Kilogramm*.", footnotes: ["193 Kilogramm. Wörtlich: 16 750 Schekel, das Schekel zu 11,5 Gramm gerechnet."] },
      { number: 53, text: "Die Krieger hatten auch jeder für sich Beute gemacht." },
      { number: 54, text: "Mose und der Priester Eleasar nahmen das Gold von den Oberen und brachten es in das Zelt der Gottesbegegnung. Es sollte vor Jahwe die Erinnerung an die Israeliten wach halten." },
    ] },
    { number: 32, verses: [
      { number: 1, text: "Die Stämme Ruben und Gad hatten sehr große Viehherden. Als sie nun das Land Jaser* und Gilead* sahen, erkannten sie, dass die Gegend für Herden geeignet war.", heading: "Vorbereitungen zum Einmarsch (32-36)\nDie Verteilung des Ostjordanlandes", footnotes: ["Jaser bezeichnete hier vielleicht die Gegend um die Stadt Jaser (4. Mose 21,32) in der Nähe des heutigen Amman.", "Gilead bezeichnete das mittlere, manchmal auch das ganze Ostjordanland."] },
      { number: 2, text: "Da kamen die Gaditen und Rubeniten und sagten zu Mose, zu dem Priester Eleasar und den Fürsten der Gemeinschaft:" },
      { number: 3, text: "\"Atarot und Dibona, Jaser und Nimra, Heschbon und Elale, Sibma, Nebo und Beon," },
      { number: 4, text: "das Land, das Jahwe für die Gemeinschaft des Volkes Israel erobert hat, ist gutes Weideland. Und deine Diener haben Herden." },
      { number: 5, text: "Wenn wir dein Wohlwollen gefunden haben, dann lass doch dieses Land deinen Dienern als Eigentum geben! Lass uns nicht über den Jordan ziehen!\"" },
      { number: 6, text: "Mose sagte zu den Gaditen und Rubeniten: \"Sollen etwa eure Brüder in den Kampf ziehen, während ihr hier bleibt?" },
      { number: 7, text: "Warum wollt ihr die Israeliten davon abhalten, in das Land hinüberzuziehen, das Jahwe ihnen gegeben hat?" },
      { number: 8, text: "Das haben ja schon eure Väter getan, als ich sie von Kadesch-Barnea losschickte, um das Land auszukundschaften." },
      { number: 9, text: "Sie kamen bis ins Traubental und sahen sich das Land an. Und dann nahmen sie den Israeliten den Mut, sodass sie nicht in das Land ziehen wollten, das Jahwe ihnen gegeben hatte." },
      { number: 10, text: "Damals entflammte Jahwes Zorn und er schwor:" },
      { number: 11, text: "'Keiner der Männer, die aus Ägypten gezogen und jetzt älter als 20 Jahre sind, wird das Land sehen, das ich Abraham, Isaak und Jakob unter Eid versprochen habe. Denn sie haben nicht treu zu mir gehalten." },
      { number: 12, text: "Ausgenommen sind nur Kaleb Ben-Jefunne aus der Sippe Kenas und Josua Ben-Nun, die treu zu mir gehalten haben.'" },
      { number: 13, text: "So traf Jahwes Zorn die Israeliten, und er ließ sie vierzig Jahre lang in der Wüste umherirren, bis diese ganze Generation aufgerieben war, die getan hatte, was vor Jahwe böse ist." },
      { number: 14, text: "Seht doch, nun seid ihr an die Stelle eurer Väter getreten, eine Brut von sündigen Männern, um den glühenden Zorn Jahwes gegen Israel noch zu vermehren." },
      { number: 15, text: "Wenn ihr euch von ihm abkehrt, wird er das Volk noch länger in der Wüste lassen, und ihr habt es dann zugrunde gerichtet!\"" },
      { number: 16, text: "Da traten sie näher zu Mose und sagten: \"Wir wollen ja nur Gehege für unser Kleinvieh hier bauen und feste Städte für unsere Familien." },
      { number: 17, text: "Wir selbst wollen für den Kampf bewaffnet vor den Israeliten herziehen, bis wir sie an ihren Ort gebracht haben. Nur unsere Familien sollen wegen der Bewohner des Landes in den befestigten Städten bleiben." },
      { number: 18, text: "Wir kehren nicht in unsere Häuser zurück, bis jeder Israelit seinen Erbbesitz erhalten hat." },
      { number: 19, text: "Wir verlangen keinen Erbbesitz auf der anderen Seite des Jordan, wenn wir ihn diesseits des Jordan im Osten bekommen.\"" },
      { number: 20, text: "Da sagte Mose zu ihnen: \"Wenn ihr das tut, wenn ihr euch vor Jahwe bewaffnet" },
      { number: 21, text: "und jeder Bewaffnete von euch vor Jahwe über den Jordan zieht, bis er seine Feinde vor sich her vertrieben hat" },
      { number: 22, text: "und das Land für Jahwe unterworfen ist, wenn ihr erst danach zurückkehrt, sollt ihr frei sein von den Verpflichtungen gegenüber Jahwe und Israel, und dieses Land hier soll vor Jahwe euch gehören." },
      { number: 23, text: "Wenn ihr das aber nicht so tut, versündigt ihr euch gegen Jahwe. Und seid gewiss, dass eure Sünde euch einholen wird." },
      { number: 24, text: "Baut euch feste Städte für eure Familien und Gehege für eure Schafe und tut, was ihr versprochen habt!\"" },
      { number: 25, text: "Da sagten die Gaditen und Rubeniten zu Mose: \"Deine Diener werden tun, was du verlangst." },
      { number: 26, text: "Unsere Kinder, unsere Frauen, unsere Herden und unser ganzes Vieh werden in den Städten Gileads bleiben." },
      { number: 27, text: "Deine Diener aber werden alle zum Heeresdienst gerüstet sein und vor Jahwe hinüberziehen in den Kampf, wie du gesagt hast.\"" },
      { number: 28, text: "Daraufhin gab Mose dem Priester Eleasar, Josua Ben-Nun und den Oberhäuptern der Stämme Israels die Anweisung:" },
      { number: 29, text: "\"Wenn die Gaditen und Rubeniten vor Jahwe zum Kampf gerüstet mit euch den Jordan überschreiten und wenn das Land euch unterworfen sein wird, dann sollt ihr ihnen das Land Gilead zum Eigentum geben." },
      { number: 30, text: "Ziehen sie aber nicht bewaffnet mit euch hinüber, dann müssen sie sich unter euch im Land Kanaan ansässig machen.\"" },
      { number: 31, text: "Da erwiderten die Gaditen und Rubeniten: \"Was Jahwe deinen Dienern gesagt hat, wollen wir tun." },
      { number: 32, text: "Für unseren Erbbesitz diesseits des Jordan werden wir vor Jahwe gerüstet in das Land Kanaan hinüberziehen.\"" },
      { number: 33, text: "So gab Mose den Gaditen, den Rubeniten und dem halben Stamm des Josefssohns Manasse das Gebiet des Amoriterkönigs Sihon und das Gebiet des Königs Og von Baschan, das ganze Land mit seinen Städten und den dazugehörenden Gebieten." },
      { number: 34, text: "Die Gaditen befestigten die Städte Dibona, Atarot und Aroer," },
      { number: 35, text: "Atrot-Schofan, Jaser, Jogboha," },
      { number: 36, text: "Bet-Nimra und Bet-Haran und errichteten Einfriedungen für ihre Herden." },
      { number: 37, text: "Die Männer des Stammes Ruben befestigten die Städte Heschbon, Elale, Kirjatajim," },
      { number: 38, text: "Nebo, Baal-Meon und Sibma und gaben ihnen andere Namen." },
      { number: 39, text: "Die Nachkommen von Machir Ben-Manasse zogen nach Gilead. Sie eroberten es und vertrieben die Amoriter dort." },
      { number: 40, text: "Mose gab ihnen Gilead als Besitz, und sie siedelten sich dort an." },
      { number: 41, text: "Jaïr vom Stamm Manasse eroberte eine Reihe von Zeltdörfern und nannte sie \"Zeltdörfer Jaïrs\"." },
      { number: 42, text: "Nobach eroberte Kenach und dessen Tochterstädte und nannte es nach seinem eigenen Namen: Nobach." },
    ] },
    { number: 33, verses: [
      { number: 1, text: "Es folgt das Verzeichnis der Lagerplätze der Israeliten, die unter der Führung von Mose und Aaron nach Heerscharen geordnet aus dem Land Ägypten ausgezogen waren.", heading: "Die Lagerplätze des Wüstenzugs" },
      { number: 2, text: "Nach Jahwes Befehl schrieb Mose die Stationen ihrer Wanderung auf." },
      { number: 3, text: "Am 15. April*, am Morgen nach dem Passamahl, brachen sie voller Mut* und vor den Augen aller Ägypter in Ramses* auf.", footnotes: ["April. Wörtlich: des 1. Monats. Es war im Jahr 1446 v.Chr.", "voller Mut. Wörtlich: mit erhobener Hand.", "Ramses. Stadt im östlichen Nildelta, etwa 30 km südlich von Tanis/Zoan."] },
      { number: 4, text: "Die Ägypter begruben währenddessen ihre Erstgeborenen, die Jahwe unter ihnen erschlagen hatte. Auch an ihren Göttern hatte Jahwe Strafgerichte vollstreckt." },
      { number: 5, text: "Von Ramses zogen die Israeliten nach Sukkot*, wo sie das erste Mal ihr Lager aufschlugen.", footnotes: ["Sukkot war vielleicht das heutige Tell el-Maskuta im Wadi Tumilat, 14 km westlich von Ismailia im Nordosten Ägyptens."] },
      { number: 6, text: "Von Sukkot zogen sie weiter nach Etam* am Rand der Wüste.", footnotes: ["Etam. Das ägyptische Wort bedeutet \"Festung\". Wahrscheinlich handelte es sich um eine der Festungen, die die Ostgrenze von Ägypten bewachten."] },
      { number: 7, text: "Von dort wandten sie sich nach Pi-Hahirot gegenüber von Baal-Zefon und schlugen ihr Lager bei Migdol* auf.", footnotes: ["Migdol ist das semitische Wort für Festung. Alle genannten Orte können Festungen meinen, die in der Nähe des heutigen Suez-Kanals lagen. Pi-Hahirot und Migdol werden in ägyptischen Quellen genannt."] },
      { number: 8, text: "Dann zogen sie mitten durch das Meer und weiter drei Tagesmärsche weit durch die Wüste von Etam bis nach Mara*.", footnotes: ["Mara, Bitterwasser, war eine Oase, ungefähr drei Tagereisen von Ägypten entfernt, vielleicht identisch mit Ain Hawarah, 75 km südöstlich von Suez."] },
      { number: 9, text: "Von dort zogen sie nach Elim*, wo es zwölf Wasserquellen und siebzig Palmen gab.", footnotes: ["Elim lag elf Kilometer südlich von Ain Hawarah im gut bewässerten Tal von Gharandel. Die Identifikation der Orte hängt allerdings davon ab, welcher Berg mit dem Sinai identifiziert wird."] },
      { number: 10, text: "Von Elim zogen sie weiter und schlugen ihr Lager am Schilfmeer* auf.", footnotes: ["Schilfmeer. Hier ist nicht der Schauplatz des Meerwunders von Vers 8 und 2. Mose 14,2 gemeint, sondern der Golf von Akaba, der zum Roten Meer gehört."] },
      { number: 11, text: "Von dort aus zogen sie in die Wüste Sin*", footnotes: ["Die Wüste Sin lag wahrscheinlich im südwestlichen Teil der Sinaihalbinsel in dem Gebiet, das heute Debbet-er-Ramleh genannt wird."] },
      { number: 12, text: "und von dort nach Dofka," },
      { number: 13, text: "dann nach Alusch" },
      { number: 14, text: "und schließlich nach Refidim, wo sie kein Trinkwasser fanden." },
      { number: 15, text: "Von Refidim zogen sie weiter und schlugen ihr Lager in der Wüste Sinai auf." },
      { number: 16, text: "Von dort ging es nach Kibrot-Taawa," },
      { number: 17, text: "dann weiter nach Hazerot" },
      { number: 18, text: "und schließlich nach Ritma*.", footnotes: ["Ritma befand sich offenbar ganz in der Nähe von Kadesch-Barnea, wo Israel etwa ein Jahr blieb."] },
      { number: 19, text: "Von Ritma zogen sie weiter nach Rimmon-Perez," },
      { number: 20, text: "nach Libna" },
      { number: 21, text: "und Rissa." },
      { number: 22, text: "Ihr nächstes Lager schlugen sie in Kehelata auf," },
      { number: 23, text: "dann am Berg Schefer," },
      { number: 24, text: "in Harada," },
      { number: 25, text: "Makhelot" },
      { number: 26, text: "und Tahat." },
      { number: 27, text: "Von dort ging es nach Tatach," },
      { number: 28, text: "dann nach Mitka," },
      { number: 29, text: "nach Haschmona," },
      { number: 30, text: "nach Moserot," },
      { number: 31, text: "Bene-Jaakan," },
      { number: 32, text: "Hor-Gidgad," },
      { number: 33, text: "Jotbata," },
      { number: 34, text: "Abrona" },
      { number: 35, text: "und Ezjon-Geber." },
      { number: 36, text: "Dann kamen sie nach Kadesch in der Wüste Zin" },
      { number: 37, text: "und schlugen ihr Lager schließlich am Berg Hor an der Grenze des Landes Edom auf." },
      { number: 38, text: "Dort stieg der Priester Aaron nach dem Befehl Jahwes auf den Berg Hor und starb. Das war im 40. Jahr nach dem Auszug aus Ägypten, am 1. August.*", footnotes: ["August. Wörtlich: des 5. Monats. Es war im Jahr 1406 v.Chr."] },
      { number: 39, text: "Aaron war 123 Jahre alt, als er auf dem Berg Hor starb." },
      { number: 40, text: "Der Kanaaniterkönig von Arad, das lag im Süden des Landes Kanaan, hörte vom Kommen der Israeliten." },
      { number: 41, text: "Diese brachen vom Berg Hor auf und kamen nach Zalmona." },
      { number: 42, text: "Von dort kamen sie nach Punon," },
      { number: 43, text: "dann nach Obot" },
      { number: 44, text: "und schließlich nach Ije-Abarim im Gebiet von Moab." },
      { number: 45, text: "Von Ijim zogen sie weiter nach Dibon-Gad," },
      { number: 46, text: "von dort nach Almon-Diblatajim" },
      { number: 47, text: "und von dort zum Gebirge Abarim, östlich von Nebo." },
      { number: 48, text: "Vom Gebirge Abarim zogen sie weiter in das moabitische Steppengebiet der Jordanebene gegenüber von Jericho." },
      { number: 49, text: "Ihr Lager erstreckte sich von Bet-Jeschimot* bis Abel-Schittim*.", footnotes: ["Bet-Jeschimot. Sieben Kilometer nordöstlich vom Toten Meer.", "Abel-Schittim. 14 km nordöstlich vom Toten Meer."] },
      { number: 50, text: "Dort im moabitischen Steppengebiet der Jordanebene, gegenüber von Jericho, befahl Jahwe Mose,", heading: "Anweisungen für die Verteilung des Landes" },
      { number: 51, text: "den Israeliten zu sagen: \"Wenn ihr über den Jordan in das Land Kanaan zieht," },
      { number: 52, text: "müsst ihr alle seine Bewohner vertreiben, alle ihre Götzenbilder und Bildwerke vernichten und ihre Höhenheiligtümer zerstören." },
      { number: 53, text: "Nehmt das Land in Besitz und lasst euch dort nieder, denn ich habe es euch als Eigentum gegeben." },
      { number: 54, text: "Durchs Los soll es euren Sippen als Erbbesitz zugeteilt werden. Einem großen Stamm sollt ihr einen großen Grundbesitz zuteilen, einem kleinen Stamm einen kleinen. Durchs Los sollt ihr es unter die Stämme eurer Väter verteilen." },
      { number: 55, text: "Wenn ihr die Einwohner des Landes aber nicht vor euch her vertreibt, dann werden die, die ihr von ihnen übrig lasst, zu Splittern in euren Augen und zu Stacheln in euren Seiten. Sie werden euch in dem Land, in dem ihr wohnt, bedrängen." },
      { number: 56, text: "Dann werde ich mit euch machen, was ich mit ihnen machen wollte.\"" },
    ] },
    { number: 34, verses: [
      { number: 1, text: "Jahwe wies Mose an,", heading: "Die Grenzen von Israels Gebiet" },
      { number: 2, text: "den Israeliten zu befehlen: \"Wenn ihr in das Land Kanaan kommt, dann liegt euer Erbbesitz in folgenden Grenzen:" },
      { number: 3, text: "Im Süden wird euer Land von der Wüste Zin und dem Gebiet von Edom begrenzt, sodass eure Südgrenze im Osten vom Ende des Salzmeeres* ausgeht.", footnotes: ["Salzmeer. Gemeint ist das Tote Meer, das einen Salzgehalt von 25% hat, sodass kein Fisch darin leben kann."] },
      { number: 4, text: "Dann soll sie südlich vom Skorpionensteig abbiegen, sich nach Zin hinüberziehen und bis südlich von Kadesch-Barnea* weiterlaufen. Dann soll sie weiter über Hazar-Addar* nach Azmon gehen", footnotes: ["Kadesch-Barnea. Ort an der Südgrenze Kanaans, etwa 80 km südwestlich von Beerscheba.", "Hazar-Addar.Die Festung liegt etwa 82 km südlich von Beerscheba."] },
      { number: 5, text: "und von dort bis zum Bach Ägyptens*, der zum Mittelmeer hin ausläuft.", footnotes: ["Bach Ägyptens.Heute: Wadi El-Arisch."] },
      { number: 6, text: "Eure Westgrenze soll das Küstengebiet des großen Meeres sein." },
      { number: 7, text: "Eure Nordgrenze sollt ihr vom großen Meer bis zum Berg Hor ziehen" },
      { number: 8, text: "und weiter bis dorthin, wo es nach Hamat geht. In Zadad soll sie enden." },
      { number: 9, text: "Dann soll die Grenze über Sifron weitergehen und bei Hazar-Enan enden." },
      { number: 10, text: "Die Ostgrenze verläuft von Hazar-Enan bis Schefam" },
      { number: 11, text: "über den Ort Ribla, östlich von Ajin, bis zu den Höhenzügen am Ostufer des Sees Kinneret*.", footnotes: ["Kinneret. Früherer Name des Sees Gennesaret."] },
      { number: 12, text: "Dann soll die Grenze zum Jordan hinabgehen und am Salzmeer enden. Das soll euer Land in seinen Grenzen sein.\"" },
      { number: 13, text: "Da befahl Mose den Israeliten: \"Das ist das Land, das ihr durch Los als Erbbesitz erhalten sollt. Jahwe hat befohlen, es den neuneinhalb Stämmen zu geben.", heading: "Weitere Anweisungen für die Verteilung des Landes" },
      { number: 14, text: "Denn der Stamm der Rubeniten mit ihren Familien, der Stamm der Gaditen mit ihren Familien und die Hälfte des Stammes Manasse haben ihren Erbbesitz schon erhalten," },
      { number: 15, text: "und zwar auf der Ostseite des Jordan, gegenüber von Jericho.\"" },
      { number: 16, text: "Jahwe sagte zu Mose:" },
      { number: 17, text: "\"Der Priester Eleasar und Josua Ben-Nun sollen das Land an Israel verteilen." },
      { number: 18, text: "Zur Verteilung sollt ihr noch je einen der Oberen aus jedem Stamm hinzuziehen." },
      { number: 19, text: "Es sind folgende Männer: Kaleb Ben-Jefunne für den Stamm Juda," },
      { number: 20, text: "Schemuël Ben-Ammihud für den Stamm Simeon," },
      { number: 21, text: "Elidad Ben-Kislon für den Stamm Benjamin," },
      { number: 22, text: "Fürst Bukki Ben-Jogli für den Stamm Dan," },
      { number: 23, text: "für die Josefstämme: Fürst Hanniël Ben-Efod für den Stamm Manasse" },
      { number: 24, text: "und Fürst Kemuël Ben-Schiftan für den Stamm Efraïm," },
      { number: 25, text: "Fürst Elizafan Ben-Parnach für den Stamm Sebulon," },
      { number: 26, text: "Fürst Paltiël Ben-Asan für den Stamm Issachar," },
      { number: 27, text: "Fürst Ahihud Ben-Schelomi für den Stamm Ascher" },
      { number: 28, text: "und Fürst Pedahel Ben-Ammihud für den Stamm Naftali.\"" },
      { number: 29, text: "Das sind die, denen Jahwe befahl, den Israeliten ihren Erbbesitz im Land Kanaan auszuteilen." },
    ] },
    { number: 35, verses: [
      { number: 1, text: "Im moabitischen Steppengebiet der Jordanebene gegenüber von Jericho sagte Jahwe zu Mose:", heading: "Leviten- und Asylstädte" },
      { number: 2, text: "\"Befiehl den Israeliten, dass sie den Leviten von ihrem Erbbesitz Städte zum Wohnen geben. Auch Weideland soll um die Städte herum sein." },
      { number: 3, text: "Die Städte sollen ihnen als Wohnsitz gehören und die dazugehörenden Weideflächen sollen für ihr Vieh, ihre Herden und für alle ihre Tiere bestimmt sein." },
      { number: 4, text: "Die Weideflächen, die ihr den Leviten gebt, sollen von der Stadtmauer aus jeweils etwa 500 Meter* hinaus reichen.", footnotes: ["500 Meter. Wörtlich: 1000 Ellen."] },
      { number: 5, text: "Dann messt ihr außerhalb der Stadt parallel zur Ost-, Süd-, West- und Nordseite je 1000 Meter* ab, sodass die Stadt in der Mitte dieser Fläche liegt. Das alles soll den Leviten als Weidefläche* vor den Städten dienen.", footnotes: ["1000 Meter. Wörtlich: 2000 Ellen.", "Die Weideflächen sind nicht als großes Quadrat um die Stadt zu denken, sondern als vier rechteckige Stücke von je 1000 x 500 Meter, die an der Stadtmauer angesetzt wurden, wobei sie je nach Länge der Mauer nach einer Seite überstehen konnten. Die Juden haben übrigens aus diesen Maßangaben die Länge eines Sabbatweges (Apostelgeschichte 1,12) bestimmt."] },
      { number: 6, text: "Von den Städten, die ihr den Leviten gebt, sollen sechs Asylstädte sein, in die jeder fliehen kann, der unabsichtlich einen Menschen getötet hat. 42 andere Städte müsst ihr ihnen noch geben," },
      { number: 7, text: "insgesamt also 48 Städte mit ihren Weideflächen." },
      { number: 8, text: "Wenn ihr die Städte an die Leviten abgebt, sollt ihr von einem großen Stamm viele nehmen und von einem kleinen wenige. Jeder Stamm soll entsprechend der Größe seines Erbbesitzes Städte an die Leviten abgeben.\"" },
      { number: 9, text: "Jahwe befahl Mose," },
      { number: 10, text: "den Israeliten zu sagen: \"Wenn ihr über den Jordan ins Land Kanaan zieht," },
      { number: 11, text: "sollt ihr Asylstädte bestimmen, in die jeder fliehen kann, der unabsichtlich einen Menschen getötet hat." },
      { number: 12, text: "Die Städte sollen als Zuflucht vor dem Bluträcher dienen, damit der Totschläger nicht umgebracht wird, bevor er in der Gemeinschaft vor Gericht gestanden hat." },
      { number: 13, text: "Sechs Asylstädte sollt ihr haben," },
      { number: 14, text: "drei diesseits des Jordan und drei im Land Kanaan." },
      { number: 15, text: "Diese Städte sollen sowohl einem Israeliten als auch einem Fremden als Zuflucht dienen. Jeder, der einen Menschen aus Versehen erschlagen hat, soll dahin fliehen können." },
      { number: 16, text: "Wenn aber jemand einen anderen mit einem eisernen Gegenstand schlägt, sodass dieser daran stirbt, dann ist er ein Mörder und muss mit dem Tod bestraft werden." },
      { number: 17, text: "Ebenso ist es, wenn er einen Stein in die Hand nimmt, durch den man sterben kann, und ihn damit schlägt," },
      { number: 18, text: "oder mit einem Gegenstand aus Holz, durch den man sterben kann. Wenn der Geschlagene stirbt, ist er ein Mörder und muss mit dem Tod bestraft werden." },
      { number: 19, text: "Der Bluträcher* soll den Mörder töten, sobald er ihn trifft.", footnotes: ["Bluträcher. Die Sühne eines Mordes stand damals dem nächsten Verwandten des Toten zu."] },
      { number: 20, text: "Wer einen anderen aus Hass stößt oder ihm in böser Absicht etwas nachwirft, sodass er stirbt," },
      { number: 21, text: "oder wer ihn aus Feindschaft mit der Hand schlägt, sodass er stirbt, muss mit dem Tod bestraft werden. Er ist ein Mörder. Der Bluträcher soll den Mörder töten, sobald er ihn trifft." },
      { number: 22, text: "Wenn er ihn aber aus Unachtsamkeit ohne feindliche Absicht gestoßen oder ohne Hintergedanken einen Gegenstand auf ihn geworfen hat," },
      { number: 23, text: "oder wenn er, ohne ihn zu sehen, einen Stein auf ihn fallen ließ, der einen Menschen töten kann, sodass er starb, obwohl er nicht sein Feind war und ihn nicht schädigen wollte," },
      { number: 24, text: "dann soll die Gemeinschaft zwischen dem Totschläger und dem Bluträcher nach diesen Rechtsbestimmungen entscheiden." },
      { number: 25, text: "Die Gemeinschaft soll den Totschläger aus der Hand des Bluträchers retten und ihn in die Asylstadt zurückbringen, in die er geflohen ist. In ihr soll er bleiben bis zum Tod des Hohen Priesters, den man mit dem heiligen Öl salbte." },
      { number: 26, text: "Verlässt der Totschläger aber das Gebiet seiner Asylstadt, in die er geflohen ist," },
      { number: 27, text: "und der Bluträcher findet ihn und tötet ihn dort, dann lädt er keine Blutschuld auf sich." },
      { number: 28, text: "Denn der Totschläger muss bis zum Tod des Hohen Priesters in seiner Asylstadt bleiben. Erst danach darf er auf seinen Grund und Boden zurückkehren." },
      { number: 29, text: "Das soll als Rechtsordnung für euch gelten in jeder Generation und überall, wo ihr wohnt." },
      { number: 30, text: "Wenn jemand einen Menschen erschlägt, soll man auf die Aussage von Zeugen hin den Mörder töten. Doch durch die Aussage eines einzigen Zeugen darf niemand sterben." },
      { number: 31, text: "Ihr dürft kein Lösegeld annehmen für das Leben eines Mörders, er muss hingerichtet werden." },
      { number: 32, text: "Auch von einem, der in seine Asylstadt geflohen ist, dürft ihr kein Lösegeld annehmen, damit er noch vor dem Tod des Priesters nach Hause zurückkehren kann." },
      { number: 33, text: "Ihr dürft das Land, in dem ihr lebt, nicht entweihen! Denn Blut entweiht das Land. Und dem Land kann für einen Mord keine Sühne erwirkt werden, außer durch das Blut dessen, der den Mord begangen hat." },
      { number: 34, text: "Lasst das Land, in dem ihr lebt, nicht unrein werden! Denn auch ich, Jahwe, wohne mitten unter euch.\"" },
    ] },
    { number: 36, verses: [
      { number: 1, text: "Die Familienoberhäupter der Nachkommen von Gilead Ben-Machir, dem Enkel Manasses aus der Josefsippe, kamen zu Mose und den Oberhäuptern des Volkes", heading: "Das Gesetz für Erbtöchter" },
      { number: 2, text: "und sagten: \"Jahwe hat dir, unserem Herrn, befohlen, das Land durchs Los unter die Israeliten aufzuteilen. Er hat dir auch befohlen, den Erbbesitz unseres Verwandten Zelofhad seinen Töchtern zu geben." },
      { number: 3, text: "Wenn sie aber nun einen Mann aus einem der anderen Stämme Israels heiraten, dann wird ihr Land dem Erbbesitz unserer Vorfahren entzogen und in den Besitz des Stammes kommen, zu dem sie dann gehören." },
      { number: 4, text: "Und wenn dann das Jubeljahr für Israel kommt, wird ihr Erbbesitz endgültig in den Besitz des Stammes übergehen, in den sie eingeheiratet haben, und ihr Besitz wird dem Erbbesitz unserer Vorfahren entzogen.\"" },
      { number: 5, text: "Da befahl Mose nach Anweisung Jahwes den Israeliten: \"Die Männer vom Stamm der Söhne Josefs haben Recht." },
      { number: 6, text: "Folgendes hat Jahwe bestimmt: Die Töchter Zelofhads dürfen den heiraten, der ihnen gefällt. Doch es muss ein Mann sein, der zu einer der Sippen ihres Stammes gehört," },
      { number: 7, text: "damit kein Grundbesitz von einem Stamm zum anderen übergeht. Jeder Israelit soll mit dem Erbbesitz seines väterlichen Stammes verbunden bleiben." },
      { number: 8, text: "Und jede Tochter, die in einem der Stämme Israels zu Erbbesitz kommt, soll einen Mann aus den Sippen ihres väterlichen Stammes heiraten, damit jeder Israelit den Erbbesitz seiner Vorfahren behält." },
      { number: 9, text: "Es darf kein Erbbesitz von einem Stamm auf den anderen übergehen. Jeder Stamm der Israeliten soll mit seinem Erbbesitz verbunden bleiben.\"" },
      { number: 10, text: "Die Töchter Zelofhads machten es so, wie Jahwe es Mose gesagt hatte." },
      { number: 11, text: "Machla, Tirza, Hogla, Milka und Noa heirateten ihre Vettern," },
      { number: 12, text: "Männer aus den Sippen der Nachkommen des Josefsohns Manasse. So blieb ihr Erbbesitz bei den Sippen ihres väterlichen Stammes." },
      { number: 13, text: "Das sind die Gebote und Rechte, die Jahwe den Israeliten durch Mose im moabitischen Steppengebiet der Jordanebene gegenüber von Jericho gegeben hat." },
    ] },
  ],
};